/* Build 45.8.12.3 — Maltese precision guard.
   Interactive Replay question/answer copy is synchronized from the already
   approved canonical Maltese question pack whenever the English and Maltese
   text were previously identical. Correct flags and option order are never changed. */
function mdmSyncInteractiveReplayMalteseFromCanonical(){
 try{
  const bank=window.MDM_MT_QUESTIONS||{}, replays=window.INTERACTIVE_REPLAY_MVP||{};
  Object.entries(replays).forEach(([id,scene])=>{
   const mt=bank[id]; if(!scene||!mt)return;
   if(scene.prompt&&mt.question_mt&&String(scene.prompt.mt||'')===String(scene.prompt.en||''))scene.prompt.mt=mt.question_mt;
   const enQ=(Q||[]).find(q=>String(q.id)===String(id));
   const enAns=Array.isArray(enQ?.answers)?enQ.answers:[];
   const mtAns=Array.isArray(mt.answers_mt)?mt.answers_mt:[];
   if(Array.isArray(scene.choices)&&enAns.length===mtAns.length){
    scene.choices.forEach(choice=>{
     if(!choice?.label)return;
     const j=enAns.findIndex(x=>String(x).trim()===String(choice.label.en||'').trim());
     if(j>=0&&mtAns[j]&&String(choice.label.mt||'')===String(choice.label.en||''))choice.label.mt=mtAns[j];
    });
    const correct=scene.choices.find(c=>c?.correct);
    const correctMt=correct?.label?.mt||'';
    scene.choices.forEach(choice=>{
     if(!choice?.consequence||String(choice.consequence.mt||'')!==String(choice.consequence.en||''))return;
     choice.consequence.mt=choice.correct
      ? `Għażla korretta. ${mt.explanation_mt||''}`.trim()
      : `Din mhix it-tweġiba korretta.${correctMt?` It-tweġiba korretta hija: ${correctMt}.`:''}`;
    });
   }
  });
 }catch(_){/* precision guard must never block startup */}
}

