function interactiveReplayText(value){
 if(!value)return '';
 return lang3(value.it||value.en||'',value.en||value.it||'',value.mt||value.en||value.it||'');
}
function interactiveReplayConfig(questionId){return INTERACTIVE_REPLAY_MVP[String(questionId||'')]||null}
function interactiveReplayRecord(questionId,choice,decisionMs,attempts,score){
 const current=Object.assign({sessions:0,choiceAttempts:0,correctChoices:0,wrongChoices:0,totalDecisionMs:0,bestDecisionMs:0,totalScore:0,bestScore:0,lastScore:0,lastDecisionMs:0,lastChoice:'',lastCorrect:false,unresolved:false,lastAt:''},errorReplay.interactive?.[questionId]||{});
 current.choiceAttempts+=1;
 current.lastChoice=String(choice?.id||'');
 current.lastCorrect=Boolean(choice?.correct);
 current.lastDecisionMs=Math.max(0,Math.round(decisionMs||0));
 current.lastAt=new Date().toISOString();
 if(choice?.correct){
  current.sessions+=1;
  current.correctChoices+=1;
  current.totalDecisionMs+=current.lastDecisionMs;
  current.bestDecisionMs=current.bestDecisionMs?Math.min(current.bestDecisionMs,current.lastDecisionMs):current.lastDecisionMs;
  current.lastScore=Math.max(0,Math.min(100,Math.round(score||0)));
  current.totalScore+=current.lastScore;
  current.bestScore=Math.max(current.bestScore,current.lastScore);
  current.unresolved=false;
 }else{
  current.wrongChoices+=1;
  current.unresolved=true;
 }
 errorReplay.interactive[questionId]=current;
 errorReplaySave();
 return current;
}
function interactiveReplayStats(){
 const ids=Object.keys(INTERACTIVE_REPLAY_MVP);
 const rows=ids.map(id=>({id,...Object.assign({sessions:0,choiceAttempts:0,correctChoices:0,wrongChoices:0,totalDecisionMs:0,bestDecisionMs:0,totalScore:0,bestScore:0,lastScore:0,lastDecisionMs:0,lastCorrect:false,unresolved:false},errorReplay.interactive?.[id]||{})}));
 const sessions=rows.reduce((n,row)=>n+Number(row.sessions||0),0);
 const attempts=rows.reduce((n,row)=>n+Number(row.choiceAttempts||0),0);
 const correct=rows.reduce((n,row)=>n+Number(row.correctChoices||0),0);
 const totalScore=rows.reduce((n,row)=>n+Number(row.totalScore||0),0);
 const totalDecisionMs=rows.reduce((n,row)=>n+Number(row.totalDecisionMs||0),0);
 const unresolved=rows.filter(row=>row.unresolved).length;
 return {rows,sessions,attempts,correct,accuracy:attempts?Math.round(correct/attempts*100):0,averageScore:sessions?Math.round(totalScore/sessions):0,averageDecisionMs:sessions?Math.round(totalDecisionMs/sessions):0,unresolved};
}
function interactiveReplayRecoveryBonus(questionId){
 const row=errorReplay.interactive?.[questionId];
 if(!row||(!row.choiceAttempts&&!row.sessions))return 0;
 let bonus=0;
 if(row.unresolved||row.lastCorrect===false)bonus+=14;
 const score=Number(row.lastScore||0);
 if(row.sessions&&score<70)bonus+=10;
 else if(row.sessions&&score<85)bonus+=5;
 return bonus;
}
function interactiveReplayWeakest(){
 const stats=interactiveReplayStats();
 return stats.rows.filter(row=>row.choiceAttempts||row.sessions).sort((a,b)=>Number(b.unresolved)-Number(a.unresolved)||Number(a.lastScore||0)-Number(b.lastScore||0)||Number(b.wrongChoices||0)-Number(a.wrongChoices||0))[0]||null;
}
