let interactiveReplayOpenCategory='';
let interactiveReplayCategoryReturnScroll=0;
function interactiveReplayCategoryLabel(def){return interactiveReplayText(def?.label||{})}
function interactiveReplayCategoryRows(){
 const ids=Object.keys(INTERACTIVE_REPLAY_MVP);
 const rows=INTERACTIVE_REPLAY_CATEGORIES.map(def=>{
  const categorySet=new Set(def.categories);
  const categoryIds=ids.filter(id=>{const q=errorReplayQuestion(id);return q&&categorySet.has(String(q.category||''))});
  const completed=categoryIds.filter(id=>Number(errorReplay.interactive?.[id]?.sessions||0)>0).length;
  return {...def,ids:categoryIds,completed};
 }).filter(row=>row.ids.length);
 return rows;
}
function interactiveReplayQuestionButtonHtml(id,compact=false){
 const q=errorReplayQuestion(id),row=errorReplay.interactive?.[id]||{};
 return `<button type="button" class="${compact?'interactive-replay-preview-question':''}" data-interactive-replay-open="${esc(id)}"><strong>${esc(id)}</strong><span>${esc(q?questionText(q):id)}</span>${compact?'':`<small>${row.sessions?`${esc(lang3('Ultimo punteggio','Last score','L-aħħar punteġġ'))}: ${Number(row.lastScore||0)}/100`:esc(lang3('Da provare','Try it','Biex tipprova'))}</small>`}</button>`;
}
function interactiveReplayCategoryCardHtml(row){
 const preview=row.ids.slice(0,5).map(id=>interactiveReplayQuestionButtonHtml(id,true)).join('');
 const remaining=Math.max(0,row.ids.length-5);
 return `<article class="interactive-replay-category-card"><div class="interactive-replay-category-top"><div><span>${esc(lang3('CATEGORIA','CATEGORY','KATEGORIJA'))}</span><h3>${esc(interactiveReplayCategoryLabel(row))}</h3></div><div class="interactive-replay-category-count"><b>${row.ids.length}</b><small>${esc(lang3('domande','questions','mistoqsijiet'))}</small></div></div><div class="interactive-replay-category-progress"><strong>${row.completed}</strong><span>${esc(lang3('completate','completed','kompluti'))}</span><i aria-hidden="true"></i><strong>${row.ids.length-row.completed}</strong><span>${esc(lang3('da provare','to try','biex tipprova'))}</span></div><div class="interactive-replay-category-preview">${preview}</div>${remaining?`<p class="interactive-replay-category-more">+ ${remaining} ${esc(lang3('altre domande','more questions','mistoqsijiet oħra'))}</p>`:''}<button type="button" class="interactive-replay-category-open" data-interactive-category-open="${esc(row.id)}"><span>${esc(lang3('Apri categoria','Open category','Iftaħ il-kategorija'))}</span><b aria-hidden="true">→</b></button></article>`;
}
