function registrationPayload(){
 const form=collectProfileForm();
 const error=validatePersonalProfile(form);
 if(error){toast(error);return null}
 const saved=savePersonalProfile(form);
 saved.emailPreparedAt=new Date().toISOString();
 save(USER_PROFILE,saved);
 const subject=`Malta Driving Master - Registrazione ${saved.registrationId}`;
 const body=[
  `DESTINATARIO: ${ADMIN_EMAIL}`,
  '',
  'NUOVA REGISTRAZIONE MALTA DRIVING MASTER',
  '',
  `Nome: ${saved.firstName}`,
  `Cognome: ${saved.lastName}`,
  `E-mail utente: ${saved.email}`,
  `Indirizzo: ${saved.address||'Non indicato'}`,
  `Età: ${saved.age||'Non indicata'}`,
  `Aggiornamenti via e-mail: ${saved.updatesConsent?'Sì':'No'}`,
  `Consenso registrazione: ${saved.privacyConsent?'Sì':'No'}`,
  `Codice registrazione: ${saved.registrationId}`,
  'Versione app: Build 08.2',
  `Data: ${new Date().toLocaleString()}`,
  '',
  'Messaggio preparato volontariamente dall’utente attraverso Malta Driving Master.'
 ].join('\n');
 return {saved,subject,body};
}
function mailtoRegistration(payload){
 return `mailto:${ADMIN_EMAIL}?subject=${encodeURIComponent(payload.subject)}&body=${encodeURIComponent(payload.body)}`;
}
function gmailRegistration(payload){
 return `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(ADMIN_EMAIL)}&su=${encodeURIComponent(payload.subject)}&body=${encodeURIComponent(payload.body)}`;
}
function openRegistrationMail(){
 const payload=registrationPayload();
 if(!payload)return;
 toast(t('mailOpening'));
 window.location.href=mailtoRegistration(payload);
}
function openRegistrationGmail(){
 const payload=registrationPayload();
 if(!payload)return;
 toast(t('gmailOpening'));
 const url=gmailRegistration(payload);
 const opened=window.open(url,'_blank','noopener,noreferrer');
 if(!opened)window.location.href=url;
}
async function shareRegistration(){
 const payload=registrationPayload();
 if(!payload)return;
 const text=`A: ${ADMIN_EMAIL}\n\n${payload.body}`;
 if(!navigator.share){
  toast(t('shareUnavailable'));
  return;
 }
 try{
  await navigator.share({
   title:payload.subject,
   text
  });
 }catch(error){
  if(error?.name!=='AbortError')toast(t('shareUnavailable'));
 }
}
async function copyRegistration(){
 const payload=registrationPayload();
 if(!payload)return;
 const text=`A: ${ADMIN_EMAIL}\nOggetto: ${payload.subject}\n\n${payload.body}`;
 try{
  if(navigator.clipboard&&window.isSecureContext){
   await navigator.clipboard.writeText(text);
  }else{
   const area=document.createElement('textarea');
   area.value=text;
   area.setAttribute('readonly','');
   area.style.position='fixed';
   area.style.opacity='0';
   document.body.appendChild(area);
   area.select();
   document.execCommand('copy');
   area.remove();
  }
  toast(t('registrationCopied'));
 }catch{
  window.prompt(`${t('copyFallback')} ${ADMIN_EMAIL}`,text);
 }
}
function allowedQuestionMap(map){
 const allowed=new Set(Q.map(q=>q.id));
 return Object.fromEntries(Object.entries(map||{}).filter(([id])=>allowed.has(id)));
}
if(progress.bankVersion!==TAG_BANK_VERSION){
 progress=Object.assign({},progress,{
   seen:allowedQuestionMap(progress.seen),
   correct:allowedQuestionMap(progress.correct),
   wrong:allowedQuestionMap(progress.wrong),
   favourites:(progress.favourites||[]).filter(id=>Q.some(q=>q.id===id)),
   review:allowedQuestionMap(progress.review),
   bankVersion:TAG_BANK_VERSION
 });
 save(STORAGE,progress);
 const oldSession=load(SESSION,null);
 if(oldSession?.list?.some(item=>!Q.some(q=>q.id===item.id)))localStorage.removeItem(SESSION);
}
function t(key,...args){const v=(ui[settings.lang]||ui.en)[key]??ui.en[key]??key;return typeof v==='function'?v(...args):v}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function localized(obj,base){return obj[base+'_'+settings.lang]||obj[settings.lang]||obj[base+'_en']||obj.en||obj[base]||''}
function isItalianAssisted(){return settings.lang==='it'}
function isMalteseMode(){return settings.lang==='mt'}
function lang3(it,en,mt){return settings.lang==='it'?it:settings.lang==='mt'?mt:en}


/* Build 42.0.0 — MDM COUNTRY PACK ENGINE
   Malta remains the only installed/active jurisdiction in this build.
   The engine centralises exam rules and validates future pack manifests without pretending that foreign content is installed. */
const COUNTRY_PACK_SCHEMA='mdm-country-pack-v1';
const COUNTRY_PACK_SCHEMA_VERSION=1;
let countryPackEngineState=Object.assign({candidate:null,lastCheck:''},load(COUNTRY_PACK_ENGINE_KEY,{}));
function countryPackReplayCount(){try{return Object.keys(INTERACTIVE_REPLAY_MVP||{}).length}catch(_){return 0}}
function countryPackLanguageCoverage(questionField,answersField){
 const total=Math.max(1,Q.length),done=Q.filter(q=>String(q?.[questionField]||'').trim()&&Array.isArray(q?.[answersField])&&Array.isArray(q?.answers)&&q[answersField].length===q.answers.length).length;
 return {done,total,pct:Math.round(done/total*100)};
}
function maltaCountryPack(){
 return {
  schema:COUNTRY_PACK_SCHEMA,schemaVersion:COUNTRY_PACK_SCHEMA_VERSION,packId:'MT-LPTV-TAG',packVersion:'1.0.0',countryCode:'MT',countryName:'Malta',flag:'🇲🇹',status:'active_verified',
  authority:'Transport Malta',programme:'LPTV TAG',drivingSide:'left',examLanguage:'en',supportLanguages:['it','mt'],
  exam:{questionCount:35,durationMinutes:45,passPercent:85,quotas:{safety:9,customer:5,road:17,eco:4}},
  runtime:{questionCount:Q.length,categoryCount:new Set(Q.map(q=>q.category).filter(Boolean)).size,interactiveReplayCount:countryPackReplayCount(),bankVersion:TAG_BANK_VERSION},
  modules:['question-bank','exam-rules','language-packs','interactive-replay','driving-twin','evidence-passport','school-command-center','instructor-studio']
 };
}
function countryEngineActivePack(){return maltaCountryPack()}
function countryPackExamConfig(){return countryEngineActivePack().exam}
function countryPackExamSeconds(){return Math.max(60,Number(countryPackExamConfig().durationMinutes||45)*60)}
function countryPackPassCorrect(total){const pct=Number(countryPackExamConfig().passPercent||85);return Math.ceil(Math.max(1,Number(total)||countryPackExamConfig().questionCount)*pct/100)}
function countryPackExamPassed(correct,total){return Number(correct)>=countryPackPassCorrect(total)}
function countryPackHomeLine(){const p=countryEngineActivePack();return settings.lang==='it'?`${p.countryName} • ${p.programme} • English • Italiano • Malti`:settings.lang==='mt'?`${p.countryName} • ${p.programme} • English • Malti`:`${p.countryName} • ${p.programme} • English`}
function countryPackTemplate(){return {schema:COUNTRY_PACK_SCHEMA,schemaVersion:COUNTRY_PACK_SCHEMA_VERSION,packId:'COUNTRY-PROGRAMME',packVersion:'0.1.0',countryCode:'XX',countryName:'Country name',authority:'Licensing authority',programme:'Driving programme',drivingSide:'left',examLanguage:'en',supportLanguages:[],exam:{questionCount:0,durationMinutes:0,passPercent:0,quotas:{}},content:{questions:0,categories:0,interactiveReplay:0},requiredPayloads:['questions','translations','exam-rules','replay-mapping','twin-taxonomy','legal-metadata']};}
function countryPackValidateManifest(m){
 const gates=[];const ok=(id,label,pass,detail)=>gates.push({id,label,pass:Boolean(pass),detail:String(detail||'')});
 const obj=m&&typeof m==='object'?m:{};
 ok('schema',lang3('Schema MDM','MDM schema','Schema MDM'),obj.schema===COUNTRY_PACK_SCHEMA,`${obj.schema||'—'}`);
 ok('identity',lang3('Identità Paese','Country identity','Identità tal-pajjiż'),/^[A-Z]{2}$/.test(String(obj.countryCode||''))&&String(obj.countryName||'').trim().length>1,`${obj.countryCode||'—'} · ${obj.countryName||'—'}`);
 ok('version',lang3('Versione pack','Pack version','Verżjoni tal-pack'),/^\d+\.\d+\.\d+/.test(String(obj.packVersion||'')),obj.packVersion||'—');
 ok('authority',lang3('Autorità e programma','Authority & programme','Awtorità u programm'),String(obj.authority||'').trim().length>1&&String(obj.programme||'').trim().length>1,`${obj.authority||'—'} · ${obj.programme||'—'}`);
 const ex=obj.exam||{};ok('exam',lang3('Regole esame','Exam rules','Regoli tal-eżami'),Number(ex.questionCount)>0&&Number(ex.durationMinutes)>0&&Number(ex.passPercent)>0&&Number(ex.passPercent)<=100,`${Number(ex.questionCount)||0} · ${Number(ex.durationMinutes)||0} min · ${Number(ex.passPercent)||0}%`);
 ok('side',lang3('Lato di guida','Driving side','Naħa tas-sewqan'),['left','right'].includes(obj.drivingSide),obj.drivingSide||'—');
 ok('language',lang3('Lingua d’esame','Exam language','Lingwa tal-eżami'),/^[a-z]{2}(-[A-Z]{2})?$/.test(String(obj.examLanguage||'')),obj.examLanguage||'—');
 const hasPayload=obj.content&&Number(obj.content.questions)>0&&Array.isArray(obj.requiredPayloads)&&obj.requiredPayloads.length>=4;
 ok('payload',lang3('Payload didattici','Learning payloads','Payloads tat-tagħlim'),hasPayload,hasPayload?lang3('Dichiarati nel manifest','Declared in manifest','Iddikjarati fil-manifest'):lang3('Manifest solo: contenuti non installati','Manifest only: content not installed','Manifest biss: kontenut mhux installat'));
 return {valid:gates.slice(0,7).every(g=>g.pass),activatable:gates.every(g=>g.pass),gates};
}
function countryPackRuntimeCheck(){
 const p=countryEngineActivePack(),it=countryPackLanguageCoverage('question_it','answers_it'),mt=countryPackLanguageCoverage('question_mt','answers_mt');
 const quotas=p.exam.quotas||{},quotaReady=Object.entries(quotas).every(([topic,n])=>Q.filter(q=>topicIdFor(q)===topic).length>=Number(n));
 const sumQuota=Object.values(quotas).reduce((a,b)=>a+Number(b||0),0);
 const gates=[
  {label:lang3('Schema e identità','Schema & identity','Schema u identità'),pass:p.schema===COUNTRY_PACK_SCHEMA&&p.countryCode==='MT',detail:`${p.packId} · v${p.packVersion}`},
  {label:lang3('Banca domande','Question bank','Bank tal-mistoqsijiet'),pass:Q.length>=p.exam.questionCount,detail:`${Q.length} · ${p.runtime.categoryCount} ${lang3('categorie','categories','kategoriji')}`},
  {label:lang3('Regole esame collegate','Exam rules wired','Regoli tal-eżami marbuta'),pass:quotaReady&&sumQuota===p.exam.questionCount,detail:`${p.exam.questionCount}Q · ${p.exam.durationMinutes} min · ${p.exam.passPercent}%`},
  {label:lang3('Italiano assistito','Italian support','Appoġġ bit-Taljan'),pass:it.pct===100,detail:`${it.done}/${it.total} · ${it.pct}%`},
  {label:lang3('Maltese pack','Maltese pack','Pack Malti'),pass:mt.pct===100,detail:`${mt.done}/${mt.total} · ${mt.pct}%`},
  {label:'Interactive Replay',pass:countryPackReplayCount()>=1,detail:`${countryPackReplayCount()} ${lang3('mappature attive','active mappings','mappings attivi')}`},
  {label:'Driving Twin + Evidence',pass:true,detail:lang3('Tassonomia condivisa dal pack attivo','Shared taxonomy from active pack','Tassonomija kondiviża mill-pack attiv')},
  {label:lang3('Moduli scuola','School modules','Moduli tal-iskola'),pass:true,detail:'Command Center · Instructor Intelligence · Instructor Studio'}
 ];
 countryPackEngineState.lastCheck=new Date().toISOString();save(COUNTRY_PACK_ENGINE_KEY,countryPackEngineState);return {pack:p,gates,it,mt,passed:gates.filter(g=>g.pass).length};
}
function countryPackManifestText(){return JSON.stringify(countryEngineActivePack(),null,2)}
function countryPackGateHtml(g){return `<article class="country-pack-gate ${g.pass?'pass':'fail'}"><span>${g.pass?'✓':'!'}</span><div><strong>${esc(g.label)}</strong><small>${esc(g.detail)}</small></div><b>${esc(g.pass?lang3('OK','PASS','OK'):lang3('DA COMPLETARE','NEEDS WORK','JONQOS'))}</b></article>`}
function countryPackCandidateHtml(){
 const c=countryPackEngineState.candidate;if(!c)return `<div class="country-pack-candidate-empty">${esc(lang3('Nessun nuovo Country Pack in validazione. Malta resta l’unico pack installato.','No new Country Pack is under validation. Malta remains the only installed pack.','L-ebda Country Pack ġdid mhu taħt validazzjoni. Malta jibqa’ l-uniku pack installat.'))}</div>`;
 const v=countryPackValidateManifest(c);return `<div class="country-pack-candidate"><div><span>${esc(c.flag||'🌐')}</span><div><small>${esc(lang3('PACK CANDIDATO','CANDIDATE PACK','PACK KANDIDAT'))}</small><h3>${esc(c.countryName||'—')} · ${esc(c.programme||'—')}</h3><p>${esc(c.countryCode||'—')} · v${esc(c.packVersion||'—')}</p></div></div><strong class="${v.activatable?'ready':'locked'}">${esc(v.activatable?lang3('PRONTO','READY','LEST'):lang3('NON ATTIVABILE','NOT ACTIVATABLE','MA JISTAX JIĠI ATTIVAT'))}</strong>${v.gates.map(countryPackGateHtml).join('')}<p class="country-pack-lock-note">${esc(v.activatable?lang3('Manifest e payload dichiarati. Prima dell’attivazione serve comunque l’audit MDM dei file reali.','Manifest and payloads declared. MDM still requires a real-file audit before activation.','Manifest u payloads iddikjarati. Qabel l-attivazzjoni xorta hemm bżonn audit MDM tal-fajls reali.'):lang3('Un manifest non può cambiare Paese da solo: domande, regole, lingue e Replay devono essere installati e verificati.','A manifest cannot switch country by itself: questions, rules, languages and Replays must be installed and verified.','Manifest waħdu ma jistax ibiddel pajjiż: mistoqsijiet, regoli, lingwi u Replay iridu jiġu installati u vverifikati.'))}</p><button class="btn secondary" id="countryPackRemoveCandidate">${esc(lang3('Rimuovi candidato','Remove candidate','Neħħi kandidat'))}</button></div>`;
}
function countryPackViewHtml(){
 let check;
 try{check=countryPackRuntimeCheck()}catch(err){
  console.error('[MDM Country Pack] runtime check failed',err);
  const p=countryEngineActivePack();
  check={pack:p,gates:[{label:lang3('Controllo runtime','Runtime check','Kontroll runtime'),pass:false,detail:lang3('Il pack è caricato; riprova il controllo.','The pack is loaded; run the check again.','Il-pack huwa mgħobbi; erġa’ agħmel il-kontroll.')}],it:{done:0,total:Q.length,pct:0},mt:{done:0,total:Q.length,pct:0},passed:0,runtimeError:true};
 }
 const p=check.pack,e=p.exam,passCorrect=countryPackPassCorrect(e.questionCount);
 return `<div class="section-title country-pack-title"><div><h2>🌍 MDM Country Pack Engine</h2><p>${esc(lang3('Un solo motore MDM, regole verificabili diverse per ogni Paese.','One MDM engine, verifiable rules for every country.','Magna MDM waħda, regoli verifikabbli differenti għal kull pajjiż.'))}</p></div><span class="badge official">Build ${esc(BUILD_VERSION)}</span></div>
 <section class="country-pack-hero"><small>${esc(lang3('ARCHITETTURA INTERNAZIONALE','INTERNATIONAL ARCHITECTURE','ARKITETTURA INTERNAZZJONALI'))}</small><h1>${esc(lang3('Cambia il Paese, non ricostruire l’app','Change the country, not the whole app','Ibdel il-pajjiż, mhux l-app kollha'))}</h1><p>${esc(lang3('Il Country Pack separa banca domande, regole d’esame, lingue, Replay e tassonomia del Twin dal motore MDM. Un pack incompleto non può essere attivato.','Country Pack separates the question bank, exam rules, languages, Replays and Twin taxonomy from the MDM engine. An incomplete pack cannot be activated.','Il-Country Pack jissepara l-bank tal-mistoqsijiet, ir-regoli tal-eżami, il-lingwi, ir-Replay u t-tassonomija tat-Twin mill-magna MDM. Pack mhux komplut ma jistax jiġi attivat.'))}</p></section>
 <section class="country-pack-metrics"><article><b>1</b><span>${esc(lang3('pack installato','installed pack','pack installat'))}</span></article><article><b>${Q.length}</b><span>${esc(lang3('domande attive','active questions','mistoqsijiet attivi'))}</span></article><article><b>${countryPackReplayCount()}</b><span>Interactive Replay</span></article></section>
 <section class="card country-pack-active"><div class="country-pack-active-head"><span class="country-pack-flag">${p.flag}</span><div><small>${esc(lang3('COUNTRY PACK ATTIVO','ACTIVE COUNTRY PACK','COUNTRY PACK ATTIV'))}</small><h2>${esc(p.countryName)} · ${esc(p.programme)}</h2><p>${esc(p.authority)} · ${esc(p.packId)} · v${esc(p.packVersion)}</p></div><b>${esc(lang3('VERIFICATO','VERIFIED','IVVERIFIKAT'))}</b></div><div class="country-pack-spec-grid"><article><strong>${esc(p.drivingSide==='left'?lang3('Sinistra','Left','Xellug'):lang3('Destra','Right','Lemin'))}</strong><span>${esc(lang3('lato di guida','driving side','naħa tas-sewqan'))}</span></article><article><strong>${esc(String(e.questionCount))}</strong><span>${esc(lang3('domande esame','exam questions','mistoqsijiet tal-eżami'))}</span></article><article><strong>${esc(String(e.durationMinutes))} min</strong><span>${esc(lang3('durata','duration','tul'))}</span></article><article><strong>${esc(String(e.passPercent))}%</strong><span>${esc(lang3(`soglia · ${passCorrect}/${e.questionCount}`,`pass · ${passCorrect}/${e.questionCount}`,`limitu · ${passCorrect}/${e.questionCount}`))}</span></article><article><strong>English</strong><span>${esc(lang3('lingua d’esame','exam language','lingwa tal-eżami'))}</span></article><article><strong>IT · MT</strong><span>${esc(lang3('lingue supporto','support languages','lingwi ta’ appoġġ'))}</span></article></div></section>
 <section class="card country-pack-rules"><div class="country-pack-section-head"><div><small>${esc(lang3('ENGINE LIVE','LIVE ENGINE','ENGINE LIVE'))}</small><h2>${esc(lang3('Le regole del pack guidano davvero l’esame','The pack rules now drive the exam','Ir-regoli tal-pack issa jmexxu l-eżami'))}</h2></div><span>⚙️</span></div><div class="country-pack-quota"><div><b>${e.quotas.safety}</b><span>${esc(lang3('Sicurezza','Safety','Sigurtà'))}</span></div><div><b>${e.quotas.customer}</b><span>${esc(lang3('Clienti','Customer','Klijenti'))}</span></div><div><b>${e.quotas.road}</b><span>${esc(lang3('Strada','Road','Triq'))}</span></div><div><b>${e.quotas.eco}</b><span>Eco</span></div></div><p>${esc(lang3('Build 42 centralizza quantità domande, durata, soglia di superamento e quote dei capitoli. I moduli esame leggono questi valori dal Country Pack attivo.','Build 42 centralises question count, duration, pass threshold and chapter quotas. Exam modules read these values from the active Country Pack.','Build 42 jiċċentralizza n-numru ta’ mistoqsijiet, it-tul, il-limitu tal-pass u l-kwoti tal-kapitli. Il-moduli tal-eżami jaqraw dawn il-valuri mill-Country Pack attiv.'))}</p></section>
 <section class="card country-pack-health"><div class="country-pack-section-head"><div><small>PACK HEALTH CHECK</small><h2>${check.passed}/${check.gates.length} ${esc(lang3('gate superati','gates passed','kontrolli mgħoddija'))}</h2><p>${esc(lang3('Nessun numero viene dichiarato “pronto” se il relativo dato non è presente.','Nothing is declared ready if its supporting data is missing.','Xejn ma jiġi ddikjarat lest jekk id-data ta’ appoġġ tkun nieqsa.'))}</p></div><span>🛡️</span></div><div class="country-pack-gates">${check.gates.map(countryPackGateHtml).join('')}</div><button class="btn" id="countryPackRecheck">${esc(lang3('Riesegui controllo','Run check again','Erġa’ agħmel il-kontroll'))}</button></section>
 <section class="card country-pack-anatomy"><div class="country-pack-section-head"><div><small>${esc(lang3('ANATOMIA DI UN PACK','PACK ANATOMY','ANATOMIJA TAL-PACK'))}</small><h2>${esc(lang3('Otto strati, un’unica identità Paese','Eight layers, one country identity','Tmien saffi, identità waħda tal-pajjiż'))}</h2></div><span>🧩</span></div><div class="country-pack-layer-grid"><article>🗂️<b>${esc(lang3('Banca domande','Question bank','Bank tal-mistoqsijiet'))}</b></article><article>🎯<b>${esc(lang3('Regole esame','Exam rules','Regoli tal-eżami'))}</b></article><article>🌐<b>Language Packs</b></article><article>🎬<b>Replay Mapping</b></article><article>🧬<b>Twin Taxonomy</b></article><article>🪪<b>Evidence Gates</b></article><article>🏫<b>School Workflow</b></article><article>⚖️<b>${esc(lang3('Metadati normativi','Legal metadata','Metadata legali'))}</b></article></div></section>
 <section class="card country-pack-builder"><div class="country-pack-section-head"><div><small>${esc(lang3('ONBOARDING NUOVO PAESE','NEW COUNTRY ONBOARDING','ONBOARDING TA’ PAJJIŻ ĠDID'))}</small><h2>${esc(lang3('Valida prima di installare','Validate before installing','Ivvalida qabel tinstalla'))}</h2><p>${esc(lang3('Incolla un manifest Country Pack. Build 42 verifica la struttura ma non attiva contenuti che non esistono realmente.','Paste a Country Pack manifest. Build 42 validates the structure but never activates content that is not really installed.','Waħħal manifest Country Pack. Build 42 tivvalida l-istruttura iżda qatt ma tattiva kontenut li mhux verament installat.'))}</p></div><span>🔐</span></div><textarea id="countryPackManifestInput" placeholder="{ &quot;schema&quot;: &quot;mdm-country-pack-v1&quot;, ... }"></textarea><div class="country-pack-actions"><button class="btn" id="countryPackValidate">${esc(lang3('Valida manifest','Validate manifest','Ivvalida manifest'))}</button><button class="btn secondary" id="countryPackCopyTemplate">${esc(lang3('Copia template','Copy template','Ikkopja template'))}</button><button class="btn secondary" id="countryPackCopyMalta">${esc(lang3('Copia manifest Malta','Copy Malta manifest','Ikkopja manifest Malta'))}</button></div><div id="countryPackCandidateBox">${countryPackCandidateHtml()}</div></section>
 <section class="country-pack-safety"><small>${esc(lang3('REGOLA DI SICUREZZA','SAFETY RULE','REGOLA TA’ SIGURTÀ'))}</small><h2>${esc(lang3('Mai “cambio Paese” con un semplice interruttore','Never switch country with a simple toggle','Qatt tibdel pajjiż b’toggle sempliċi'))}</h2><p>${esc(lang3('Il nuovo pack potrà diventare attivo solo dopo banca domande, regole d’esame, lingue, Replay e tassonomia verificati. Malta rimane intatta durante la preparazione di ogni nuovo Paese.','A new pack can become active only after its question bank, exam rules, languages, Replays and taxonomy are verified. Malta stays untouched while each new country is prepared.','Pack ġdid jista’ jsir attiv biss wara li l-bank tal-mistoqsijiet, ir-regoli tal-eżami, il-lingwi, ir-Replay u t-tassonomija jiġu vverifikati. Malta tibqa’ intatta waqt il-preparazzjoni ta’ kull pajjiż ġdid.'))}</p></section>`;
}

/* Build 45.0.0 — Multi-License Architecture
   License Pack is deliberately separate from Country Pack.
   Only payloads really installed and verified may become active. */
let licensePackEngineState=Object.assign({activeId:'MT-LPTV',inspectedId:'MT-LPTV',lastCheck:''},load(LICENSE_PACK_ENGINE_KEY,{}));
function licensePackSyncRuntime(p){
 if(!p||p.id!=='MT-C-CE')return p;
 try{
  const bank=p.questionBank||(p.questionBank={});
  const official=Number(bank.officialCount||386);
  const runtimeIds=new Set((Array.isArray(CCE_Q)?CCE_Q:[]).map(q=>String(q?.id||'')).filter(Boolean));
  const actual=runtimeIds.size;
  bank.currentCanonicalMatches=actual;
  bank.importedRuntimeCount=actual;
  bank.missingOfficial=Math.max(0,official-actual);
 }catch(_){ }
 return p;
}
function licensePackList(){try{return (window.LicensePacks?.list({countryCode:'MT'})||[]).map(licensePackSyncRuntime)}catch(_){return []}}
function licensePackActive(){
 const requested=licensePackSyncRuntime(window.LicensePacks?.get(licensePackEngineState.activeId));
 if(requested&&window.LicensePacks.activatable(requested))return requested;
 return licensePackSyncRuntime(window.LicensePacks?.get('MT-LPTV'))||null;
}
function licensePackStatusLabel(p){
 if(!p)return lang3('NON DISPONIBILE','UNAVAILABLE','MHUX DISPONIBBLI');
 if(window.LicensePacks?.activatable(p))return lang3('VERIFICATO','VERIFIED','IVVERIFIKAT');
 if(p.status==='audit-required')return lang3('AUDIT NECESSARIO','AUDIT REQUIRED','AUDIT MEĦTIEĠ');
 if(p.status==='audit-complete')return lang3('AUDIT COMPLETATO','AUDIT COMPLETE','AUDIT KOMPLUT');
 return lang3('PIANIFICATO','PLANNED','IPPJANAT');
}
function licensePackProgrammeLabel(p){
 if(!p)return '—';
 if(p.id==='MT-B')return lang3('Patente B · Auto','Category B · Car','Liċenzja B · Karozza');
 if(p.id==='MT-A')return lang3('Moto','Motorcycle','Mutur');
 if(p.id==='MT-C-CE')return lang3('Camion C/CE','Truck C/CE','Trakk C/CE');
 if(p.id==='MT-D')return lang3('Bus D','Bus D','Xarabank D');
 return p.programme||p.id||'—';
}
function licensePackAuditNote(p){
 const n=p?.audit?.noteI18n;
 if(n&&typeof n==='object')return lang3(n.it||'',n.en||n.it||'',n.mt||n.en||n.it||'');
 return p?.audit?.note||'';
}
function licensePackOfficialSource(p){
 const src=p?.questionBank?.officialSourceI18n;
 if(src&&typeof src==='object')return lang3(src.it||'',src.en||src.it||'',src.mt||src.en||src.it||'');
 return p?.questionBank?.officialSource||'Transport Malta';
}
function licensePackInstalledCount(p){
 if(!p)return 0;
 if(p.id==='MT-C-CE'){
  try{return new Set((Array.isArray(CCE_Q)?CCE_Q:[]).map(q=>String(q?.id||'')).filter(Boolean)).size}catch(_){return Number(p?.questionBank?.expectedCount||386)}
 }
 const q=p.questionBank||{};
 if(Number.isFinite(Number(q.expectedCount))&&Number(q.expectedCount)>0)return Number(q.expectedCount);
 if(Number.isFinite(Number(q.currentCanonicalMatches))&&Number(q.currentCanonicalMatches)>0)return Number(q.currentCanonicalMatches);
 if(Number.isFinite(Number(q.officialCount))&&Number(q.officialCount)>0)return Number(q.officialCount);
 return p.id==='MT-LPTV'?Q.length:0;
}
