function bindLicenseCCE(){
 autonomousPackSetActive('MT-C-CE');
 bindAutonomousPackResume('licensecce');
 const study=$('#licenseCCEStudy');if(study)study.onclick=()=>startQuiz(shuffle(CCE_Q).slice(0,35),'guided',{returnRoute:'licensecce'});
 const exam=$('#licenseCCEExam');if(exam)exam.onclick=()=>startQuiz(shuffle(CCE_Q).slice(0,35),'exam',{timerSeconds:45*60,returnRoute:'licensecce'});
 const bank=$('#licenseCCEBank');if(bank)bank.onclick=()=>{$('#licenseCCEBankCard')?.classList.remove('hidden');$('#licenseCCEBankCard')?.scrollIntoView({behavior:'smooth',block:'start'})};
 const close=$('#licenseCCECloseBank');if(close)close.onclick=()=>$('#licenseCCEBankCard')?.classList.add('hidden');
 screen.querySelectorAll('[data-license-cce-cat]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.licenseCceCat;const list=CCE_Q.filter(q=>String(q.category||'OTHER').trim()===key);if(list.length)startQuiz(shuffle(list).slice(0,Math.min(35,list.length)),'guided',{returnRoute:'licensecce'})});
 screen.querySelectorAll('[data-license-cce-q]').forEach(btn=>btn.onclick=()=>{const q=CCE_Q.find(x=>x.id===btn.dataset.licenseCceQ);if(q)startQuiz([q],'guided',{returnRoute:'licensecce'})});
 const d=cceIntelligenceData();const recovery=$('#cceStartRecovery');if(recovery)recovery.onclick=()=>{if(d.recovery.length)startQuiz(d.recovery,'guided',{returnRoute:'licensecce'})};const replay=$('#cceOpenReplay');if(replay&&d.replayPairs[0])replay.onclick=()=>errorReplayOpen(d.replayPairs[0].source.id);
}
function busDProgressStats(){
 const ids=new Set(BUS_D_Q.map(q=>q.id));
 const seen=Object.keys(progress.seen||{}).filter(id=>ids.has(id)).length;
 const correct=Object.entries(progress.correct||{}).filter(([id,v])=>ids.has(id)&&Number(v)>0).length;
 const wrong=Object.entries(progress.wrong||{}).filter(([id,v])=>ids.has(id)&&Number(v)>0).length;
 const exams=(progress.exams||[]).filter(e=>Array.isArray(e.details)&&e.details.length&&e.details.every(d=>ids.has(d.id)));
 const last=exams[exams.length-1]||null;
 return {seen,correct,wrong,exams,last,pct:BUS_D_Q.length?Math.round(seen/BUS_D_Q.length*100):0};
}
function busDCategoryLabel(value){
 const k=String(value||'').trim().toUpperCase();
 const labels={
  'PASSENGER WEIGHTS':['Pesi dei passeggeri','Passenger weights','Piżijiet tal-passiġġieri'],
  'VEHICLE WEIGHTS AND DIMENSIONS':['Pesi e dimensioni del veicolo','Vehicle weights and dimensions','Piżijiet u dimensjonijiet tal-vettura'],
  'VEHICLE CONTROL AND BRAKING':['Controllo del veicolo e frenata','Vehicle control and braking','Kontroll tal-vettura u ibbrejkjar'],
  'PASSENGER SAFETY AND COMFORT':['Sicurezza e comfort dei passeggeri','Passenger safety and comfort','Sigurtà u kumdità tal-passiġġieri'],
  'CARRYING PASSENGERS':['Trasporto passeggeri','Carrying passengers','Ġarr ta’ passiġġieri'],
  'THE DRIVER':['Il conducente professionale','The professional driver','Is-sewwieq professjonali'],
  'THE ROAD':['Strada e procedure','Road and procedures','Triq u proċeduri'],
  'RESTRICTED VIEW':['Visibilità limitata e specchi','Restricted view and mirrors','Viżibbiltà limitata u mirja'],
  'VULNERABLE ROAD USERS':['Utenti vulnerabili','Vulnerable road users','Utenti vulnerabbli tat-triq'],
  'OTHER ROAD USERS':['Altri utenti della strada','Other road users','Utenti oħra tat-triq'],
  'LEAVING THE VEHICLE':['Fermata e uscita dal veicolo','Leaving the vehicle','Tluq mill-vettura'],
  'ACCIDENTS / EMERGENCIES':['Incidenti ed emergenze','Accidents and emergencies','Inċidenti u emerġenzi'],
  'ACCIDENT HANDLING':['Gestione degli incidenti','Accident handling','Ġestjoni tal-inċidenti'],
  'VEHICLE CONDITION':['Condizioni e controlli del veicolo','Vehicle condition and checks','Kundizzjoni u kontrolli tal-vettura'],
  'ENVIRONMENTAL':['Guida e ambiente','Driving and environment','Sewqan u ambjent'],
  'ENVIRONMENTAL ISSUES':['Guida e ambiente','Driving and environment','Sewqan u ambjent'],
  'DOCUMENTS':['Documenti e responsabilità','Documents and responsibility','Dokumenti u responsabbiltà'],
  'TRAFFIC SIGNS':['Segnali stradali','Traffic signs','Sinjali tat-traffiku']
 };
 const x=labels[k];return x?lang3(x[0],x[1],x[2]):String(value||lang3('Altro','Other','Oħrajn'));
}
function busDIntelligenceData(){
 const ps=busDProgressStats(),ids=new Set(BUS_D_Q.map(q=>q.id));
 const wrongQuestions=BUS_D_Q.filter(q=>Number(progress.wrong?.[q.id]||0)>0).sort((a,b)=>Number(progress.wrong?.[b.id]||0)-Number(progress.wrong?.[a.id]||0)||a.id.localeCompare(b.id));
 const recentWrong=[];const seenRecent=new Set();
 (ps.exams||[]).slice(-5).reverse().forEach(exam=>(exam.details||[]).forEach(d=>{if(!d?.ok&&ids.has(d.id)&&!seenRecent.has(d.id)){const q=BUS_D_Q.find(x=>x.id===d.id);if(q){seenRecent.add(d.id);recentWrong.push(q)}}}));
 const recovery=[];const used=new Set();[...recentWrong,...wrongQuestions].forEach(q=>{if(q&&!used.has(q.id)&&recovery.length<10){used.add(q.id);recovery.push(q)}});
 const groups={};wrongQuestions.forEach(q=>{const key=String(q.category||'OTHER').trim().toUpperCase();groups[key]=(groups[key]||0)+Number(progress.wrong?.[q.id]||0)});
 const weakKey=Object.keys(groups).sort((a,b)=>groups[b]-groups[a])[0]||'';
 const weakLabel=weakKey?busDCategoryLabel(weakKey):lang3('Nessuna debolezza registrata','No recorded weakness','L-ebda dgħufija rreġistrata');
 const replayPairs=wrongQuestions.map(q=>({bus:q,source:busDReplayEquivalentQuestion(q)})).filter(x=>x.source);
 const recent=(ps.exams||[]).slice(-3),avg=recent.length?recent.reduce((n,e)=>n+(Number(e.score||0)/Math.max(1,Number(e.total||35))*100),0)/recent.length:0;
 const signals=[
  {ok:ps.seen>=104,label:lang3('Copertura Bus D','Bus D coverage','Kopertura Bus D'),detail:`${ps.seen}/208`},
  {ok:recent.length>=2,label:lang3('Simulazioni Bus D','Bus D simulations','Simulazzjonijiet Bus D'),detail:`${recent.length}/2`},
  {ok:recent.length>=2&&avg>=85,label:lang3('Prestazione recente','Recent performance','Prestazzjoni riċenti'),detail:recent.length?`${Math.round(avg)}%`:'—'},
  {ok:wrongQuestions.length<=Math.max(3,Math.round(ps.seen*.12)),label:lang3('Errori Bus D aperti','Open Bus D mistakes','Żbalji Bus D miftuħa'),detail:String(wrongQuestions.length)},
  {ok:recovery.length===0||recovery.every(q=>Number(progress.correct?.[q.id]||0)>0),label:lang3('Recovery Bus D','Bus D recovery','Irkupru Bus D'),detail:recovery.length?`${recovery.filter(q=>Number(progress.correct?.[q.id]||0)>0).length}/${recovery.length}`:lang3('nessun errore','no mistakes','ebda żball')}
 ];
 return {ps,wrongQuestions,recovery,weakKey,weakLabel,replayPairs,recent,avg,signals,passed:signals.filter(x=>x.ok).length};
}
