function bindLicenseD(){
 autonomousPackSetActive('MT-D');
 bindAutonomousPackResume('licensed');
 const study=$('#licenseDStudy');if(study)study.onclick=()=>startQuiz(shuffle(BUS_D_Q).slice(0,35),'guided',{returnRoute:'licensed'});
 const exam=$('#licenseDExam');if(exam)exam.onclick=()=>startQuiz(shuffle(BUS_D_Q).slice(0,35),'exam',{timerSeconds:45*60,returnRoute:'licensed'});
 const bank=$('#licenseDBank');if(bank)bank.onclick=()=>{$('#licenseDBankCard')?.classList.remove('hidden');$('#licenseDBankCard')?.scrollIntoView({behavior:'smooth',block:'start'})};
 const close=$('#licenseDCloseBank');if(close)close.onclick=()=>$('#licenseDBankCard')?.classList.add('hidden');
 screen.querySelectorAll('[data-license-d-cat]').forEach(btn=>btn.onclick=()=>{const key=btn.dataset.licenseDCat;const list=BUS_D_Q.filter(q=>String(q.category||'OTHER').trim()===key);if(list.length)startQuiz(shuffle(list).slice(0,Math.min(35,list.length)),'guided',{returnRoute:'licensed'})});
 screen.querySelectorAll('[data-license-d-q]').forEach(btn=>btn.onclick=()=>{const q=BUS_D_Q.find(x=>x.id===btn.dataset.licenseDQ);if(q)startQuiz([q],'guided',{returnRoute:'licensed'})});
 const d=busDIntelligenceData();const recovery=$('#busDStartRecovery');if(recovery)recovery.onclick=()=>{if(d.recovery.length)startQuiz(d.recovery,'guided',{returnRoute:'licensed'})};const replay=$('#busDOpenReplay');if(replay&&d.replayPairs[0])replay.onclick=()=>errorReplayOpen(d.replayPairs[0].source.id);
}
function globalMultiLicenseIntelligenceAuditHtml(){
 const defs=[
  {id:'MT-LPTV',icon:'🚘',name:'LPTV TAG',expected:250,bridge:()=>lptvIntelligenceData(),view:()=>typeof lptvIntelligenceHtml==='function',detail:lang3('Core AI storico + LPTV Intelligence Bridge installato e visibile','Original AI core + LPTV Intelligence Bridge installed and visible','Core AI storiku + LPTV Intelligence Bridge installat u viżibbli')},
  {id:'MT-B',icon:'🚗',name:lang3('Patente B','Category B','Kategorija B'),expected:444,bridge:()=>autoBIntelligenceData(),view:()=>typeof autoBIntelligenceHtml==='function',detail:lang3('Intelligence Bridge installato e visibile','Intelligence Bridge installed and visible','Intelligence Bridge installat u viżibbli')},
  {id:'MT-A',icon:'🏍️',name:lang3('Moto','Motorcycle','Mutur'),expected:391,bridge:()=>motoIntelligenceData(),view:()=>typeof motoIntelligenceHtml==='function',detail:lang3('Intelligence Bridge installato e visibile','Intelligence Bridge installed and visible','Intelligence Bridge installat u viżibbli')},
  {id:'MT-C-CE',icon:'🚛',name:'C/CE',expected:386,bridge:()=>cceIntelligenceData(),view:()=>typeof cceIntelligenceHtml==='function',detail:lang3('Intelligence Bridge installato e visibile','Intelligence Bridge installed and visible','Intelligence Bridge installat u viżibbli')},
  {id:'MT-D',icon:'🚌',name:'Bus D',expected:208,bridge:()=>busDIntelligenceData(),view:()=>typeof busDIntelligenceHtml==='function',detail:lang3('Intelligence Bridge installato e visibile','Intelligence Bridge installed and visible','Intelligence Bridge installat u viżibbli')}
 ];
 const rows=defs.map(d=>{
  const p=licensePackSyncRuntime(window.LicensePacks?.get(d.id));
  const count=licensePackInstalledCount(p);
  let intel=null,viewOk=false;
  try{ intel=d.bridge(); viewOk=Boolean(d.view()); }catch(e){ intel=null; viewOk=false; }
  /* Final freeze validates the installed Intelligence architecture, not the student's personal readiness score.
     A bridge can correctly show 0/5..5/5 depending on learning history and must not fail the product freeze for that reason. */
  const bridgeOk=!!(viewOk && intel && Array.isArray(intel.signals) && intel.signals.length===5 && typeof intel.passed==='number');
  const complete=!!(p && window.LicensePacks?.activatable(p) && count===d.expected);
  return {...d,count,bridgeOk,complete,ok:complete&&bridgeOk};
 });
 const passed=rows.filter(r=>r.ok).length;
 const all=passed===rows.length;
 return `<section class="card multi-license-intelligence-audit final-freeze-audit"><div class="license-pack-head"><div><small>${esc(lang3('GLOBAL MULTI-LICENSE FINAL AUDIT & FREEZE','GLOBAL MULTI-LICENSE FINAL AUDIT & FREEZE','GLOBAL MULTI-LICENSE FINAL AUDIT & FREEZE'))}</small><h2>${esc(all?lang3('5/5 licenze complete, intelligenti e pronte al freeze','5/5 licences complete, intelligent and ready to freeze','5/5 liċenzji kompluti, intelliġenti u lesti għall-freeze'):lang3(`${passed}/5 controlli finali superati`,`${passed}/5 final checks passed`,`${passed}/5 kontrolli finali mgħoddija`))}</h2></div><strong class="${all?'ready':'locked'}">${passed}/5</strong></div><div class="license-pack-gates">${rows.map(r=>`<article class="${r.ok?'pass':'fail'}"><span>${r.ok?'✓':'!'}</span><div><b>${r.icon} ${esc(r.name)} · ${esc(String(r.count))}/${esc(String(r.expected))}</b><small>${esc(r.detail)} · ${esc(r.complete?lang3('banca verificata/attiva','bank verified/active','bank ivverifikat/attiv'):lang3('banca non completa','bank incomplete','bank mhux komplut'))}</small></div></article>`).join('')}</div><p><strong>${esc(all?lang3('FASE MULTI-LICENSE CONGELABILE','MULTI-LICENSE PHASE READY TO FREEZE','FAŻI MULTI-LICENSE LESTA GĦALL-FREEZE'):lang3('NON CONGELARE ANCORA','DO NOT FREEZE YET','GĦADUX FREEZE'))}</strong></p><p>${esc(lang3('Controllo runtime finale: conteggi ufficiali, stato verificato/attivo e catena Intelligence di ciascuna licenza. Nessun dato viene condiviso tra pack salvo mapping canonici e Replay semanticamente pertinenti.','Final runtime check: official counts, verified/active state and Intelligence chain for every licence. No data is shared across packs except canonical mappings and semantically relevant Replays.','Kontroll finali tar-runtime: għadd uffiċjali, stat ivverifikat/attiv u katina Intelligence għal kull liċenzja. Ebda data ma tinqasam bejn packs ħlief mappings kanoniċi u Replay semantikament rilevanti.'))}</p></section>`;
}
