function applyStrictLanguageUiLiterals(root=document.body){
 const lang=settings?.lang||'en';
 const map=lang==='mt'?STRICT_MT_UI_LITERALS:(lang==='it'?STRICT_IT_UI_LITERALS:null);
 if(!map||!root)return;
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 for(const n of nodes){
  if(n.parentElement?.closest('script,style,textarea,input'))continue;
  const raw=n.nodeValue||'',trim=raw.trim();
  if(!trim||!Object.prototype.hasOwnProperty.call(map,trim))continue;
  n.nodeValue=raw.replace(trim,map[trim]);
 }
}
let strictLanguageObserver=null;
function ensureStrictLanguageObserver(){
 if(strictLanguageObserver)return;
 strictLanguageObserver=new MutationObserver(muts=>{for(const m of muts)for(const n of m.addedNodes){if(n.nodeType===1||n.nodeType===3)applyStrictLanguageUiLiterals(n.nodeType===1?n:n.parentNode)}});
 strictLanguageObserver.observe(document.body,{childList:true,subtree:true});
}
