  targetDate:$('#roadmapTargetDate')?.value||'',
  dailyMinutes:Math.max(10,Math.min(120,Number($('#roadmapDailyMinutes')?.value)||20)),
  studyDays:Math.max(1,Math.min(7,Number($('#roadmapStudyDays')?.value)||5)),
