let replayAssetVerification={};
let replayAssetVerificationPromise=null;
let replayAssetVerificationScheduled=false;

async function verifyReplayAssets(){
 const pack=activeCountryPack();
 const entries=window.SceneAssets?.list()||[];
 const results={};
 for(const item of entries){
  results[item.sceneKey]=await window.SceneAssets.verify(item.sceneKey,pack);
 }
 replayAssetVerification=results;
 if(route?.name==='errorreplay')render();
 return results;
}
function ensureReplayAssetVerification(){
 if(replayAssetVerificationPromise)return replayAssetVerificationPromise;
 replayAssetVerificationPromise=verifyReplayAssets().catch(error=>{
  replayAssetVerificationPromise=null;
  throw error;
 });
 return replayAssetVerificationPromise;
}
function scheduleReplayAssetVerification(){
 if(replayAssetVerificationScheduled||replayAssetVerificationPromise)return;
 replayAssetVerificationScheduled=true;
 const run=()=>{
  replayAssetVerificationScheduled=false;
  ensureReplayAssetVerification().catch(()=>{});
 };
 if(typeof requestIdleCallback==='function')requestIdleCallback(run,{timeout:5000});
 else setTimeout(run,2500);
}

function replayAssetStatusHtml(question){
 const selection=replaySceneSelection(question);
 const key=selection.key;
 const manifest=key?window.SceneAssets?.get(key):null;
 const verification=key?replayAssetVerification[key]:null;
 if(!key)return '';

 let state='waiting';
 let title=lang3('Filmato non ancora inserito','Footage not added yet','Il-filmat għadu ma ddaħħalx');
 let body=lang3('Il Replay non userà video generici. Verrà attivato solo quando il file corretto per Malta sarà presente e approvato.','The Replay will not use generic footage. It will activate only when the correct approved Malta file is present.','Ir-Replay ma jużax filmati ġeneriċi. Jiġi attivat biss meta jkun hemm il-filmat korrett u approvat għal Malta.');

 if(manifest?.status==='approved'&&verification?.ok){
  state='ready';
  title=lang3('Asset verificato','Asset verified','Asset ivverifikat');
  body=lang3('Video, poster, lato di guida e Country Pack sono compatibili.','Video, poster, driving side and Country Pack are compatible.','Il-video, il-poster, in-naħa tas-sewqan u l-pakkett tal-pajjiż huma kompatibbli.');
 }else if(manifest?.status==='approved'&&!verification){
  state='checking';
  title=lang3('Verifica asset in corso','Checking scene assets','Qed jiġu vverifikati l-assets tax-xena');
  body=lang3('Il motore sta controllando video e poster.','The engine is checking the video and poster.','Il-magna qed tivverifika l-video u l-poster.');
 }else if(verification&&!verification.ok){
  state='blocked';
  title=lang3('Scena bloccata correttamente','Scene correctly blocked','Ix-xena ġiet imblukkata kif suppost');
  body=lang3('Manca un asset approvato e pertinente. Nessun video casuale verrà mostrato.','An approved relevant asset is missing. No random video will be shown.','Hemm asset approvat u pertinenti nieqes. Ma jintwera l-ebda video każwali.');
 }

 return `<div class="scene-asset-card ${state}">
  <div class="scene-asset-icon">${state==='ready'?'✓':state==='blocked'?'×':'…'}</div>
  <div>
   <span>${esc(replayUi('CONTROLLO ASSET','ASSET CONTROL'))}</span>
   <strong>${esc(title)}</strong>
   <p>${esc(body)}</p>
   ${manifest?.sourceType==='local'?`<small>${esc(manifest.video)}</small>`:''}
  </div>
 </div>`;
}


