  `<div class="section-title"><div><h2>${esc(t('errorReplayLibrary'))}</h2><p>${esc(replayUi('Seleziona una domanda per aprire la ricostruzione tecnica','Select a question to open its technical reconstruction'))}</p></div><strong>${pool.length}</strong></div>`,
  `<div class="replay-library-grid">${pool.length?pool.map(item=>{const s=errorReplayScenario(item);return `<button data-replay-open="${esc(item.id)}"><span>${esc(item.id)} · ${esc(replayUi(s.labelIt,s.labelEn))}</span><strong>${esc(questionText(item))}</strong>${isItalianAssisted()?`<small>${esc(item.question_it||item.question)}</small>`:''}</button>`}).join(''):`<p>${esc(t('errorReplayNoQuestion'))}</p>`}</div>`
