function pilotAnalyticsDate(value){
 if(!value)return '—';
 try{return new Date(value).toLocaleString(settings.lang==='it'?'it-IT':settings.lang==='mt'?'mt-MT':'en-GB')}
 catch{return String(value)}
}
function pilotAnalyticsViewHtml(){
 const s=pilotAnalyticsSummary();
 const status=s.consent?lang3('ATTIVO CON CONSENSO','ACTIVE WITH CONSENT','ATTIV BIL-KUNSENS'):lang3('DISATTIVATO','DISABLED','MITFI');
 const syncText=s.lastServerSyncAt?pilotAnalyticsDate(s.lastServerSyncAt):lang3('Mai','Never','Qatt');
 const syncLabel=s.consent?lang3('Sincronizza riepilogo pilot','Sync pilot summary','Issinkronizza s-sommarju tal-pilot'):lang3('Sincronizza revoca analytics','Sync analytics revocation','Issinkronizza r-revoka tal-analytics');
 return `<div class="section-title"><div><h2>📈 ${esc(lang3('Pilot Analytics & Measurement','Pilot Analytics & Measurement','Pilot Analytics & Measurement'))}</h2><p>${esc(lang3('Metriche reali del pilot, registrate solo dopo consenso analytics.','Real pilot metrics recorded only after analytics consent.','Metriċi reali tal-pilot irreġistrati biss wara kunsens għall-analytics.'))}</p></div><span class="badge official">Build ${esc(BUILD_VERSION)}</span></div>
 <div class="card"><div class="help-card-title"><div><h3>${esc(status)}</h3><p>${esc(s.consent?lang3('Gli eventi restano locali; solo il riepilogo aggregato entra nella sincronizzazione didattica quando la avvii esplicitamente.','Events remain local; only the aggregate summary enters learning sync when you explicitly start it.','L-avvenimenti jibqgħu lokali; is-sommarju aggregat biss jidħol fis-sinkronizzazzjoni meta tibdaha b’mod espliċitu.'):lang3('Analytics è disattivato: non vengono registrati nuovi eventi e le metriche locali precedenti non vengono incluse nelle sincronizzazioni. Se avevi già condiviso un riepilogo, usa “Sincronizza revoca analytics” per sostituirlo sul server con il solo stato di consenso revocato. Le metriche storiche restano sul dispositivo finché non scegli di cancellarle.','Analytics is disabled: no new events are recorded and previous local metrics are not included in sync. If you previously shared a summary, use “Sync analytics revocation” to replace it on the server with consent-revoked state only. Historical metrics remain on this device until you choose to delete them.','Analytics huwa mitfi: ma jiġu rreġistrati l-ebda avvenimenti ġodda u l-metriċi lokali preċedenti ma jidħlux fis-sync. Jekk qabel qsamtu sommarju, uża “Issinkronizza r-revoka tal-analytics” biex tissostitwih fuq is-server bl-istat tal-kunsens revokat biss. Il-metriċi storiċi jibqgħu fuq dan l-apparat sakemm tagħżel li tħassarhom.'))}</p></div><span>${s.consent?'✓':'○'}</span></div>
 <div class="privacy-summary-grid">
  <article><span>${esc(lang3('Giorni attivi','Active days','Jiem attivi'))}</span><strong>${s.activeDays}</strong><small>${esc(lang3('ritorno reale','real return','ritorn reali'))}</small></article>
  <article><span>${esc(lang3('Sessioni','Sessions','Sessjonijiet'))}</span><strong>${s.sessionsCompleted}/${s.sessionsStarted}</strong><small>${s.completionRate}% ${esc(lang3('completate','completed','kompluti'))}</small></article>
  <article><span>${esc(lang3('Esami','Exams','Eżamijiet'))}</span><strong>${s.examsCompleted}</strong><small>${s.examAverage===null?'—':s.examAverage+'%'} ${esc(lang3('media','average','medja'))}</small></article>
  <article><span>Replay</span><strong>${s.replayCompleted}</strong><small>${esc(lang3('completati','completed','kompluti'))}</small></article>
  <article><span>${esc(lang3('Feedback pilot','Pilot feedback','Feedback tal-pilot'))}</span><strong>${s.pilotFeedbackActions}</strong><small>${esc(lang3('azioni preparate','prepared actions','azzjonijiet ippreparati'))}</small></article>
  <article><span>${esc(lang3('Errori runtime build corrente','Current-build runtime errors','Żbalji runtime tal-build kurrenti'))}</span><strong>${s.currentBuildRuntimeErrors}</strong><small>${s.lastRuntimeKind?esc(lang3('ultimo','last','l-aħħar'))+': '+esc(s.lastRuntimeKind)+(s.lastRuntimeScript?' · '+esc(s.lastRuntimeScript):'')+(s.lastRuntimeLine?' · L'+s.lastRuntimeLine+(s.lastRuntimeColumn?':'+s.lastRuntimeColumn:''):''):esc(lang3('storici/non attribuiti','historical/unattributed','storiċi/mhux attribwiti'))+': '+s.legacyRuntimeErrors}</small></article>
  <article><span>${esc(lang3('Avvio app','App startup','Bidu tal-app'))}</span><strong>${s.startupAverageMs===null?'—':s.startupAverageMs+' ms'}</strong><small>${s.startupMaxMs===null?esc(lang3('nessun campione','no sample','l-ebda kampjun')):esc(lang3('max','max','massimu'))+' '+s.startupMaxMs+' ms · '+s.startupSamples}</small></article>
 </div>
 <p class="muted">${esc(lang3('Pack osservati','Observed packs','Packs osservati'))}: ${esc(s.packs.length?s.packs.join(', '):'—')} · ${esc(lang3('Ultima sync server','Last server sync','L-aħħar sync mas-server'))}: ${esc(syncText)}</p>
 <div class="actions"><button class="btn" id="pilotAnalyticsSync">☁️ ${esc(syncLabel)}</button><button class="btn secondary" id="pilotAnalyticsCopy">⧉ ${esc(lang3('Copia report locale','Copy local report','Ikkopja r-rapport lokali'))}</button><button class="btn secondary" data-go="privacycenter">🔒 ${esc(lang3('Centro Privacy','Privacy Center','Ċentru tal-Privatezza'))}</button><button class="btn danger" id="pilotAnalyticsClear">${esc(lang3('Cancella metriche pilot locali','Delete local pilot metrics','Ħassar il-metriċi lokali tal-pilot'))}</button></div>
 </div>`;
}
