// Build 40.12.1 — MDM DRIVING TWIN DATA INTEGRITY
// Hardened diagnostic layer: every displayed Twin value is finite, attributable and explicit.
// No NaN / undefined / opaque severity numbers are allowed in the Driving Twin UI.
function drivingTwinFinite(value,fallback=0){const n=Number(value);return Number.isFinite(n)?n:fallback}
function drivingTwinCount(value){return Math.max(0,Math.round(drivingTwinFinite(value,0)))}
function drivingTwinMaybeNumber(value){const n=Number(value);return Number.isFinite(n)?n:null}
function drivingTwinClamp(value,min=0,max=100){const n=drivingTwinFinite(value,0);return Math.max(min,Math.min(max,Math.round(n)))}
function drivingTwinPct(value){const n=drivingTwinMaybeNumber(value);return n===null?null:drivingTwinClamp(n)}
function drivingTwinEvidence(){
 const history=Array.isArray(progress.responseHistory)?progress.responseHistory:[];
 const interactive=interactiveReplayStats()||{};
 const interactiveAttempts=drivingTwinCount(interactive.attempts);
 const reasons=Object.values(progress.errorReasons||{}).reduce((n,map)=>n+Object.values(map||{}).reduce((a,b)=>a+drivingTwinCount(b),0),0);
 const seen=Q.filter(q=>drivingTwinCount(progress.seen?.[q.id])>0).length;
 const exams=Array.isArray(progress.exams)?progress.exams.length:0;
 const bridge=Array.isArray(progress.bridgeResults)?progress.bridgeResults.length:0;
 const languageTwinRuns=typeof languageTwinLatest==='function'&&typeof languageTwin!=='undefined'&&Array.isArray(languageTwin.diagnostics)?languageTwin.diagnostics.length:0;
 const realRoad=typeof realRoadEvidenceCount==='function'?realRoadEvidenceCount():0;
 const points=drivingTwinCount(history.length+interactiveAttempts+reasons+(exams*8)+(bridge*5)+(languageTwinRuns*6)+(realRoad*8)+Math.round(seen/5));
 const level=points>=120?'high':points>=45?'medium':'growing';
 return {history:drivingTwinCount(history.length),interactive:interactiveAttempts,reasons:drivingTwinCount(reasons),seen:drivingTwinCount(seen),exams:drivingTwinCount(exams),bridge:drivingTwinCount(bridge),languageTwin:drivingTwinCount(languageTwinRuns),realRoad:drivingTwinCount(realRoad),points,level};
}
function drivingTwinStabilityData(activeGroups,timing){
 const groups=Array.isArray(activeGroups)?activeGroups:[];
 const rows=Array.isArray(timing)?timing:[];
 const dated=rows.map(x=>Date.parse(x?.ts||'')).filter(Number.isFinite).sort((a,b)=>a-b);
 const spanDays=dated.length>=2?(dated[dated.length-1]-dated[0])/(24*60*60*1000):0;
 const hasVerification=groups.some(x=>Boolean(x?.stabilityRecord||x?.recentRecovery||x?.stabilityConfirmed));
 const enoughLongitudinalEvidence=hasVerification||spanDays>=1;
 const stable=groups.filter(x=>x?.stabilityConfirmed).length;
 const improving=groups.filter(x=>x?.recurrence==='improving').length;
 const occasional=groups.filter(x=>x?.recurrence==='occasional').length;
 const emerging=groups.filter(x=>x?.recurrence==='emerging').length;
 const recurring=groups.filter(x=>x?.recurrence==='recurring').length;
 if(!groups.length||!enoughLongitudinalEvidence)return {score:null,stable,improving,occasional,emerging,recurring,spanDays};
 const weighted=(stable*100)+(improving*75)+(occasional*55)+(emerging*35)+(recurring*15);
 const score=drivingTwinClamp(weighted/groups.length);
 return {score,stable,improving,occasional,emerging,recurring,spanDays};
}
function drivingTwinAxisData(){
 const ready=readinessStats()||{};
 const pattern=aiCoachPatternAnalysis()||{ranked:[]};
 const interactive=interactiveReplayStats()||{};
 const bridge=latestBridgeResult();
 const timing=(Array.isArray(progress.responseHistory)?progress.responseHistory:[]).filter(x=>drivingTwinMaybeNumber(x?.ms)!==null&&Number(x.ms)>0);
 const reasonTotals=errorReasonTotals()||{};
 const groups=AI_PATTERN_GROUPS.map(aiPatternGroupAnalysis);
 const activeGroups=groups.filter(x=>drivingTwinCount(x?.attempts)||drivingTwinCount(x?.wrong)||Object.values(x?.reasonTotals||{}).some(Boolean));
 const knowledgeAccuracy=drivingTwinPct(ready.accuracy);
 const knowledgeCoverage=drivingTwinPct(ready.coverage);
 const knowledgeEvidence=knowledgeCoverage!==null&&knowledgeCoverage>0;
 const knowledge=knowledgeEvidence?drivingTwinClamp((knowledgeAccuracy||0)*.78+(knowledgeCoverage||0)*.22):null;
 let language=null;
 const universalLanguageResult=typeof languageTwinLatest==='function'?languageTwinLatest():null;
 const universalLanguageProfile=typeof languageTwinProfile==='function'?languageTwinProfile():null;
 if(universalLanguageProfile&&drivingTwinPct(universalLanguageProfile.score)!==null)language=drivingTwinPct(universalLanguageProfile.score);
 else if(isItalianAssisted()){
  const english=aiEnglishPatternAnalysis();
  const bridgePct=drivingTwinPct(bridge?.englishPct);
  if(bridge&&bridgePct!==null)language=bridgePct;
  else if(english)language=drivingTwinClamp(100-Math.min(70,drivingTwinFinite(english.score,0)));
  else if(drivingTwinCount(reasonTotals.language)+drivingTwinCount(reasonTotals.word)>0)language=drivingTwinClamp(100-(drivingTwinCount(reasonTotals.language)+drivingTwinCount(reasonTotals.word))*9);
 }
 const interactiveSessions=drivingTwinCount(interactive.sessions);
 const decision=interactiveSessions?drivingTwinClamp(drivingTwinFinite(interactive.averageScore,0)*.62+drivingTwinFinite(interactive.accuracy,0)*.38):null;
 const correctMedian=aiPatternMedian(timing.filter(x=>x.ok).map(x=>x.ms));
 const wrongMedian=aiPatternMedian(timing.filter(x=>!x.ok).map(x=>x.ms));
 const rushReasons=drivingTwinCount(reasonTotals.rush);
 const impulsive=Boolean(correctMedian&&wrongMedian&&wrongMedian<Math.min(7000,correctMedian*.65));
 const rushPatterns=(Array.isArray(pattern.ranked)?pattern.ranked:[]).filter(x=>x?.cause?.id==='rush').length;
 const attention=timing.length>=5?drivingTwinClamp(100-(rushReasons*9)-(impulsive?24:0)-Math.min(20,rushPatterns*8)):null;
 const stabilityData=drivingTwinStabilityData(activeGroups,timing);
 const stability=stabilityData.score;
 const wrongTimingText=wrongMedian?aiPatternSeconds(wrongMedian):lang3('nessun errore cronometrato','no timed wrong answer','ebda żball bil-ħin');
 return [
  {id:'knowledge',icon:'📘',label:lang3('Conoscenza','Knowledge','Għarfien'),score:knowledge,detail:knowledgeEvidence?lang3(`${knowledgeAccuracy??0}% precisione · ${knowledgeCoverage??0}% copertura`,`${knowledgeAccuracy??0}% accuracy · ${knowledgeCoverage??0}% coverage`,`${knowledgeAccuracy??0}% preċiżjoni · ${knowledgeCoverage??0}% kopertura`):lang3('Servono ancora risposte','More answers needed','Għad hemm bżonn tweġibiet')},
  {id:'language',icon:'🔤',label:lang3('Indipendenza linguistica','Language independence','Indipendenza lingwistika'),score:language,detail:universalLanguageResult?lang3(`Twin linguistico ${drivingTwinPct(universalLanguageProfile?.score)}% · ${universalLanguageProfile?.evidence||0} evidenze · ${universalLanguageProfile?.languageGaps||0} difficoltà linguistiche`,`Language Twin ${drivingTwinPct(universalLanguageProfile?.score)}% · ${universalLanguageProfile?.evidence||0} evidence items · ${universalLanguageProfile?.languageGaps||0} language gaps`,`Language Twin ${drivingTwinPct(universalLanguageProfile?.score)}% · ${universalLanguageProfile?.evidence||0} evidenzi · ${universalLanguageProfile?.languageGaps||0} nuqqasijiet lingwistiċi`):!isItalianAssisted()?lang3('Avvia il Twin linguistico d’esame per misurare la lingua d’esame','Run Exam Language Twin to measure exam-language independence','Ibda Exam Language Twin biex tkejjel l-indipendenza tal-lingwa tal-eżami'):bridge&&drivingTwinPct(bridge?.englishPct)!==null?lang3(`Bridge English ${drivingTwinPct(bridge.englishPct)}%`,`Bridge English ${drivingTwinPct(bridge.englishPct)}%`,`Bridge English ${drivingTwinPct(bridge.englishPct)}%`):lang3('Il Twin sta separando lingua e regola','The Twin is separating language from rule knowledge','It-Twin qed jifred il-lingwa mill-għarfien tar-regola')},
  {id:'decision',icon:'🚦',label:lang3('Qualità decisionale','Decision quality','Kwalità tad-deċiżjoni'),score:decision,detail:interactiveSessions?lang3(`${interactiveSessions} scene · ${drivingTwinCount(interactive.averageScore)}/100 media`,`${interactiveSessions} scenes · ${drivingTwinCount(interactive.averageScore)}/100 average`,`${interactiveSessions} xeni · medja ${drivingTwinCount(interactive.averageScore)}/100`):lang3('Completa alcune Interactive Replay','Complete some Interactive Replays','Imla xi Interactive Replay')},
  {id:'attention',icon:'⏱️',label:lang3('Controllo della risposta','Response control','Kontroll tar-risposta'),score:attention,detail:timing.length?lang3(`${timing.length} tempi osservati · errori ${wrongTimingText}`,`${timing.length} timings observed · wrong ${wrongTimingText}`,`${timing.length} ħinijiet osservati · żbaljati ${wrongTimingText}`):lang3('I tempi inizieranno a costruire il profilo','Response times will build this profile','Il-ħinijiet tar-rispons se jibnu dan il-profil')},
  {id:'stability',icon:'🧠',label:lang3('Stabilità dell’apprendimento','Learning stability','Stabbiltà tat-tagħlim'),score:stability,statusText:stability===null?lang3('IN OSSERVAZIONE','OBSERVING','TAĦT OSSERVAZZJONI'):(stabilityData.stable===0?lang3('IN CONSOLIDAMENTO','CONSOLIDATING','QED JIKKONSOLIDA'):drivingTwinStatusText(stability)),displayScore:stability===null?'—':(stabilityData.stable===0?lang3('IN CORSO','IN PROGRESS','GĦADDEJ'):stability+'%'),detail:stability===null?lang3('Serve almeno un secondo ciclo nel tempo o una verifica di recupero','A second cycle over time or a recovery verification is needed','Hemm bżonn ċiklu ieħor maż-żmien jew verifika ta’ rkupru'):(stabilityData.stable===0?lang3(`${stabilityData.recurring+stabilityData.emerging} schemi ricorrenti ancora aperti · nessuno stabile confermato`,`${stabilityData.recurring+stabilityData.emerging} patterns still open · none confirmed stable`,`${stabilityData.recurring+stabilityData.emerging} mudelli għadhom miftuħa · l-ebda wieħed ikkonfermat stabbli`):lang3(`${stabilityData.stable} stabili · ${stabilityData.recurring+stabilityData.emerging} schemi ricorrenti aperti`,`${stabilityData.stable} stable · ${stabilityData.recurring+stabilityData.emerging} open patterns`,`${stabilityData.stable} stabbli · ${stabilityData.recurring+stabilityData.emerging} mudelli miftuħa`))}
 ];
}
function drivingTwinProfile(){
 const analysis=aiCoachPatternAnalysis()||{ranked:[]};
 const evidence=drivingTwinEvidence();
 const top=(Array.isArray(analysis.ranked)?analysis.ranked:[])[0]||null;
 const cause=top?.cause?.id||'observe';
 const labels={
  language:['Profilo sensibile alla lingua','Language-sensitive profile','Profil sensittiv għall-lingwa'],
  word:['Vocabolario sotto pressione','Vocabulary under pressure','Vokabularju taħt pressjoni'],
  rush:['Decisione rapida / impulsiva','Fast / impulsive decision pattern','Mudell ta’ deċiżjoni mgħaġġla'],
  unsure:['Decisione esitante','Hesitant decision pattern','Mudell ta’ deċiżjoni inċerta'],
  rule:['Conoscenza da consolidare','Knowledge consolidation profile','Profil ta’ konsolidazzjoni tal-għarfien'],
  multiple:['Controllo risposte multiple','Multiple-answer control','Kontroll ta’ tweġibiet multipli'],
  recovered:['Recupero in consolidamento','Recovery being consolidated','Irkupru qed jiġi kkonsolidat'],
  stable:['Pattern sotto controllo','Pattern under control','Mudell taħt kontroll'],
  observe:['Profilo in costruzione','Profile being built','Profil qed jinbena']
 };
 const label=lang3(...(labels[cause]||labels.observe));
 const evidenceLabel=evidence.level==='high'?lang3('Evidenza alta','High evidence','Evidenza għolja'):evidence.level==='medium'?lang3('Evidenza media','Medium evidence','Evidenza medja'):lang3('Evidenza in crescita','Growing evidence','Evidenza qed tikber');
 return {analysis,evidence,top,cause,label,evidenceLabel};
}


/* ================================================================
   Build 45.8.20 — THEORY ↔ ROAD CONTRADICTION DETECTION
   Compares strong theory evidence with explicit instructor-verified
   road evidence for the exact same canonical pattern. Raw telemetry
   is NOT treated as behavioural evidence in this build.
   ================================================================ */
function theoryRoadContradictionTheoryEvidence(groupId){
 const group=AI_PATTERN_GROUPS.find(g=>String(g.id)===String(groupId||''));
 if(!group)return {supported:false,status:'missing',recentCount:0,recentCorrect:0,recentPct:null,stable:false,analysis:null};
 const analysis=aiPatternGroupAnalysis(group);
 const history=(Array.isArray(progress.responseHistory)?progress.responseHistory:[]).filter(row=>aiPatternGroupForHistory(row)===group.id);
 const recent=history.slice(-5),recentCorrect=recent.filter(row=>Boolean(row.ok)).length;
 const recentPct=recent.length?Math.round(recentCorrect/recent.length*100):null;
 // Integrity threshold: theory is treated as strong only after a verified
 // stability record or five consecutive correct recent responses.
 const stable=Boolean(analysis?.stabilityConfirmed);
 const recentPerfect=recent.length===5&&recentCorrect===5;
 const supported=stable||recentPerfect;
 const status=stable?'stable':recentPerfect?'recent-perfect':recent.length?'building':'missing';
 return {supported,status,recentCount:recent.length,recentCorrect,recentPct,stable,analysis};
}
function theoryRoadContradictionLatestRoad(groupId){
 const id=String(groupId||'');
 const rows=(typeof realRoadEvidenceRows==='function'?realRoadEvidenceRows():[]).filter(row=>String(row?.patternId||'')===id&&row?.completedAt);
 return [...rows].sort((a,b)=>String(b.completedAt||'').localeCompare(String(a.completedAt||'')))[0]||null;
}
function theoryRoadContradictionRoadEvidence(row){
 if(!row)return {available:false,repeat:0,help:0,independent:0,total:0,state:'missing',score:null,status:''};
 const evals=Array.isArray(row.objectiveEvaluations)?row.objectiveEvaluations:[];
 const repeat=evals.filter(x=>String(x?.evaluation||'')==='repeat').length;
 const help=evals.filter(x=>String(x?.evaluation||'')==='help').length;
 const independent=evals.filter(x=>String(x?.evaluation||'')==='independent').length;
 const total=evals.length;
 const status=String(row.status||'');
 let state='observed';
 if(status==='verified'||(total>=3&&independent===total))state='independent';
 else if(status==='needs-work'||repeat>0)state='repeat';
 else if(status==='partial'||help>0)state='assisted';
 return {available:true,repeat,help,independent,total,state,score:drivingTwinMaybeNumber(row.score),status,row};
}
function theoryRoadContradictionRow(group){
 const theory=theoryRoadContradictionTheoryEvidence(group.id);
 const roadRow=theoryRoadContradictionLatestRoad(group.id);
 const road=theoryRoadContradictionRoadEvidence(roadRow);
 let state='insufficient';
 if(theory.supported&&road.available){
  if(road.state==='repeat')state='contradiction';
  else if(road.state==='assisted')state='transfer-gap';
  else if(road.state==='independent')state='aligned';
  else state='insufficient';
 }else if(!theory.supported&&road.available&&(road.state==='repeat'||road.state==='assisted'))state='coherent-weakness';
 const rank={contradiction:5,'transfer-gap':4,'coherent-weakness':3,aligned:2,insufficient:1}[state]||1;
 return {id:group.id,group,theory,road,roadRow,state,rank};
}
function drivingTwinTheoryRoadContradictionData(){
 const rows=AI_PATTERN_GROUPS.map(theoryRoadContradictionRow);
 const observed=rows.filter(row=>row.theory.recentCount||row.road.available||drivingTwinCount(row.theory.analysis?.attempts)>0);
 const contradictions=observed.filter(row=>row.state==='contradiction');
 const gaps=observed.filter(row=>row.state==='transfer-gap');
 const aligned=observed.filter(row=>row.state==='aligned');
 const coherent=observed.filter(row=>row.state==='coherent-weakness');
 const primary=[...observed].sort((a,b)=>b.rank-a.rank||drivingTwinCount(b.road?.repeat)-drivingTwinCount(a.road?.repeat)||drivingTwinCount(b.road?.help)-drivingTwinCount(a.road?.help))[0]||null;
 const state=contradictions.length?'contradiction':gaps.length?'transfer-gap':aligned.length?'aligned':coherent.length?'coherent-weakness':'insufficient';
 return {state,rows:observed,contradictions,gaps,aligned,coherent,primary};
}
function theoryRoadContradictionStateLabel(state){
 const map={
  contradiction:lang3('CONTRADDIZIONE OSSERVATA','OBSERVED CONTRADICTION','KONTRADIZZJONI OSSERVATA'),
  'transfer-gap':lang3('TRASFERIMENTO NON ANCORA INDIPENDENTE','TRANSFER NOT YET INDEPENDENT','TRASFERIMENT GĦADU MHUX INDIPENDENTI'),
  aligned:lang3('TEORIA E STRADA ALLINEATE','THEORY AND ROAD ALIGNED','TEORIJA U TRIQ ALLINJATI'),
  'coherent-weakness':lang3('DEBOLEZZA COERENTE, NON CONTRADDIZIONE','CONSISTENT WEAKNESS, NOT A CONTRADICTION','DGĦUFIJA KONSISTENTI, MHUX KONTRADIZZJONI'),
  insufficient:lang3('EVIDENZA INCROCIATA INSUFFICIENTE','INSUFFICIENT CROSS-EVIDENCE','EVIDENZA MQABBLA MHUX BIŻŻEJJED')
 };
 return map[state]||map.insufficient;
}
function theoryRoadContradictionTheoryText(row){
 if(row.theory.stable)return lang3('Stabilità teorica già verificata sullo stesso schema ricorrente.','Theory stability is already verified for the same pattern.','L-istabbiltà tat-teorija hija diġà vverifikata għall-istess mudell.');
 if(row.theory.status==='recent-perfect')return lang3('Ultime 5 risposte teoriche sullo stesso schema ricorrente: 5/5 corrette.','Latest 5 theory responses on the same pattern: 5/5 correct.','L-aħħar 5 tweġibiet tat-teorija fuq l-istess mudell: 5/5 korretti.');
 if(row.theory.recentCount)return lang3(`Teoria ancora in costruzione: ${row.theory.recentCorrect}/${row.theory.recentCount} corrette nelle risposte recenti disponibili.`,`Theory evidence is still building: ${row.theory.recentCorrect}/${row.theory.recentCount} correct in the available recent responses.`,`L-evidenza tat-teorija għadha qed tinbena: ${row.theory.recentCorrect}/${row.theory.recentCount} korretti fit-tweġibiet riċenti disponibbli.`);
 return lang3('Manca una verifica teorica recente sufficiente sullo stesso schema ricorrente.','There is not enough recent theory verification for the same pattern.','M’hemmx biżżejjed verifika riċenti tat-teorija għall-istess mudell.');
}
function theoryRoadContradictionRoadText(row){
 if(!row.road.available)return lang3('Nessuna verifica istruttore completata sullo stesso schema ricorrente.','No completed instructor road check exists for the same pattern.','M’hemm l-ebda kontroll fit-triq mill-istruttur komplut għall-istess mudell.');
 const score=row.road.score===null?'—':`${drivingTwinCount(row.road.score)}/100`;
 if(row.road.state==='repeat')return lang3(`Strada: ${score} · ${row.road.repeat} comportamenti da ripetere${row.road.help?` · ${row.road.help} con aiuto`:''}.`,`Road: ${score} · ${row.road.repeat} behaviours to repeat${row.road.help?` · ${row.road.help} with help`:''}.`,`Triq: ${score} · ${row.road.repeat} imġibiet biex jerġgħu jsiru${row.road.help?` · ${row.road.help} bl-għajnuna`:''}.`);
 if(row.road.state==='assisted')return lang3(`Strada: ${score} · ${row.road.help} comportamenti eseguiti con aiuto.`,`Road: ${score} · ${row.road.help} behaviours completed with help.`,`Triq: ${score} · ${row.road.help} imġibiet twettqu bl-għajnuna.`);
 if(row.road.state==='independent')return lang3(`Strada: ${score} · tutti i comportamenti osservati risultano indipendenti.`,`Road: ${score} · all observed behaviours are independent.`,`Triq: ${score} · l-imġibiet kollha osservati huma indipendenti.`);
 return lang3(`Verifica su strada registrata: ${score}.`,`Recorded road check: ${score}.`,`Kontroll fit-triq irreġistrat: ${score}.`);
}
function theoryRoadContradictionInterpretation(row){
 if(!row)return '';
 if(row.state==='contradiction')return lang3('La teoria è forte, ma sulla strada almeno un comportamento è stato segnato “Da ripetere”. La differenza è reale e riguarda lo stesso schema ricorrente.','Theory is strong, but on the road at least one behaviour was marked “Repeat”. The difference is real and concerns the same pattern.','It-teorija hija b’saħħitha, iżda fit-triq mill-inqas imġiba waħda ġiet immarkata “Erġa’ pprova”. Id-differenza hija reali u tirrigwarda l-istess mudell.');
 if(row.state==='transfer-gap')return lang3('La teoria è forte, ma l’esecuzione sulla strada ha ancora richiesto aiuto. È un divario di trasferimento, non una bocciatura della competenza.','Theory is strong, but road execution still required help. This is a transfer gap, not a failed competence judgement.','It-teorija hija b’saħħitha, iżda l-eżekuzzjoni fit-triq għadha kellha bżonn għajnuna. Dan huwa distakk fit-trasferiment, mhux ġudizzju ta’ falliment tal-kompetenza.');
 if(row.state==='aligned')return lang3('Le evidenze disponibili mostrano teoria forte e comportamento indipendente sullo stesso schema ricorrente.','Available evidence shows strong theory and independent road behaviour for the same pattern.','L-evidenza disponibbli turi teorija b’saħħitha u mġiba indipendenti fit-triq għall-istess mudell.');
 if(row.state==='coherent-weakness')return lang3('Teoria e strada mostrano entrambe una difficoltà: non viene dichiarata una contraddizione.','Theory and road both show difficulty, so no contradiction is declared.','It-teorija u t-triq it-tnejn juru diffikultà, għalhekk ma tiġix iddikjarata kontradizzjoni.');
 return lang3('Servono evidenze teoriche e stradali sufficienti sullo stesso schema ricorrente prima di confrontarle.','Sufficient theory and road evidence for the same pattern is required before comparing them.','Hemm bżonn biżżejjed evidenza tat-teorija u tat-triq għall-istess mudell qabel ma jitqabblu.');
}
function drivingTwinTheoryRoadContradictionHtml(){
 const data=drivingTwinTheoryRoadContradictionData(),row=data.primary;
 const state=data.state,label=theoryRoadContradictionStateLabel(state);
 const empty=!row;
 if(empty)return `<section class="driving-twin-theory-road insufficient"><div class="driving-twin-theory-road-head"><div><small>THEORY ↔ ROAD CONTRADICTION · ${esc(BUILD_VERSION)}</small><h3>${esc(label)}</h3><p>${esc(lang3('Confronta conoscenza teorica e comportamento reale soltanto quando esistono prove sullo stesso schema ricorrente.','Compares theory knowledge and real behaviour only when evidence exists for the same pattern.','Tqabbel l-għarfien tat-teorija u l-imġiba reali biss meta teżisti evidenza għall-istess mudell.'))}</p></div><span>↔</span></div><div class="driving-twin-theory-road-empty"><b>•</b><div><strong>${esc(lang3('Nessun confronto affidabile disponibile','No reliable comparison available','L-ebda tqabbil affidabbli mhu disponibbli'))}</strong><small>${esc(lang3('Continua a raccogliere teoria e verifiche istruttore sulla strada.','Keep collecting theory and instructor road checks.','Kompli iġbor teorija u kontrolli fit-triq mill-istruttur.'))}</small></div></div></section>`;
 const groupLabel=aiPatternLocalizedLabel(row.id,aiRecoveryText(row.group?.it||'',row.group?.en||''));
 const badge=state==='contradiction'?'!':state==='transfer-gap'?'↔':state==='aligned'?'✓':'•';
 const telemetryCount=typeof realRoadTelemetryStore==='object'&&Array.isArray(realRoadTelemetryStore.sessions)?realRoadTelemetryStore.sessions.length:0;
 return `<section class="driving-twin-theory-road ${esc(state)}"><div class="driving-twin-theory-road-head"><div><small>THEORY ↔ ROAD CONTRADICTION · ${esc(BUILD_VERSION)}</small><h3>${esc(label)}</h3><p>${esc(lang3('Cerca differenze reali tra ciò che lo studente dimostra di sapere e ciò che applica sulla strada.','Looks for real differences between what the student demonstrates in theory and what is applied on the road.','Tfittex differenzi reali bejn dak li l-istudent juri li jaf fit-teorija u dak li japplika fit-triq.'))}</p></div><span>${badge}</span></div><div class="driving-twin-theory-road-focus"><small>${esc(lang3('SCHEMA RICORRENTE CONFRONTATO','COMPARED PATTERN','MUDELL IMQABBEL'))}</small><strong>${esc(groupLabel)}</strong><p>${esc(theoryRoadContradictionInterpretation(row))}</p></div><div class="driving-twin-theory-road-columns"><article><small>${esc(lang3('TEORIA','THEORY','TEORIJA'))}</small><strong>${row.theory.supported?'✓':'○'} ${esc(row.theory.supported?lang3('Evidenza forte','Strong evidence','Evidenza b’saħħitha'):lang3('In costruzione','Building','Qed tinbena'))}</strong><p>${esc(theoryRoadContradictionTheoryText(row))}</p></article><article><small>${esc(lang3('STRADA','ROAD','TRIQ'))}</small><strong>${row.road.available?'✓':'○'} ${esc(row.road.available?lang3('Verifica registrata','Recorded check','Kontroll irreġistrat'):lang3('Da verificare','Needs verification','Jeħtieġ verifika'))}</strong><p>${esc(theoryRoadContradictionRoadText(row))}</p></article></div><div class="driving-twin-theory-road-metrics"><article><b>${data.contradictions.length}</b><span>${esc(lang3('contraddizioni osservate','observed contradictions','kontradizzjonijiet osservati'))}</span></article><article><b>${data.gaps.length}</b><span>${esc(lang3('divari di trasferimento','transfer gaps','distakki fit-trasferiment'))}</span></article><article><b>${data.aligned.length}</b><span>${esc(lang3('schemi allineati','aligned patterns','mudelli allinjati'))}</span></article></div>${(state==='contradiction'||state==='transfer-gap'||state==='coherent-weakness')?`<button class="btn driving-twin-theory-road-action" data-theory-road-pattern="${esc(row.id)}">${esc(lang3('Apri verifica pratica mirata','Open targeted road verification','Iftaħ verifika prattika mmirata'))} →</button>`:''}<p class="driving-twin-theory-road-rule">${esc(lang3(`Regola di integrità: il confronto usa solo teoria forte e verifica istruttore con lo stesso identificatore canonico dello schema ricorrente. ${telemetryCount} sessioni di telemetria tecnica disponibili non vengono interpretate automaticamente come comportamento finché non esiste il rilevamento eventi/validazione previsto nei passaggi successivi.`,`Integrity rule: comparison uses only strong theory and an instructor check with the exact same canonical pattern identifier. ${telemetryCount} technical telemetry sessions are available but are not automatically interpreted as behaviour until the later event-detection/validation stages exist.`,`Regola ta’ integrità: it-tqabbil juża biss teorija b’saħħitha u kontroll tal-istruttur bl-istess identifikatur kanoniku tal-mudell. ${telemetryCount} sessjonijiet ta’ telemetrija teknika huma disponibbli iżda ma jiġux interpretati awtomatikament bħala mġiba sakemm jiġu żviluppati l-istadji ta’ skoperta/validazzjoni tal-avvenimenti.`))}</p></section>`;
}
