// Build 45.8.6.1 — Measurement Closure / GitHub Hard Refresh Fix
// Closes the 45.8.5 measurement contract only with outcomes already recorded by a completed Twin Action Loop.
// No predicted result, synthetic score or inferred instructor verification is created here.
function drivingTwinLastVerifiedOutcomeHtml(){
 const history=Array.isArray(progress.drivingTwinLoopHistory)?progress.drivingTwinLoopHistory:[];
 const row=history.length?history[history.length-1]:null;
 if(!row||!row.completedAt){
  const title=lang3('ULTIMA MISURAZIONE CHIUSA','LATEST CLOSED MEASUREMENT','L-AĦĦAR KEJL MAGĦLUQ');
  const heading=lang3('Nessuna misurazione chiusa su questo ambiente','No closed measurement in this environment yet','Għad m’hemm l-ebda kejl magħluq f’dan l-ambjent');
  const detail=lang3('Completa un Twin Action Loop qui: il risultato reale verrà mostrato dopo il completamento. I dati locali di Koder e GitHub non vengono copiati o inventati.','Complete a Twin Action Loop here: the real result will appear after completion. Local Koder and GitHub data are not copied or invented.','Imla Twin Action Loop hawn: ir-riżultat reali jidher wara t-tlestija. Id-data lokali ta’ Koder u GitHub ma tiġix ikkupjata jew ivvintata.');
  return `<section class="driving-twin-measurement-closure driving-twin-measurement-closure-empty"><div class="driving-twin-measurement-closure-head"><div><small>${esc(title)}</small><h3>${esc(heading)}</h3></div><span class="open">• ${esc(lang3('In attesa di evidenza reale','Waiting for real evidence','Qed tistenna evidenza reali'))}</span></div><p class="driving-twin-measurement-closure-foot">${esc(detail)}</p></section>`;
 }
 const correct=drivingTwinCount(row.correct),total=drivingTwinCount(row.total),pct=drivingTwinPct(row.pct);
 const before=drivingTwinPct(row.baselineErrorRate),after=drivingTwinPct(row.afterErrorRate);
 const passed=Boolean(row.passed);
 const memory=drivingTwinMemoryFor(row.id)||{};
 const status=String(memory.status||'open');
 const statusText=status==='stable'
  ?lang3('Stabilità verificata','Stability verified','Stabbiltà vverifikata')
  :status==='recovered'
   ?lang3('Recupero completato · stabilità da riconfermare','Recovery completed · stability still to verify','Irkupru komplut · l-istabbiltà għadha trid tiġi vverifikata')
   :lang3('Schema ricorrente ancora aperto','Pattern still open','Ix-xejra għadha miftuħa');
 const verificationText=row.isMaintenance
  ?lang3('Controllo di mantenimento','Maintenance check','Kontroll ta’ manteniment')
  :row.isVerification
   ?lang3('Verifica di stabilità','Stability verification','Verifika tal-istabbiltà')
   :lang3('Ciclo di recupero','Recovery cycle','Ċiklu ta’ rkupru');
 const when=(()=>{try{return new Date(row.completedAt).toLocaleString()}catch(_){return ''}})();
 const delta=(before!==null&&after!==null)?Math.round(before-after):null;
 const deltaText=delta===null?'—':`${delta>0?'+':''}${delta} pt`;
 const resultText=total?`${correct}/${total}${pct!==null?` · ${pct}%`:''}`:'—';
 return `<section class="driving-twin-measurement-closure"><div class="driving-twin-measurement-closure-head"><div><small>${esc(lang3('ULTIMA MISURAZIONE CHIUSA','LATEST CLOSED MEASUREMENT','L-AĦĦAR KEJL MAGĦLUQ'))}</small><h3>${esc(verificationText)}</h3></div><span class="${passed?'verified':'open'}">${passed?'✓':'•'} ${esc(statusText)}</span></div><div class="driving-twin-measurement-closure-grid"><article><small>${esc(lang3('RISULTATO REALE','REAL RESULT','RIŻULTAT REALI'))}</small><b>${esc(resultText)}</b><p>${esc(lang3('Registrato al completamento','Recorded on completion','Irreġistrat mat-tlestija'))}</p></article><article><small>${esc(lang3('PRIMA → DOPO','BEFORE → AFTER','QABEL → WARA'))}</small><b>${esc(before===null||after===null?'—':`${before}% → ${after}%`)}</b><p>${esc(lang3(`Variazione ${deltaText}`,`Change ${deltaText}`,`Bidla ${deltaText}`))}</p></article><article><small>${esc(lang3('STATO EVIDENZA','EVIDENCE STATE','STAT TAL-EVIDENZA'))}</small><b>${esc(statusText)}</b><p>${esc(when)}</p></article></div><p class="driving-twin-measurement-closure-foot">${esc(lang3('Questa sezione usa solo il risultato realmente registrato dal Twin Action Loop. La competenza non viene dichiarata verificata finché le verifiche richieste non sono state completate.','This section uses only the result actually recorded by the Twin Action Loop. Competence is not declared verified until the required checks have been completed.','Din it-taqsima tuża biss ir-riżultat irreġistrat realment mit-Twin Action Loop. Il-kompetenza ma tiġix iddikjarata vverifikata sakemm jitlestew il-kontrolli meħtieġa.'))}</p></section>`;
}

function drivingTwinStatusText(score){
 if(score===null||score===undefined||!Number.isFinite(Number(score)))return lang3('IN OSSERVAZIONE','OBSERVING','TAĦT OSSERVAZZJONI');
 if(score>=85)return lang3('FORTE','STRONG','B’SAĦĦTU');
 if(score>=70)return lang3('BUONO','GOOD','TAJJEB');
 if(score>=50)return lang3('DA CONSOLIDARE','NEEDS CONSOLIDATION','JEĦTIEĠ KONSOLIDAZZJONI');
 return lang3('PRIORITÀ','PRIORITY','PRIJORITÀ');
}
function drivingTwinPatternMetric(item){
 const wrong=drivingTwinCount(item?.wrong);
 const attempts=drivingTwinCount(item?.attempts);
 const rate=attempts?drivingTwinClamp((wrong/attempts)*100):drivingTwinPct(item?.errorRate)||0;
 if(item?.stabilityConfirmed)return {main:'✓',sub:lang3('stabile','stable','stabbli')};
 if(item?.recentRecovery)return {main:'5/5',sub:lang3('recupero','recovery','irkupru')};
 return {main:String(wrong),sub:lang3(`errori · ${rate}%`,`errors · ${rate}%`,`żbalji · ${rate}%`)};
}

// Build 40.12.4 — ADAPTIVE MEMORY & STABILITY ENGINE
// The Twin now remembers corrective cycles over time and schedules spaced checks.
// State progression: OPEN -> RECOVERED -> STABLE -> periodic maintenance; any new error can reopen the pattern.
function drivingTwinMemoryIntervalDays(successfulChecks){
 const n=drivingTwinCount(successfulChecks);
 if(n<=1)return 1;
 if(n===2)return 7;
 if(n===3)return 14;
 return 30;
}
function drivingTwinMemoryIsoAfter(iso,days){
 const base=Date.parse(iso||'');
 const start=Number.isFinite(base)?base:Date.now();
 return new Date(start+Math.max(0,Number(days)||0)*24*60*60*1000).toISOString();
}
function drivingTwinMemoryEnsure(){
 const store=progress.drivingTwinMemory&&typeof progress.drivingTwinMemory==='object'?progress.drivingTwinMemory:{};
 let changed=!progress.drivingTwinMemory;
 const history=Array.isArray(progress.drivingTwinLoopHistory)?progress.drivingTwinLoopHistory:[];
 history.forEach(row=>{
  const id=String(row?.id||'');if(!id)return;
  const completedAt=String(row?.completedAt||row?.startedAt||new Date().toISOString());
  const existing=store[id];
  if(existing&&Date.parse(existing.lastCompletedAt||'')>=Date.parse(completedAt||''))return;
  const passed=Boolean(row?.passed),verification=Boolean(row?.isVerification);
  const rec=Object.assign({id,status:'open',successfulChecks:0,stableSince:'',lastStableAt:'',nextDueAt:'',lastCompletedAt:'',lastResultPct:0,lastQuestionIds:[],lastLeadId:''},existing||{});
  rec.lastCompletedAt=completedAt;rec.lastResultPct=drivingTwinCount(row?.pct);rec.lastQuestionIds=(Array.isArray(row?.questionIds)?row.questionIds:[]).map(String);rec.lastLeadId=String(row?.leadId||'');
  if(!passed){rec.status='open';rec.successfulChecks=0;rec.stableSince='';rec.nextDueAt=completedAt;}
  else if(verification){rec.status='stable';rec.successfulChecks=Math.max(2,drivingTwinCount(rec.successfulChecks)+1);rec.stableSince=rec.stableSince||completedAt;rec.lastStableAt=completedAt;rec.nextDueAt=drivingTwinMemoryIsoAfter(completedAt,drivingTwinMemoryIntervalDays(rec.successfulChecks));}
  else{rec.status='recovered';rec.successfulChecks=Math.max(1,drivingTwinCount(rec.successfulChecks));rec.nextDueAt=drivingTwinMemoryIsoAfter(completedAt,1);}
  store[id]=rec;changed=true;
 });
 progress.drivingTwinMemory=store;
 if(changed)save(STORAGE,progress);
 return store;
}
function drivingTwinMemoryFor(id){
 id=String(id||'');const store=drivingTwinMemoryEnsure(),rec=store[id];if(!rec)return null;
 // A new wrong answer after a stable confirmation reopens the pattern immediately.
 if(rec.status==='stable'&&rec.stableSince){
  const stableTs=Date.parse(rec.stableSince);
  const wrongAfter=(progress.responseHistory||[]).some(row=>!row?.ok&&aiPatternGroupForHistory(row)===id&&Date.parse(row?.ts||'')>stableTs);
  if(wrongAfter){rec.status='open';rec.successfulChecks=0;rec.stableSince='';rec.nextDueAt=new Date().toISOString();save(STORAGE,progress);}
 }
 return rec;
}
function drivingTwinMemoryIsDue(rec){
 if(!rec)return true;const due=Date.parse(rec.nextDueAt||'');return !Number.isFinite(due)||Date.now()>=due;
}
function drivingTwinMemoryDueText(rec){
 if(!rec||drivingTwinMemoryIsDue(rec))return lang3('Adesso','Now','Issa');
 const due=Date.parse(rec.nextDueAt||''),delta=Math.max(0,due-Date.now()),hours=Math.ceil(delta/(60*60*1000));
 if(hours<=24)return hours===1?lang3('tra 1 ora','in 1 hour','fi siegħa'):lang3(`tra ${hours} ore`,`in ${hours} hours`,`fi ${hours} sigħat`);
 const days=Math.ceil(hours/24);return days===1?lang3('domani','tomorrow','għada'):lang3(`tra ${days} giorni`,`in ${days} days`,`fi ${days} ijiem`);
}
function drivingTwinMemoryStatusText(rec){
 if(!rec)return '';
 if(rec.status==='stable')return lang3('STABILE','STABLE','STABBLI');
 if(rec.status==='recovered')return lang3('RECUPERATO · IN CONSOLIDAMENTO','RECOVERED · CONSOLIDATING','IRKUPRAT · QED JIKKONSOLIDA');
 return lang3('PATTERN APERTO','OPEN PATTERN','MUDELL MIFTUĦ');
}
function drivingTwinMemoryRows(){
 const store=drivingTwinMemoryEnsure();
 return Object.values(store).filter(rec=>AI_PATTERN_GROUPS.some(g=>g.id===rec.id)).sort((a,b)=>{
  const ad=drivingTwinMemoryIsDue(a)?0:1,bd=drivingTwinMemoryIsDue(b)?0:1;
  return ad-bd||Date.parse(b.lastCompletedAt||0)-Date.parse(a.lastCompletedAt||0);
 });
}
function drivingTwinMemoryHtml(){
 const rows=drivingTwinMemoryRows().slice(0,4);
 if(!rows.length)return '';
 const cards=rows.map(rec=>{
  const group=AI_PATTERN_GROUPS.find(g=>g.id===rec.id);if(!group)return '';
  const due=drivingTwinMemoryDueText(rec),status=drivingTwinMemoryStatusText(rec),pct=drivingTwinCount(rec.lastResultPct);
  const action=rec.status==='stable'?lang3('Prossimo controllo di mantenimento','Next maintenance check','Il-kontroll ta’ manteniment li jmiss'):rec.status==='recovered'?lang3('Verifica di stabilità','Stability verification','Verifika tal-istabbiltà'):lang3('Nuovo recupero','Next recovery','Irkupru li jmiss');
  return `<article class="driving-twin-memory-row ${esc(rec.status)}"><span>${group.icon||'🧠'}</span><div><small>${esc(status)}</small><h3>${esc(aiRecoveryText(group.it,group.en))}</h3><p>${esc(action)} · <strong>${esc(due)}</strong></p></div><b>${pct}%</b></article>`;
 }).join('');
 return `<section class="card driving-twin-memory"><div class="driving-twin-section-head"><div><small>${esc(lang3('ADAPTIVE MEMORY','ADAPTIVE MEMORY','MEMORJA ADATTIVA'))}</small><h2>${esc(lang3('Il Twin ricorda nel tempo','The Twin remembers over time','It-Twin jiftakar maż-żmien'))}</h2><p>${esc(lang3('Un buon risultato non cancella lo schema ricorrente: il Twin lo ricontrolla a distanza crescente — 1, 7, 14 e 30 giorni.','A good result does not erase a pattern: the Twin rechecks it at increasing intervals — 1, 7, 14 and 30 days.','Riżultat tajjeb ma jħassarx il-mudell: it-Twin jerġa’ jiċċekkjah b’intervalli ta’ 1, 7, 14 u 30 jum.'))}</p></div><span>🧠</span></div><div class="driving-twin-memory-list">${cards}</div></section>`;
}


// Build 45.8.18 — SKILL DECAY & SMART RECALL
// Formalizes the existing 1/7/14/30-day adaptive-memory schedule into an evidence-safe
// retention layer. Time alone is NEVER treated as proof that competence has been lost.
// A real new error can reopen a previously stable schema; otherwise the engine only
// schedules a due recall and waits for a new measured result.
function drivingTwinSkillDecayRow(rec){
 if(!rec)return null;
 const group=AI_PATTERN_GROUPS.find(g=>g.id===String(rec.id||''));if(!group)return null;
 const now=Date.now();
 const last=Date.parse(rec.lastCompletedAt||'');
 const due=Date.parse(rec.nextDueAt||'');
 const lastStable=Date.parse(rec.lastStableAt||'');
 const isDue=drivingTwinMemoryIsDue(rec);
 const wrongAfterStable=Number.isFinite(lastStable)&&(progress.responseHistory||[]).some(row=>!row?.ok&&aiPatternGroupForHistory(row)===String(rec.id||'')&&Date.parse(row?.ts||'')>lastStable);
 const reopened=String(rec.status||'')==='open'&&wrongAfterStable;
 const scheduled=String(rec.status||'')==='recovered'||String(rec.status||'')==='stable';
 let state='monitoring';
 if(reopened)state='observed';
 else if(String(rec.status||'')==='open')state='open';
 else if(isDue)state='due';
 else if(Number.isFinite(last)&&Number.isFinite(due)&&due>last&&now>=last+((due-last)*0.7))state='approaching';
 const stateLabel={
  observed:lang3('CALO OSSERVATO','OBSERVED DECLINE','TNAQQIS OSSERVAT'),
  open:lang3('RECUPERO APERTO','RECOVERY OPEN','IRKUPRU MIFTUĦ'),
  due:lang3('RICHIAMO DOVUTO','RECALL DUE','TIFKIRA DOVUTA'),
  approaching:lang3('RICHIAMO IN AVVICINAMENTO','RECALL APPROACHING','TIFKIRA QRIB'),
  monitoring:lang3('STABILITÀ MONITORATA','STABILITY MONITORED','STABBILTÀ MONITORATA')
 }[state];
 const actionLabel=reopened||String(rec.status||'')==='open'
  ?lang3('Avvia micro-recupero','Start micro-recovery','Ibda mikro-irkupru')
  :isDue
   ?lang3('Avvia richiamo mirato','Start targeted recall','Ibda tifkira mmirata')
   :lang3('Richiamo già programmato','Recall already scheduled','Tifkira diġà ppjanata');
 const dueText=drivingTwinMemoryDueText(rec);
 const successfulChecks=drivingTwinCount(rec.successfulChecks);
 const checkCount=lang3(successfulChecks===1?'1 verifica riuscita':`${successfulChecks} verifiche riuscite`,successfulChecks===1?'1 successful check':`${successfulChecks} successful checks`,successfulChecks===1?'verifika waħda rnexxiet':`${successfulChecks} verifiki rnexxew`);
 const evidenceText=lang3(
  `Ultimo risultato reale ${drivingTwinCount(rec.lastResultPct)}% · ${checkCount}`,
  `Last real result ${drivingTwinCount(rec.lastResultPct)}% · ${checkCount}`,
  `L-aħħar riżultat reali ${drivingTwinCount(rec.lastResultPct)}% · ${checkCount}`
 );
 return {id:String(rec.id||''),group,rec,state,stateLabel,actionLabel,dueText,evidenceText,isDue,reopened,scheduled,dueAt:Number.isFinite(due)?due:Infinity,lastAt:Number.isFinite(last)?last:0};
}
function drivingTwinSkillDecayData(){
 const rows=drivingTwinMemoryRows().map(rec=>drivingTwinMemoryFor(rec.id)||rec).map(drivingTwinSkillDecayRow).filter(Boolean).sort((a,b)=>{
  const rank=x=>x.reopened?0:(x.state==='open'?1:(x.isDue?2:(x.state==='approaching'?3:4)));
  return rank(a)-rank(b)||a.dueAt-b.dueAt||b.lastAt-a.lastAt;
 });
 const due=rows.filter(x=>x.isDue||x.reopened||x.state==='open').length;
 const scheduled=rows.filter(x=>x.scheduled&&!x.isDue).length;
 const observed=rows.filter(x=>x.reopened).length;
 return {rows,due,scheduled,observed,next:rows[0]||null};
}
