function drivingTwinLoopRecordResult(id,correct,total){
 const state=drivingTwinLoopState();
 if(!state?.active||String(state.id)!==String(id))return null;
 const pct=total?Math.round(correct/total*100):0,passed=total>=5&&correct===total;
 const afterErrorRate=Math.max(0,100-pct),baselineErrorRate=drivingTwinPct(state.baselineErrorRate)||0,improvement=Math.round(baselineErrorRate-afterErrorRate);
 state.stage='complete';state.completedAt=new Date().toISOString();state.lastResult={correct,total,pct,passed,baselineErrorRate,afterErrorRate,improvement};
 progress.drivingTwinLoop=state;
 progress.drivingTwinLoopHistory=Array.isArray(progress.drivingTwinLoopHistory)?progress.drivingTwinLoopHistory:[];
 progress.drivingTwinLoopHistory.push({id:state.id,startedAt:state.startedAt,completedAt:state.completedAt,replayCompletedAt:state.replayCompletedAt||'',leadId:state.leadId,questionIds:state.questionIds,isVerification:Boolean(state.isVerification),isMaintenance:Boolean(state.isMaintenance),correct,total,pct,passed,baselineErrorRate,afterErrorRate,improvement});
 progress.drivingTwinLoopHistory=progress.drivingTwinLoopHistory.slice(-80);
 if(state.isVerification){
  progress.patternStability=progress.patternStability&&typeof progress.patternStability==='object'?progress.patternStability:{};
  progress.patternStability[state.id]={passed,correct,total,ts:state.completedAt,questionIds:state.questionIds,sourceQuestionIds:Array.isArray(state.sourceQuestionIds)?state.sourceQuestionIds:[]};
 }
 const store=drivingTwinMemoryEnsure();
 const rec=Object.assign({id:state.id,status:'open',successfulChecks:0,stableSince:'',lastStableAt:'',nextDueAt:'',lastCompletedAt:'',lastResultPct:0,lastQuestionIds:[],lastLeadId:''},store[state.id]||{});
 rec.lastCompletedAt=state.completedAt;rec.lastResultPct=pct;rec.lastQuestionIds=(state.questionIds||[]).map(String);rec.lastLeadId=String(state.leadId||'');
 if(!passed){rec.status='open';rec.successfulChecks=0;rec.stableSince='';rec.nextDueAt=state.completedAt;}
 else if(state.isVerification){rec.status='stable';rec.successfulChecks=Math.max(2,drivingTwinCount(rec.successfulChecks)+1);rec.stableSince=rec.stableSince||state.completedAt;rec.lastStableAt=state.completedAt;rec.nextDueAt=drivingTwinMemoryIsoAfter(state.completedAt,drivingTwinMemoryIntervalDays(rec.successfulChecks));}
 else{rec.status='recovered';rec.successfulChecks=1;rec.nextDueAt=drivingTwinMemoryIsoAfter(state.completedAt,1);}
 store[state.id]=rec;progress.drivingTwinMemory=store;
 save(STORAGE,progress);
 return state.lastResult;
}

