function bindDrivingTwin(){
 screen.querySelectorAll('[data-twin-pattern-road]').forEach(card=>{
  const open=()=>{if(realRoadSelectPattern(card.dataset.twinPatternRoad))go('realroad')};
  card.onclick=open;
  card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}};
 });
 screen.querySelectorAll('[data-theory-road-pattern]').forEach(button=>button.onclick=()=>{if(realRoadSelectPattern(button.dataset.theoryRoadPattern))go('realroad')});
 screen.querySelectorAll('[data-driving-twin-action]').forEach(button=>button.onclick=()=>{
  const type=button.dataset.drivingTwinAction,id=button.dataset.drivingTwinId||'';
  if(type==='wait')return toast(String(drivingTwinNextAction().detail||lang3('Verifica programmata.','Check scheduled.','Verifika ppjanata.')));
  if(type==='pattern')return drivingTwinLoopStart(id);
  if(type==='road'){if(id&&realRoadSelectPattern(id))return go('realroad');return go('realroad')}
  if(type==='bridge')return go('bridgesetup');
  if(type==='replay')return go('errorreplay');
  if(type==='study')return go('studysetup');
  if(type==='exam')return go('examsetup');
  return go('aiinstructor');
 });
 const copy=$('#copyDrivingTwinBrief');if(copy)copy.onclick=()=>copyTextSafe(drivingTwinInstructorBrief(),lang3('Brief copiato.','Brief copied.','Brief ikkupjat.'));
 const share=$('#shareDrivingTwinBrief');if(share)share.onclick=()=>shareTextReport('MDM Driving Twin',drivingTwinInstructorBrief(),lang3('Brief copiato.','Brief copied.','Brief ikkupjat.'));
}


/* ================================================================
   Build 40.13.3 — PERSONAL DRIVING ENGLISH & ADAPTIVE FADING
   Exam language and support language are separate concepts.
   Malta active packs: English, Italian, Maltese.
   The engine is pack-based so additional support languages can be
   registered later without rewriting the diagnostic logic.
   ================================================================ */
const LANGUAGE_TWIN_KEY='mdm-language-twin-v1';
const LANGUAGE_TWIN_PACKS={
 en:{code:'en',name:'English',nativeName:'English',flag:'🇬🇧',active:true},
 it:{code:'it',name:'Italian',nativeName:'Italiano',flag:'🇮🇹',active:true},
 mt:{code:'mt',name:'Maltese',nativeName:'Malti',flag:'🇲🇹',active:true}
};
window.MDM_LANGUAGE_PACKS=Object.assign({},window.MDM_LANGUAGE_PACKS||{},LANGUAGE_TWIN_PACKS);
const LANGUAGE_TWIN_DEFAULT={examLanguage:'en',supportLanguage:'it',displayMode:'bilingual',diagnostics:[],difficultTerms:{},termMemory:{},lastUpdated:''};
let languageTwin=Object.assign({},LANGUAGE_TWIN_DEFAULT,load(LANGUAGE_TWIN_KEY,{}));
languageTwin.diagnostics=Array.isArray(languageTwin.diagnostics)?languageTwin.diagnostics:[];
languageTwin.difficultTerms=languageTwin.difficultTerms&&typeof languageTwin.difficultTerms==='object'?languageTwin.difficultTerms:{};
languageTwin.termMemory=languageTwin.termMemory&&typeof languageTwin.termMemory==='object'?languageTwin.termMemory:{};
Object.entries(languageTwin.difficultTerms).forEach(([term,count])=>{if(!languageTwin.termMemory[term])languageTwin.termMemory[term]={term,gapCount:Number(count)||0,successCount:0,recoveryStreak:0,status:'critical',lastSeen:'',lastGap:''}});
let languageTwinDiagnostic=null;
function languageTwinSave(){languageTwin.lastUpdated=new Date().toISOString();save(LANGUAGE_TWIN_KEY,languageTwin)}
function languageTwinPack(code){return (window.MDM_LANGUAGE_PACKS||{})[code]||LANGUAGE_TWIN_PACKS.en}
function languageTwinText(q,code){
 if(!q)return '';
 if(code==='it')return q.question_it||q.question||'';
 if(code==='mt')return q.question_mt||q.question||'';
 return q.question||'';
}
function languageTwinAnswers(q,code){
 if(!q)return [];
 if(code==='it'&&Array.isArray(q.answers_it)&&q.answers_it.length===q.answers.length)return q.answers_it;
 if(code==='mt'&&Array.isArray(q.answers_mt)&&q.answers_mt.length===q.answers.length)return q.answers_mt;
 return Array.isArray(q.answers)?q.answers:[];
}
function languageTwinExplanation(q,code){
 if(!q)return '';
 if(code==='it')return q.explanation_it||q.explanation||'';
 if(code==='mt')return q.explanation_mt||q.explanation||'';
 return q.explanation||'';
}
function languageTwinQuestionHasPack(q,code){
 if(code==='en')return Boolean(q?.question&&Array.isArray(q?.answers));
 const txt=languageTwinText(q,code),answers=languageTwinAnswers(q,code);
 return Boolean(txt&&Array.isArray(answers)&&answers.length===q.answers.length);
}
function languageTwinEligibleQuestions(code=languageTwin.supportLanguage){return Q.filter(q=>languageTwinQuestionHasPack(q,code)&&languageTwinQuestionHasPack(q,'en'))}
function languageTwinLatest(){return languageTwin.diagnostics.at(-1)||null}
function languageTwinGapIds(){const r=languageTwinLatest();return new Set(Array.isArray(r?.languageGapIds)?r.languageGapIds:[])}
function languageTwinModeLabel(mode=languageTwin.displayMode){
 const map={exam:lang3('Solo inglese d’esame','Exam English only','Ingliż tal-eżami biss'),support:lang3('Solo lingua di supporto','Support language only','Lingwa ta’ appoġġ biss'),bilingual:lang3('Inglese + supporto','English + support','Ingliż + appoġġ'),adaptive:lang3('Supporto adattivo Twin','Twin adaptive support','Appoġġ adattiv Twin')};
 return map[mode]||map.bilingual;
}
function languageTwinSupportLabel(){const p=languageTwinPack(languageTwin.supportLanguage);return `${p.flag||''} ${p.nativeName||p.name||p.code}`.trim()}
function quizLanguageTwinLabel(){return isMalteseMode()?lang3('Solo maltese','Maltese only','Malti biss'):isItalianAssisted()?languageTwinModeLabel():lang3('Solo inglese','English only','Ingliż biss')}
function languageTwinStudyText(q){
 if(!q)return '';
 if(quiz?.mode==='exam')return languageTwinText(q,languageTwin.examLanguage);
 // App-language contract: IT = official English + Italian support; EN = English only; MT = Maltese only.
 if(isMalteseMode())return languageTwinText(q,'mt');
 if(!isItalianAssisted())return languageTwinText(q,'en');
 const mode=languageTwin.displayMode;
 if(mode==='support')return languageTwinText(q,languageTwin.supportLanguage);
 return languageTwinText(q,languageTwin.examLanguage);
}
function languageTwinStudyAnswers(q){
 if(!q)return [];
 if(quiz?.mode==='exam')return languageTwinAnswers(q,languageTwin.examLanguage);
 if(isMalteseMode())return languageTwinAnswers(q,'mt');
 if(!isItalianAssisted())return languageTwinAnswers(q,'en');
 if(languageTwin.displayMode==='support')return languageTwinAnswers(q,languageTwin.supportLanguage);
 return languageTwinAnswers(q,languageTwin.examLanguage);
}
function languageTwinQuestionTerms(q){
 if(!q)return [];
 const hay=`${q.question||''} ${(q.answers||[]).join(' ')}`.toLowerCase();
 return GLOSSARY.filter(item=>hay.includes(String(item.term||'').toLowerCase())).map(item=>item.term);
}
function languageTwinTermTranslation(term,code=languageTwin.supportLanguage){
 const pack=languageTwinPack(code),item=GLOSSARY.find(x=>x.term===term);
 if(pack&&pack.terms&&pack.terms[term])return pack.terms[term];
 if(code==='it')return item?.it||'';
 if(code==='mt')return item?.mt||'';
 return item?.[code]||'';
}
function languageTwinTermState(term){
 const row=languageTwin.termMemory?.[term];
 if(!row)return 'unseen';
 if(row.status==='mastered'||Number(row.recoveryStreak)>=2)return 'mastered';
 if(Number(row.gapCount)>0&&Number(row.recoveryStreak)>0)return 'learning';
 if(Number(row.gapCount)>0)return 'critical';
 return 'observed';
}
function languageTwinAdaptiveTerms(q){
 return languageTwinQuestionTerms(q).map(term=>({term,state:languageTwinTermState(term),translation:languageTwinTermTranslation(term)})).filter(x=>x.state==='critical'||x.state==='learning').slice(0,4);
}
function languageTwinShouldShowSupport(q){
 // Support panes belong only to the Italian-assisted app mode. EN and MT are strict single-language modes.
 if(!isItalianAssisted()||!q||quiz?.mode==='exam'||languageTwin.supportLanguage===languageTwin.examLanguage)return false;
 if(languageTwin.displayMode==='bilingual')return true;
 if(languageTwin.displayMode==='adaptive'){
  const gaps=languageTwinGapIds();
  if(!languageTwin.diagnostics.length)return true;
  // Full translation is kept only for the exact concepts recently diagnosed as language gaps.
  // Other questions progressively fade to word-level hints and then to pure Exam English.
  return gaps.has(q.id);
 }
 return false;
}
function languageTwinAdaptiveHintsHtml(q){
 if(!isItalianAssisted()||!q||quiz?.mode==='exam'||languageTwin.displayMode!=='adaptive'||languageTwinShouldShowSupport(q))return '';
 const terms=languageTwinAdaptiveTerms(q).filter(x=>x.translation);
 if(!terms.length)return '';
 return `<div class="language-twin-word-hints"><small>${esc(lang3('AIUTO MINIMO · SOLO LE PAROLE CHE IL TWIN STA ANCORA CONSOLIDANDO','MINIMAL HELP · ONLY WORDS THE TWIN IS STILL CONSOLIDATING','GĦAJNUNA MINIMA · IL-KLIEM LI T-TWIN GĦADU QED JIKKONSOLIDA'))}</small><div>${terms.map(x=>`<span><b>${esc(x.term)}</b> → ${esc(x.translation)}</span>`).join('')}</div></div>`;
}
function languageTwinSupportQuestion(q){return languageTwinText(q,languageTwin.supportLanguage)}
function languageTwinSupportAnswers(q){return languageTwinAnswers(q,languageTwin.supportLanguage)}
function languageTwinExtractTerms(ids){
 const found=[];
 ids.map(id=>Q.find(q=>q.id===id)).filter(Boolean).forEach(q=>languageTwinQuestionTerms(q).forEach(term=>{if(!found.includes(term))found.push(term)}));
 return found.slice(0,8).map(term=>{const item=GLOSSARY.find(x=>x.term===term)||{};return {term,it:item.it,tag:item.tag};});
}
function languageTwinUpdateTermMemory(q,outcome){
 const now=new Date().toISOString();
 languageTwinQuestionTerms(q).forEach(term=>{
  const row=languageTwin.termMemory[term]||{term,gapCount:0,successCount:0,recoveryStreak:0,status:'observed',lastSeen:'',lastGap:''};
  row.lastSeen=now;
  if(outcome==='language-gap'){
   row.gapCount=Number(row.gapCount||0)+1;row.recoveryStreak=0;row.status='critical';row.lastGap=now;
  }else if(outcome==='mastered'&&Number(row.gapCount||0)>0){
   row.successCount=Number(row.successCount||0)+1;row.recoveryStreak=Number(row.recoveryStreak||0)+1;row.status=row.recoveryStreak>=2?'mastered':'learning';
  }
  languageTwin.termMemory[term]=row;
 });
}
function languageTwinPersonalTerms(limit=10){
 return Object.values(languageTwin.termMemory||{}).filter(row=>Number(row.gapCount||0)>0).sort((a,b)=>{
  const rank={critical:0,learning:1,mastered:2};
  return (rank[a.status]??3)-(rank[b.status]??3)||Number(b.gapCount||0)-Number(a.gapCount||0)||String(b.lastSeen||'').localeCompare(String(a.lastSeen||''));
 }).slice(0,limit);
}
function languageTwinProfile(){
 const rows=Array.isArray(languageTwin.diagnostics)?languageTwin.diagnostics:[];
 if(!rows.length)return {score:null,rawAccuracy:null,evidence:0,label:lang3('IN OSSERVAZIONE','OBSERVING','TAĦT OSSERVAZZJONI'),languageGaps:0,knowledgeGaps:0,mastered:0,total:0};
 let mastered=0,languageGaps=0,knowledgeGaps=0,total=0;
 rows.forEach(r=>{
  mastered+=Array.isArray(r?.masteredIds)?r.masteredIds.length:0;
  languageGaps+=Array.isArray(r?.languageGapIds)?r.languageGapIds.length:0;
  knowledgeGaps+=Array.isArray(r?.knowledgeGapIds)?r.knowledgeGapIds.length:0;
  total+=Number(r?.total)||0;
 });
 // Language independence is measured only where the rule is known in the support language.
 // A small neutral prior prevents a five-question perfect test from becoming a global 100% profile.
 const evidence=mastered+languageGaps;
 const rawAccuracy=evidence?Math.round(mastered/evidence*100):null;
 const score=evidence?Math.round(((mastered+2)/(evidence+4))*100):null;
 return {score,rawAccuracy,evidence,label:score===null?lang3('IN OSSERVAZIONE','OBSERVING','TAĦT OSSERVAZZJONI'):score>=85?lang3('FORTE','STRONG','B’SAĦĦTU'):score>=70?lang3('BUONO','GOOD','TAJJEB'):lang3('DA RINFORZARE','NEEDS SUPPORT','JEĦTIEĠ APPOĠĠ'),languageGaps,knowledgeGaps,mastered,total};
}
function languageTwinBuildDiagnostic(count=5){
 const pool=languageTwinEligibleQuestions(languageTwin.supportLanguage);
 const gapFocus=[...languageTwinGapIds()].map(id=>Q.find(q=>q.id===id)).filter(q=>q&&pool.some(p=>p.id===q.id));
 const list=[],used=new Set();
 shuffle(gapFocus).forEach(q=>{if(list.length<count&&!used.has(q.id)){list.push(q);used.add(q.id)}});
 shuffle(pool).forEach(q=>{if(list.length<count&&!used.has(q.id)){list.push(q);used.add(q.id)}});
 return list.slice(0,count);
}
function startLanguageTwinDiagnostic(count=5){
 if(languageTwin.supportLanguage==='en')return toast(lang3('Scegli una lingua di supporto diversa dall’inglese per la diagnosi.','Choose a support language different from English for diagnosis.','Agħżel lingwa ta’ appoġġ differenti mill-Ingliż għad-dijanjosi.'));
 const list=languageTwinBuildDiagnostic(Math.max(3,Number(count)||5));
 if(!list.length)return toast(t('noResults'));
 languageTwinDiagnostic={list,phase:'support',index:0,selected:[],supportAnswers:{},examAnswers:{},examOrder:shuffle(list.map(q=>q.id)),startedAt:new Date().toISOString()};
 go('languagetwinquiz');
}
function languageTwinCurrentDiagnosticQuestion(){
 if(!languageTwinDiagnostic)return null;
 if(languageTwinDiagnostic.phase==='support')return languageTwinDiagnostic.list[languageTwinDiagnostic.index]||null;
 const id=languageTwinDiagnostic.examOrder[languageTwinDiagnostic.index];
 return languageTwinDiagnostic.list.find(q=>q.id===id)||null;
}
function languageTwinDiagnosticComplete(){
 const list=languageTwinDiagnostic.list,mastered=[],languageGap=[],knowledgeGap=[],examOnly=[];
 let supportCorrect=0,examCorrect=0;
 list.forEach(q=>{
  const sOk=answerIsCorrect(q,languageTwinDiagnostic.supportAnswers[q.id]);
  const eOk=answerIsCorrect(q,languageTwinDiagnostic.examAnswers[q.id]);
  if(sOk)supportCorrect++;if(eOk)examCorrect++;
  if(sOk&&eOk){mastered.push(q.id);languageTwinUpdateTermMemory(q,'mastered')}
  else if(sOk&&!eOk){languageGap.push(q.id);languageTwinUpdateTermMemory(q,'language-gap')}
  else if(!sOk&&!eOk)knowledgeGap.push(q.id);
  else examOnly.push(q.id);
 });
 const result={id:`LT-${Date.now().toString(36).toUpperCase()}`,date:new Date().toISOString(),examLanguage:languageTwin.examLanguage,supportLanguage:languageTwin.supportLanguage,total:list.length,supportCorrect,examCorrect,supportPct:Math.round(supportCorrect/list.length*100),examPct:Math.round(examCorrect/list.length*100),masteredIds:mastered,languageGapIds:languageGap,knowledgeGapIds:knowledgeGap,examOnlyIds:examOnly,terms:languageTwinExtractTerms(languageGap)};
 result.terms.forEach(term=>languageTwin.difficultTerms[term.term]=Number(languageTwin.difficultTerms[term.term]||0)+1);
 languageTwin.diagnostics.push(result);languageTwin.diagnostics=languageTwin.diagnostics.slice(-30);languageTwinSave();
 languageTwinDiagnostic=null;go('languagetwinresult',result.id);
}
function confirmLanguageTwinDiagnostic(){
 const q=languageTwinCurrentDiagnosticQuestion();if(!q)return;
 if(languageTwinDiagnostic.selected.length!==q.correct.length)return toast(q.correct.length===1?t('selectOne'):t('selectMany',q.correct.length));
 const key=languageTwinDiagnostic.phase==='support'?'supportAnswers':'examAnswers';languageTwinDiagnostic[key][q.id]=[...languageTwinDiagnostic.selected];languageTwinDiagnostic.selected=[];
 if(languageTwinDiagnostic.index<languageTwinDiagnostic.list.length-1){languageTwinDiagnostic.index++;renderLanguageTwinQuiz();return}
 if(languageTwinDiagnostic.phase==='support'){languageTwinDiagnostic.phase='exam';languageTwinDiagnostic.index=0;toast(lang3('Ora le stesse regole in inglese d’esame.','Now the same rules in exam English.','Issa l-istess regoli bl-Ingliż tal-eżami.'));renderLanguageTwinQuiz();return}
 languageTwinDiagnosticComplete();
}
function renderLanguageTwinQuiz(){
 if(!languageTwinDiagnostic){go('languagetwin');return}
 const q=languageTwinCurrentDiagnosticQuestion(),support=languageTwinDiagnostic.phase==='support';
 const total=languageTwinDiagnostic.list.length*2,done=(support?0:languageTwinDiagnostic.list.length)+languageTwinDiagnostic.index;
 const pack=languageTwinPack(languageTwin.supportLanguage),code=support?languageTwin.supportLanguage:languageTwin.examLanguage;
 $('#languageTwinPhase').textContent=support?`${pack.flag} ${pack.nativeName}`:lang3('🇬🇧 Inglese d’esame','🇬🇧 Exam English','🇬🇧 Ingliż tal-eżami');
 $('#languageTwinCounter').textContent=`${done+1}/${total}`;$('#languageTwinProgress').style.width=`${Math.round(done/total*100)}%`;
 $('#languageTwinQuestion').textContent=languageTwinText(q,code);
 $('#languageTwinInstruction').textContent=q.correct.length===1?t('selectOne'):t('selectMany',q.correct.length);
 const answers=languageTwinAnswers(q,code);
 $('#languageTwinOptions').innerHTML=answers.map((answer,i)=>`<button class="option ${languageTwinDiagnostic.selected.includes(i)?'selected':''}" data-lt-opt="${i}"><span class="option-main"><strong>${String.fromCharCode(65+i)}.</strong> ${esc(answer)}</span></button>`).join('');
 screen.querySelectorAll('[data-lt-opt]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.ltOpt),max=q.correct.length;if(languageTwinDiagnostic.selected.includes(i))languageTwinDiagnostic.selected=languageTwinDiagnostic.selected.filter(x=>x!==i);else{if(languageTwinDiagnostic.selected.length>=max)return toast(max===1?t('selectOne'):t('selectMany',max));languageTwinDiagnostic.selected.push(i)}renderLanguageTwinQuiz()});
 $('#languageTwinConfirm').onclick=confirmLanguageTwinDiagnostic;
 $('#languageTwinExit').onclick=()=>{if(confirm(t('exit')+'?')){languageTwinDiagnostic=null;go('languagetwin')}};
}
function languageTwinResultById(id){return languageTwin.diagnostics.find(x=>x.id===id)||languageTwinLatest()}
function languageTwinViewHtml(){
 const profile=languageTwinProfile(),last=languageTwinLatest(),support=languageTwinPack(languageTwin.supportLanguage);
 const difficult=languageTwinPersonalTerms(8);
 return `<div class="section-title language-twin-title"><div><h2>🌐 ${esc(lang3('MDM Twin linguistico d’esame','MDM Exam Language Twin','MDM Twin tal-lingwa tal-eżami'))}</h2><p>${esc(lang3('Separa la conoscenza della regola dalla comprensione della lingua d’esame.','Separates rule knowledge from exam-language comprehension.','Jissepara l-għarfien tar-regola mill-fehim tal-lingwa tal-eżami.'))}</p></div><span class="badge official">Build ${esc(BUILD_VERSION)}</span></div>
 <section class="language-twin-hero"><small>UNIVERSAL LANGUAGE ENGINE</small><h1>${esc(lang3('Impara nella tua lingua. Passa l’esame nella sua.','Learn in your language. Pass the exam in its language.','Tgħallem bil-lingwa tiegħek. Għaddi l-eżami bil-lingwa tiegħu.'))}</h1><p>${esc(lang3('A Malta la lingua d’esame resta English. La lingua di supporto può cambiare senza cambiare il motore.','In Malta the exam language remains English. The support language can change without changing the engine.','F’Malta l-lingwa tal-eżami tibqa’ l-Ingliż. Il-lingwa ta’ appoġġ tista’ tinbidel mingħajr ma jinbidel il-magna.'))}</p><div class="language-twin-hero-pills"><span>🇬🇧 Exam: English</span><span>${esc(languageTwinSupportLabel())} Support</span><span>${esc(languageTwinModeLabel())}</span></div></section>
 <section class="card language-twin-config"><div class="language-twin-section-head"><div><small>${esc(lang3('CONFIGURAZIONE','CONFIGURATION','KONFIGURAZZJONI'))}</small><h2>${esc(lang3('Due lingue, un solo percorso','Two languages, one learning path','Żewġ lingwi, triq waħda'))}</h2></div><span>🌍</span></div><div class="language-twin-config-grid"><label><span>${esc(lang3('Lingua d’esame','Exam language','Lingwa tal-eżami'))}</span><select id="languageTwinExam"><option value="en">🇬🇧 English — Malta</option></select></label><label><span>${esc(lang3('Lingua di supporto','Support language','Lingwa ta’ appoġġ'))}</span><select id="languageTwinSupport">${Object.values(window.MDM_LANGUAGE_PACKS||{}).filter(p=>p.active).map(p=>`<option value="${esc(p.code)}" ${p.code===languageTwin.supportLanguage?'selected':''}>${esc((p.flag||'')+' '+(p.nativeName||p.name))}</option>`).join('')}</select></label></div><div class="language-twin-mode-grid">${[['exam','🇬🇧',lang3('Solo esame','Exam only','Eżami biss')],['support','🌍',lang3('Solo supporto','Support only','Appoġġ biss')],['bilingual','↔',lang3('Bilingue','Bilingual','Bilingwi')],['adaptive','🧬',lang3('Adattivo Twin','Twin adaptive','Adattiv Twin')]].map(([id,icon,label])=>`<button data-language-twin-mode="${id}" class="${languageTwin.displayMode===id?'active':''}"><span>${icon}</span><strong>${esc(label)}</strong><small>${esc(id==='adaptive'?lang3('Mostra l’aiuto solo dove serve.','Shows help only where needed.','Juri l-għajnuna biss fejn hemm bżonn.'):id==='bilingual'?lang3('English + lingua personale.','English + personal language.','English + lingwa personali.'):languageTwinModeLabel(id))}</small></button>`).join('')}</div></section>
 <section class="language-twin-diagnosis ${profile.score===null?'observing':''}"><div><small>${esc(lang3('LANGUAGE DIAGNOSIS','LANGUAGE DIAGNOSIS','DIJANJOSI TAL-LINGWA'))}</small><h2>${esc(profile.score===null?lang3('Scopri se l’errore è lingua o regola','Find out whether the problem is language or rule knowledge','Skopri jekk il-problema hijiex il-lingwa jew ir-regola'):lang3('Indipendenza dall’inglese d’esame','Exam-English independence','Indipendenza mill-Ingliż tal-eżami'))}</h2><p>${esc(profile.score===null?lang3('La stessa regola viene verificata prima nella lingua di supporto e poi in English.','The same rule is checked first in the support language and then in English.','L-istess regola tiġi ċċekkjata l-ewwel bil-lingwa ta’ appoġġ u mbagħad bl-Ingliż.'):lang3(`${profile.mastered}/${profile.total} regole padroneggiate · ${profile.languageGaps} gap linguistici · ${profile.knowledgeGaps} gap di conoscenza`,`${profile.mastered}/${profile.total} rules mastered · ${profile.languageGaps} language gaps · ${profile.knowledgeGaps} knowledge gaps`,`${profile.mastered}/${profile.total} regoli mhaddma · ${profile.languageGaps} nuqqasijiet lingwistiċi · ${profile.knowledgeGaps} nuqqasijiet ta’ għarfien`))}</p></div><b>${profile.score===null?'—':profile.score+'%'}</b><button class="btn" id="startLanguageTwinDiagnostic">${esc(lang3(last?'Ripeti diagnosi (5)':'Avvia diagnosi (5)','Run diagnosis (5)','Ibda d-dijanjosi (5)'))} →</button></section>
 ${last?`<section class="card language-twin-last"><div class="language-twin-section-head"><div><small>${esc(lang3('ULTIMA DIAGNOSI','LATEST DIAGNOSIS','L-AĦĦAR DIJANJOSI'))}</small><h2>${esc(formatExamDate(last.date))}</h2></div><span>🔬</span></div><div class="language-twin-score-grid"><article><b>${last.supportPct}%</b><span>${esc(support.nativeName||support.name)}</span></article><article><b>${last.examPct}%</b><span>${esc(lang3('Inglese d’esame','Exam English','Ingliż tal-eżami'))}</span></article><article><b>${last.languageGapIds.length}</b><span>${esc(lang3('Difficoltà linguistiche','Language gaps','Nuqqas lingwistiku'))}</span></article><article><b>${last.knowledgeGapIds.length}</b><span>${esc(lang3('Lacune di conoscenza','Knowledge gaps','Nuqqas ta’ għarfien'))}</span></article></div><button class="btn secondary" data-go="languagetwinresult" data-id="${esc(last.id)}">${esc(t('viewDetails'))} →</button></section>`:''}
 <section class="card language-twin-vocabulary"><div class="language-twin-section-head"><div><small>PERSONAL DRIVING ENGLISH</small><h2>${esc(lang3('Il tuo inglese di guida personale','Your personal Driving English','L-Ingliż tas-sewqan personali tiegħek'))}</h2><p>${esc(lang3('Il Twin conserva solo i termini comparsi in una vera difficoltà linguistica e riduce l’aiuto quando li recuperi.','The Twin keeps only terms seen in a real language gap and fades support as you recover them.','It-Twin iżomm biss termini li dehru f’diffikultà lingwistika vera u jnaqqas l-għajnuna hekk kif tirkuprahom.'))}</p></div><span>🔤</span></div>${difficult.length?`<div class="language-twin-term-list personal">${difficult.map(row=>{const translation=languageTwinTermTranslation(row.term);const state=languageTwinTermState(row.term),label=state==='mastered'?lang3('ACQUISITA','MASTERED','MHADDMA'):state==='learning'?lang3('IN APPRENDIMENTO','LEARNING','QED TITGĦALLEM'):lang3('DA CONSOLIDARE','NEEDS SUPPORT','TEĦTIEĠ APPOĠĠ');return `<article class="${state}"><div><strong>${esc(row.term)}</strong><span>${esc(translation||lang3('Traduzione disponibile con il relativo Language Pack','Translation available with the matching Language Pack','Traduzzjoni disponibbli mal-Language Pack korrispondenti'))}</span></div><em>${esc(label)}</em><b>${Number(row.gapCount||0)}×</b></article>`}).join('')}</div><div class="language-twin-fade-legend"><span>1 · ${esc(lang3('Traduzione completa','Full translation','Traduzzjoni sħiħa'))}</span><b>→</b><span>2 · ${esc(lang3('Solo parole difficili','Difficult words only','Kliem diffiċli biss'))}</span><b>→</b><span>3 · ${esc(lang3('Inglese puro','English only','Ingliż biss'))}</span></div>`:`<div class="language-twin-empty">${esc(lang3('Nessun termine critico ancora rilevato. Il Twin creerà questa lista soltanto dai tuoi errori linguistici reali.','No critical terms detected yet. The Twin will build this list only from your real language errors.','Għadu ma nstab l-ebda terminu kritiku. It-Twin jibni din il-lista biss mill-iżbalji lingwistiċi reali tiegħek.'))}</div>`}</section>
 <section class="card language-twin-future"><div><span>🧩</span><div><small>${esc(lang3('ARCHITETTURA UNIVERSALE','UNIVERSAL ARCHITECTURE','ARKITETTURA UNIVERSALI'))}</small><h3>${esc(lang3('Language Pack estendibili','Extensible Language Packs','Language Packs estensibbli'))}</h3><p>${esc(lang3('Italiano, Inglese e Maltese sono attivi ora. Nuove lingue di supporto potranno essere aggiunte come pack senza riscrivere la diagnosi.','Italian, English and Maltese are active now. New support languages can be added as packs without rewriting the diagnosis engine.','It-Taljan, l-Ingliż u l-Malti huma attivi issa. Lingwi ta’ appoġġ ġodda jistgħu jiżdiedu bħala packs mingħajr ma terġa’ tinkiteb id-dijanjosi.'))}</p></div></div></section>`;
}
function languageTwinQuizViewHtml(){return `<div class="card language-twin-quiz"><div class="language-twin-quiz-head"><span id="languageTwinPhase" class="mode-label"></span><b id="languageTwinCounter"></b></div><div class="progress"><span id="languageTwinProgress"></span></div><p class="muted">${esc(lang3('Prima dimostra che conosci la regola nella lingua di supporto. Poi il Twin misura la comprensione dell’inglese d’esame.','First prove you know the rule in your support language. Then the Twin measures exam-English comprehension.','L-ewwel uri li taf ir-regola bil-lingwa ta’ appoġġ. Imbagħad it-Twin ikejjel il-fehim tal-Ingliż tal-eżami.'))}</p><div id="languageTwinQuestion" class="question"></div><div id="languageTwinInstruction" class="quiz-instruction"></div><div id="languageTwinOptions"></div><div class="actions quiz-footer"><button class="btn secondary" id="languageTwinExit">${esc(t('exit'))}</button><button class="btn" id="languageTwinConfirm">${esc(t('confirm'))}</button></div></div>`}
function languageTwinResultViewHtml(){
 const r=languageTwinResultById(route.data);if(!r)return `<div class="card"><h2>${esc(t('noResults'))}</h2><button class="btn" data-go="languagetwin">${esc(t('back'))}</button></div>`;
 const support=languageTwinPack(r.supportLanguage),terms=Array.isArray(r.terms)?r.terms:[];
 return `<div class="section-title"><div><h2>🌐 ${esc(lang3('Risultato Twin linguistico','Language Twin result','Riżultat Language Twin'))}</h2><p>${esc(formatExamDate(r.date))}</p></div><span class="badge official">${esc(r.id)}</span></div><section class="language-twin-result-hero"><small>${esc(lang3('DIAGNOSI DIFFERENZIALE DIDATTICA','LEARNING DIFFERENTIAL DIAGNOSIS','DIJANJOSI DIFFERENZJALI TAT-TAGĦLIM'))}</small><h1>${r.examPct}%</h1><p>${esc(lang3(`nel test attuale · ${r.total} concetti verificati`,`in this test · ${r.total} concepts checked`,`f’dan it-test · ${r.total} kunċetti vverifikati`))}</p></section><div class="language-twin-result-grid"><article><span>${support.flag}</span><b>${r.supportCorrect}/${r.total}</b><small>${esc(support.nativeName||support.name)}</small></article><article><span>🇬🇧</span><b>${r.examCorrect}/${r.total}</b><small>${esc(lang3('Inglese d’esame','Exam English','Ingliż tal-eżami'))}</small></article></div><section class="card language-twin-diff"><h2>${esc(lang3('Cosa significa il risultato','What the result means','Xi jfisser ir-riżultat'))}</h2><article class="language-gap"><b>${r.languageGapIds.length}</b><div><strong>${esc(lang3('DIFFICOLTÀ LINGUISTICA','LANGUAGE GAP','NUQQAS LINGWISTIKU'))}</strong><p>${esc(lang3('Conosci la regola nella tua lingua, ma la formulazione inglese ti blocca.','You know the rule in your language, but the English wording blocks you.','Taf ir-regola bil-lingwa tiegħek, iżda l-formulazzjoni bl-Ingliż twaqqfek.'))}</p><small>${esc(r.languageGapIds.join(' · ')||'—')}</small></div></article><article class="knowledge-gap"><b>${r.knowledgeGapIds.length}</b><div><strong>${esc(lang3('LACUNA DI CONOSCENZA','KNOWLEDGE GAP','NUQQAS TA’ GĦARFIEN'))}</strong><p>${esc(lang3('La regola non è ancora stabile nemmeno nella lingua di supporto.','The rule is not stable yet even in the support language.','Ir-regola għadha mhix stabbli lanqas bil-lingwa ta’ appoġġ.'))}</p><small>${esc(r.knowledgeGapIds.join(' · ')||'—')}</small></div></article><article class="mastered"><b>${r.masteredIds.length}</b><div><strong>${esc(lang3('PADRONEGGIATE','MASTERED','MHADDMA'))}</strong><p>${esc(lang3('Regola compresa sia nella lingua personale sia in inglese.','Rule understood both in the personal language and in English.','Ir-regola mifhuma kemm bil-lingwa personali kif ukoll bl-Ingliż.'))}</p></div></article></section>${terms.length?`<section class="card language-twin-found-terms"><h2>${esc(lang3('Inglese di guida','Driving English','Ingliż tas-sewqan'))}</h2>${terms.map(x=>`<div><strong>${esc(x.term)}</strong><span>${esc(x.it||'')}</span><small>${esc(x.tag||'')}</small></div>`).join('')}</section>`:''}<div class="actions"><button class="btn" data-go="languagetwin">${esc(lang3('Torna al Twin linguistico','Back to Language Twin','Lura għal Language Twin'))}</button>${r.languageGapIds.length?`<button class="btn secondary" id="languageTwinTrainGaps">${esc(lang3('Allena le difficoltà linguistiche','Train language gaps','Ħarreġ in-nuqqasijiet lingwistiċi'))}</button>`:''}</div>`;
}
function bindLanguageTwin(){
 const support=$('#languageTwinSupport');if(support)support.onchange=()=>{const code=support.value;if(languageTwinPack(code)?.active){languageTwin.supportLanguage=code;if(languageTwin.supportLanguage===languageTwin.examLanguage&&['support','bilingual','adaptive'].includes(languageTwin.displayMode))languageTwin.displayMode='exam';languageTwinSave();render()}};
 screen.querySelectorAll('[data-language-twin-mode]').forEach(button=>button.onclick=()=>{const mode=button.dataset.languageTwinMode;if(['exam','support','bilingual','adaptive'].includes(mode)){if(mode!=='exam'&&languageTwin.supportLanguage===languageTwin.examLanguage)return toast(lang3('Scegli prima una lingua di supporto diversa da English.','Choose a support language different from English first.','Agħżel l-ewwel lingwa ta’ appoġġ differenti mill-Ingliż.'));languageTwin.displayMode=mode;languageTwinSave();render()}});
 const start=$('#startLanguageTwinDiagnostic');if(start)start.onclick=()=>startLanguageTwinDiagnostic(5);
}
function bindLanguageTwinResult(){
 const r=languageTwinResultById(route.data),train=$('#languageTwinTrainGaps');if(train&&r)train.onclick=()=>{const pool=r.languageGapIds.map(id=>Q.find(q=>q.id===id)).filter(Boolean);if(!pool.length)return toast(t('noResults'));startQuiz(pool,'guided')};
}


/* ================================================================
   Build 40.14.1 — INSTRUCTOR EVIDENCE PRECISION
   Each practical mission now records the three observable behaviours
   separately. The overall road-transfer result is calculated from
   those three instructor observations; no single global tap can hide
   which behaviour was strong, assisted or still unsafe.
   ================================================================ */
const REAL_ROAD_SELECTED_PATTERN_KEY='mdm-v1-real-road-selected-pattern';
const REAL_ROAD_DEFAULT={active:null,history:[]};
let realRoadTwin=Object.assign({},REAL_ROAD_DEFAULT,load(REAL_ROAD_TWIN_KEY,{}));
realRoadTwin.history=Array.isArray(realRoadTwin.history)?realRoadTwin.history:[];
realRoadTwin.active=realRoadTwin.active&&typeof realRoadTwin.active==='object'?realRoadTwin.active:null;
function realRoadSave(){save(REAL_ROAD_TWIN_KEY,realRoadTwin)}
function realRoadEvidenceRows(){return Array.isArray(progress.realRoadEvidence)?progress.realRoadEvidence:[]}
function realRoadEvidenceCount(){return realRoadEvidenceRows().reduce((n,row)=>n+(Array.isArray(row?.objectiveEvaluations)&&row.objectiveEvaluations.length?row.objectiveEvaluations.length:1),0)}
function realRoadSelectedPatternId(){
 const raw=load(REAL_ROAD_SELECTED_PATTERN_KEY,'');
 return AI_PATTERN_GROUPS.some(group=>group.id===String(raw||''))?String(raw):'';
}
function realRoadSelectPattern(id){
 const patternId=String(id||'');
 if(!AI_PATTERN_GROUPS.some(group=>group.id===patternId))return false;
 save(REAL_ROAD_SELECTED_PATTERN_KEY,patternId);
 return true;
}
function realRoadPattern(){
 const ranked=Array.isArray(drivingTwinProfile()?.analysis?.ranked)?drivingTwinProfile().analysis.ranked:[];
 const selectedId=realRoadSelectedPatternId();
 if(selectedId){
  const selected=ranked.find(item=>String(item?.id||'')===selectedId)||aiPatternGroupAnalysis(AI_PATTERN_GROUPS.find(g=>g.id===selectedId));
  if(selected)return selected;
 }
 return ranked.find(item=>AI_PATTERN_GROUPS.some(group=>group.id===item?.id))||AI_PATTERN_GROUPS.map(aiPatternGroupAnalysis).filter(item=>item.attempts||item.wrong).sort((a,b)=>b.score-a.score)[0]||aiPatternGroupAnalysis(AI_PATTERN_GROUPS.find(g=>g.id==='observation'));
}
function realRoadTemplate(id){
 const map={
  priority:{title:['Precedenze e incroci sulla strada reale','Priorities and junctions on the real road','Prijoritajiet u salib it-toroq fit-triq reali'],objectives:[['Avvicinati a un incrocio leggendo priorità, segnali e traffico prima di decidere.','Approach a junction by reading priority, signs and traffic before deciding.','Meta tersaq lejn salib it-toroq, osserva l-prijorità, is-sinjali u t-traffiku qabel tiddeċiedi.'],['Dichiara ad alta voce chi ha la precedenza prima di impegnare l’incrocio.','State who has priority before entering the junction.','Għid min għandu l-prijorità qabel tidħol fis-salib it-toroq.'],['Posizionati e rallenta senza costringere altri utenti a reagire.','Position and slow down without forcing other road users to react.','Poġġi ruħek u naqqas il-veloċità mingħajr ma ġġiegħel lil oħrajn jirreaġixxu.']]},
  signs:{title:['Segnali: riconosci → decidi → agisci','Signs: recognise → decide → act','Sinjali: agħraf → iddeċiedi → aġixxi'],objectives:[['Individua il segnale abbastanza presto da poter reagire con calma.','Identify the sign early enough to react calmly.','Agħraf is-sinjal kmieni biżżejjed biex tirreaġixxi bil-kalma.'],['Spiega in una frase cosa cambia nella tua guida.','Explain in one sentence what changes in your driving.','Spjega f’sentenza waħda x’jinbidel fis-sewqan tiegħek.'],['Esegui l’azione corretta senza correzione dell’istruttore.','Carry out the correct action without instructor correction.','Agħmel l-azzjoni t-tajba mingħajr korrezzjoni mill-istruttur.']]},
  vulnerable:{title:['Utenti vulnerabili: spazio, velocità, previsione','Vulnerable users: space, speed, anticipation','Utenti vulnerabbli: spazju, veloċità, antiċipazzjoni'],objectives:[['Riconosci pedoni, ciclisti o motociclisti prima che diventino un pericolo immediato.','Recognise pedestrians, cyclists or motorcyclists before they become an immediate hazard.','Agħraf persuni mexjin, ċiklisti jew sewwieqa ta’ muturi qabel ma jsiru periklu immedjat.'],['Riduci la velocità e crea spazio prima di arrivare accanto a loro.','Reduce speed and create space before reaching them.','Naqqas il-veloċità u oħloq spazju qabel tasal ħdejhom.'],['Aspetta se la situazione non consente margine sufficiente.','Wait if the situation does not provide enough safety margin.','Stenna jekk is-sitwazzjoni ma tagħtix marġni ta’ sigurtà biżżejjed.']]},
  procedures:{title:['Procedure e controlli prima di partire','Procedures and checks before setting off','Proċeduri u kontrolli qabel titlaq'],objectives:[['Esegui con l’istruttore un controllo documenti/veicolo collegato alla regola debole.','Carry out a document/vehicle check with the instructor linked to the weak rule.','Agħmel, flimkien mal-istruttur, kontroll tad-dokumenti u tal-vettura marbut mar-regola li għadek dgħajjef fiha.'],['Spiega cosa controlleresti prima di guidare e perché.','Explain what you would check before driving and why.','Spjega x’għandek tivverifika qabel issuq u għaliex.'],['Dimostra la procedura senza suggerimenti al secondo tentativo.','Demonstrate the procedure without prompts on the second attempt.','Uri l-proċedura mingħajr suġġerimenti fit-tieni tentattiv.']]},
  observation:{title:['Osservazione, specchi e decisione','Observation, mirrors and decision','Osservazzjoni, mirja u deċiżjoni'],objectives:[['Prima di ogni cambio di direzione verbalizza specchio → segnale → manovra.','Before each change of direction verbalise mirror → signal → manoeuvre.','Qabel kull bidla fid-direzzjoni għid mera → sinjal → manuvra.'],['Individua almeno un rischio che richiede adattamento di velocità o posizione.','Identify at least one hazard requiring speed or position adjustment.','Agħraf mill-inqas periklu wieħed li jeħtieġ tibdil fil-veloċità jew pożizzjoni.'],['Prendi la decisione senza intervento dell’istruttore quando è sicuro farlo.','Make the decision without instructor intervention when it is safe.','Ħu d-deċiżjoni mingħajr intervent tal-istruttur meta jkun sigur.']]},
  vehicle:{title:['Controllo del veicolo prima e durante la guida','Vehicle control before and during driving','Kontroll tal-vettura qabel u waqt is-sewqan'],objectives:[['Esegui un controllo mirato di pneumatici, luci o comandi legato al pattern.','Perform a targeted tyre, light or control check linked to the pattern.','Agħmel kontroll immirat tat-tajers, id-dwal jew il-kontrolli marbut mal-mudell ta’ żbalji.'],['Spiega quale rischio crea un controllo scorretto o trascurato.','Explain the risk created by an incorrect or missed check.','Spjega r-riskju maħluq minn kontroll ħażin jew nieqes.'],['Durante la guida dimostra un uso fluido e sicuro del comando collegato.','During driving demonstrate smooth and safe use of the related control.','Waqt is-sewqan uri użu bla xkiel u sigur tal-kontroll rilevanti.']]},
  risk:{title:['Hazard scan: vedi prima, decidi prima','Hazard scan: see earlier, decide earlier','Osservazzjoni tal-perikli: ara qabel, iddeċiedi qabel'],objectives:[['Ogni 10–15 secondi verbalizza il rischio principale che stai monitorando.','Every 10–15 seconds verbalise the main hazard you are monitoring.','Kull 10–15-il sekonda għid il-periklu ewlieni li qed tosserva.'],['Prima di reagire crea una pausa mentale: rischio → spazio → azione.','Before reacting use a mental pause: hazard → space → action.','Qabel tirreaġixxi agħmel waqfa mentali: periklu → spazju → azzjoni.'],['Evita risposte impulsive mantenendo velocità e distanza coerenti.','Avoid impulsive responses while keeping appropriate speed and distance.','Evita tweġibiet impulsivi billi żżomm veloċità u distanza xierqa.']]},
  eco:{title:['Eco-guida verificabile sulla strada','Verifiable eco-driving on the road','Sewqan ekonomiku verifikabbli fit-triq'],objectives:[['Anticipa il traffico per ridurre frenate e accelerazioni inutili.','Anticipate traffic to reduce unnecessary braking and acceleration.','Antiċipa t-traffiku biex tnaqqas l-ibbrejkjar u l-aċċellerazzjoni bla bżonn.'],['Mantieni velocità e marcia coerenti con la situazione.','Maintain speed and gear appropriate to the situation.','Żomm veloċità u ger xierqa għas-sitwazzjoni.'],['L’istruttore verifica una sequenza fluida senza correzioni.','The instructor verifies a smooth sequence without corrections.','L-istruttur jivverifika sekwenza bla xkiel mingħajr korrezzjonijiet.']]}
 };
 return map[id]||map.observation;
}
/* ================================================================
   Build 45.8.12 — ADAPTIVE MISSION ENGINE FOUNDATION
   Practical missions adapt to measured Twin / Copilot / road evidence.
   No competence result is inferred and the instructor remains in control.
   ================================================================ */
function adaptiveMissionLatestCopilot(patternId){
 const rows=typeof instructorCopilotRows==='function'?instructorCopilotRows():[];
 return [...rows].reverse().find(row=>String(row?.patternId||'')===String(patternId||''))||null;
}
function adaptiveMissionLatestRoad(patternId,relatedQuestionIds=[]){
 const rows=typeof realRoadEvidenceRows==='function'?realRoadEvidenceRows():[];
 const wanted=String(patternId||'');
 // Primary key: the canonical pattern id saved by Theory → Real Road.
 const exact=[...rows].reverse().find(row=>String(row?.patternId||'')===wanted);
 if(exact)return exact;
 // Compatibility bridge for evidence created by earlier builds: accept it only
 // when it shares actual canonical question IDs with the current pattern.
 // Never use the global road-transfer score as evidence for a specific mission.
 const ids=new Set((Array.isArray(relatedQuestionIds)?relatedQuestionIds:[]).map(String).filter(Boolean));
 if(!ids.size)return null;
 let best=null,bestOverlap=0;
 for(const row of [...rows].reverse()){
  const rowIds=(Array.isArray(row?.relatedQuestionIds)?row.relatedQuestionIds:[]).map(String);
  const overlap=rowIds.reduce((n,id)=>n+(ids.has(id)?1:0),0);
  if(overlap>bestOverlap){best=row;bestOverlap=overlap;}
 }
 return bestOverlap>0?best:null;
}
function adaptiveMissionContext(pattern){
 const patternId=String(pattern?.group?.id||pattern?.id||'observation');
 const copilot=adaptiveMissionLatestCopilot(patternId);
 const road=adaptiveMissionLatestRoad(patternId,(pattern?.questions||[]).map(q=>q?.id).filter(Boolean));
 const predictive=typeof drivingTwinPredictiveInterventionData==='function'?drivingTwinPredictiveInterventionData():{signals:[]};
 const signals=Array.isArray(predictive?.signals)?predictive.signals:[];
 const has=id=>signals.some(x=>x?.id===id);
 const roadScore=drivingTwinMaybeNumber(road?.score);
 let code='baseline';
 if(String(copilot?.outcome||'')==='repeat')code='repeat';
 else if(String(copilot?.outcome||'')==='assisted')code='assisted';
 else if(has('deterioration'))code='deterioration';
 else if(has('memory_due'))code='memory';
 else if(road&&(String(road?.status||'')==='needs-work'||(roadScore!==null&&roadScore<50)))code='road_gap';
 else if(has('recurrence'))code='recurrence';
 else if(String(copilot?.outcome||'')==='independent')code='consolidate';
 const source=[];
 if(copilot)source.push(lang3('Nota istruttore','Instructor note','Nota tal-istruttur'));
 if(road)source.push(lang3('Evidenza su strada','Road evidence','Evidenza mis-sewqan'));
 if(signals.length)source.push(lang3('Segnali del Twin','Twin signals','Sinjali tat-Twin'));
 return {code,copilot,road,signals,source};
}
function adaptiveMissionFocus(code){
 const map={
  repeat:{label:lang3('Ripetizione guidata','Guided repetition','Ripetizzjoni ggwidata'),objective:lang3('Ripeti il comportamento critico due volte: la seconda volta senza suggerimenti, solo se la situazione è sicura.','Repeat the critical behaviour twice: the second time without prompts, only when the situation is safe.','Agħmel l-imġiba kritika darbtejn: fit-tieni darba mingħajr ebda tfakkira, u biss jekk is-sitwazzjoni tkun sigura.')},
  assisted:{label:lang3('Riduzione dell’assistenza','Reduce assistance','Tnaqqis gradwali fl-għajnuna'),objective:lang3('Esegui lo stesso comportamento una volta con al massimo un richiamo e poi una seconda volta in autonomia, se sicuro.','Perform the same behaviour once with no more than one prompt, then a second time independently if safe.','Agħmel l-istess imġiba darba b’tfakkira waħda biss; imbagħad erġa’ agħmilha waħdek jekk ikun sigur.')},
  deterioration:{label:lang3('Rallenta la decisione','Slow the decision','Naqqas ir-ritmu tad-deċiżjoni'),objective:lang3('Prima della manovra verbalizza rischio → spazio → azione e agisci solo dopo aver completato questa sequenza.','Before the manoeuvre verbalise hazard → space → action and act only after completing that sequence.','Qabel il-manuvra, għid b’leħen għoli: periklu → spazju → azzjoni, u aġixxi biss wara li tlesti din is-sekwenza.')},
  memory:{label:lang3('Riconferma memoria + strada','Reconfirm memory + road','Ikkonferma l-memorja u l-applikazzjoni fit-triq'),objective:lang3('All’inizio e alla fine della lezione spiega la stessa regola e applicala in una situazione reale sicura.','At the start and end of the lesson explain the same rule and apply it in one safe real-road situation.','Fil-bidu u fit-tmiem tal-lezzjoni, spjega l-istess regola u applikaha f’sitwazzjoni reali sigura.')},
  road_gap:{label:lang3('Recupera l’obiettivo più debole','Recover the weakest objective','Saħħaħ mill-ġdid l-għan l-aktar dgħajjef'),objective:lang3('Ripeti prima il comportamento che nell’ultima prova su strada ha richiesto più aiuto, senza aumentare la difficoltà finché non è stabile.','Repeat first the behaviour that needed the most help in the latest road evidence; do not increase difficulty until it is stable.','L-ewwel erġa’ agħmel l-imġiba li fl-aħħar prova fit-triq kellha bżonn l-aktar għajnuna; iżżidx id-diffikultà sakemm tkun stabbli.')},
  recurrence:{label:lang3('Stesso rischio, due contesti','Same risk, two contexts','L-istess riskju, żewġ sitwazzjonijiet'),objective:lang3('Affronta lo stesso tipo di decisione in due contesti reali sicuri differenti per verificare che lo schema ricorrente non dipenda da una sola situazione.','Practise the same type of decision in two different safe real-road contexts to check the pattern is not tied to one situation.','Ipprattika l-istess tip ta’ deċiżjoni f’żewġ sitwazzjonijiet reali differenti u siguri biex tivverifika li l-problema ma tiddependix minn sitwazzjoni waħda biss.')},
  consolidate:{label:lang3('Consolidamento autonomo','Independent consolidation','Konsolidament indipendenti'),objective:lang3('Conferma lo stesso comportamento in un contesto sicuro diverso senza suggerimenti dell’istruttore.','Confirm the same behaviour in a different safe context without instructor prompts.','Ikkonferma l-istess imġiba f’kuntest sigur differenti mingħajr suġġerimenti tal-istruttur.')},
  baseline:{label:lang3('Missione basata sullo schema ricorrente','Pattern-based mission','Missjoni bbażata fuq ix-xejra ta’ żbalji'),objective:''}
 };
 return map[code]||map.baseline;
}
function adaptiveMissionExplanation(ctx){
 const rows=[];
 if(ctx?.copilot)rows.push(lang3(`Ultima nota istruttore: ${instructorCopilotOutcomeLabel(ctx.copilot.outcome)}`,`Latest instructor note: ${instructorCopilotOutcomeLabel(ctx.copilot.outcome)}`,`L-aħħar nota tal-istruttur: ${instructorCopilotOutcomeLabel(ctx.copilot.outcome)}`));
 if(ctx?.road){const score=drivingTwinMaybeNumber(ctx.road.score);rows.push(lang3(`Ultima prova su strada${score!==null?`: ${drivingTwinCount(score)}/100`:''}`,`Latest road evidence${score!==null?`: ${drivingTwinCount(score)}/100`:''}`,`L-aħħar prova fit-triq${score!==null?`: ${drivingTwinCount(score)}/100`:''}`));}
 if(Array.isArray(ctx?.signals)&&ctx.signals.length)rows.push(...ctx.signals.slice(0,2).map(x=>String(x.label||'')));
 return rows.filter(Boolean).slice(0,3);
}
function adaptiveMissionEvidence(ctx){
 return {copilotOutcome:String(ctx?.copilot?.outcome||''),roadScore:drivingTwinMaybeNumber(ctx?.road?.score),roadStatus:String(ctx?.road?.status||''),signalIds:(Array.isArray(ctx?.signals)?ctx.signals:[]).slice(0,2).map(x=>String(x?.id||'')).filter(Boolean)};
}
function adaptiveMissionReasonsFromEvidence(e){
 const rows=[],ev=e&&typeof e==='object'?e:{};
 if(ev.copilotOutcome)rows.push(lang3(`Ultima nota istruttore: ${instructorCopilotOutcomeLabel(ev.copilotOutcome)}`,`Latest instructor note: ${instructorCopilotOutcomeLabel(ev.copilotOutcome)}`,`L-aħħar nota tal-istruttur: ${instructorCopilotOutcomeLabel(ev.copilotOutcome)}`));
 const score=drivingTwinMaybeNumber(ev.roadScore);
 if(score!==null||ev.roadStatus)rows.push(lang3(`Ultima prova su strada${score!==null?`: ${drivingTwinCount(score)}/100`:''}`,`Latest road evidence${score!==null?`: ${drivingTwinCount(score)}/100`:''}`,`L-aħħar prova fit-triq${score!==null?`: ${drivingTwinCount(score)}/100`:''}`));
 const signalMap={deterioration:lang3('Peggioramento dopo l’ultima azione','Deterioration after the latest action','Il-prestazzjoni marret lura wara l-aħħar azzjoni'),memory_due:lang3('Verifica memoria arrivata a scadenza','Memory recheck is due','Wasal iż-żmien għall-verifika tal-memorja'),recurrence:lang3('Schema ricorrente ancora presente','Pattern still recurring','Ix-xejra ta’ żbalji għadha rikorrenti'),response:lang3('Controllo della risposta debole','Weak response control','Kontroll dgħajjef tar-rispons'),competence:lang3('Competenza ancora non chiusa','Competence evidence still incomplete','L-evidenza tal-kompetenza għadha mhux kompluta')};
 (Array.isArray(ev.signalIds)?ev.signalIds:[]).forEach(id=>{if(signalMap[id])rows.push(signalMap[id])});
 return rows.filter(Boolean).slice(0,3);
}
function realRoadMissionCandidate(){
 const pattern=realRoadPattern(),group=pattern?.group||AI_PATTERN_GROUPS.find(g=>g.id==='observation'),tpl=realRoadTemplate(group.id);
 const related=(pattern?.questions||[]).slice().sort((a,b)=>Number(progress.wrong?.[b.id]||0)-Number(progress.wrong?.[a.id]||0)).slice(0,5).map(q=>q.id);
 const adaptive=adaptiveMissionContext(pattern),focus=adaptiveMissionFocus(adaptive.code);
 const objectives=tpl.objectives.map(row=>lang3(...row));
 if(focus.objective)objectives[2]=focus.objective;
 return {patternId:group.id,patternLabel:aiPatternLocalizedLabel(group.id,aiRecoveryText(group.it,group.en)),causeId:String(pattern?.cause?.id||''),cause:aiPatternCauseLocalized(pattern?.cause?.id,pattern?.cause?.label||lang3('Schema ricorrente da verificare sulla strada','Pattern to verify on the road','Xejra li trid tiġi vverifikata fit-triq')),title:lang3(...tpl.title),objectives,baselineErrorRate:drivingTwinPct(pattern?.errorRate)||0,relatedQuestionIds:related,adaptiveCode:adaptive.code,adaptiveLabel:focus.label,adaptiveEvidence:adaptiveMissionEvidence(adaptive)};
}
function realRoadDisplayMission(m){
 if(!m)return m;
 const group=AI_PATTERN_GROUPS.find(g=>g.id===String(m.patternId||''))||AI_PATTERN_GROUPS.find(g=>g.id==='observation');
 const tpl=realRoadTemplate(group.id),focus=adaptiveMissionFocus(String(m.adaptiveCode||'baseline'));
 const objectives=tpl.objectives.map(row=>lang3(...row));
 if(focus.objective)objectives[2]=focus.objective;
 const live=aiPatternGroupAnalysis(group),causeId=String(m.causeId||live?.cause?.id||'');
 return {...m,title:lang3(...tpl.title),patternLabel:aiPatternLocalizedLabel(group.id,aiRecoveryText(group.it,group.en)),causeId,cause:aiPatternCauseLocalized(causeId,live?.cause?.label||m.cause||''),objectives,adaptiveLabel:focus.label};
}
function adaptiveMissionCardHtml(m){
 const code=String(m?.adaptiveCode||'baseline'),focus=adaptiveMissionFocus(code),reasons=m?.adaptiveEvidence?adaptiveMissionReasonsFromEvidence(m.adaptiveEvidence):[];
 const reasonHtml=reasons.length?reasons.map((x,i)=>`<div class="adaptive-mission-reason"><b>${i+1}</b><span>${esc(x)}</span></div>`).join(''):`<div class="adaptive-mission-reason clear"><b>✓</b><span>${esc(lang3('Nessun segnale aggiuntivo: usa lo schema ricorrente principale come base.','No additional signal: use the primary pattern as the baseline.','M’hemm l-ebda sinjal ieħor: uża l-mudell ewlieni bħala bażi.'))}</span></div>`;
 return `<section class="adaptive-mission-card"><div class="adaptive-mission-head"><div><small>${esc(lang3('ADAPTIVE MISSION ENGINE','ADAPTIVE MISSION ENGINE','ADAPTIVE MISSION ENGINE'))}</small><h3>${esc(focus.label)}</h3></div><span>🎯</span></div><p>${esc(lang3('La missione cambia usando evidenze reali del Twin, dell’istruttore e della strada. Nessun esito di competenza viene dedotto automaticamente.','The mission changes using real Twin, instructor and road evidence. No competence outcome is inferred automatically.','Il-missjoni tinbidel billi tuża evidenza reali tat-Twin, tal-istruttur u tat-triq. L-ebda riżultat ta’ kompetenza ma jiġi dedott awtomatikament.'))}</p><div class="adaptive-mission-reasons">${reasonHtml}</div></section>`;
}
function realRoadObjectiveRows(m){
 // Always derive objective copy from the canonical multilingual mission template.
 // Stored missions keep only evaluation state; switching IT/EN/MT must never
 // replay the language that happened to be active when the mission was saved.
 const display=realRoadDisplayMission(m);
 const objectives=Array.isArray(display?.objectives)?display.objectives:[];
 const existing=Array.isArray(m?.objectiveEvaluations)?m.objectiveEvaluations:[];
 return objectives.map((objective,index)=>({index,objective,evaluation:String(existing[index]?.evaluation||''),score:drivingTwinMaybeNumber(existing[index]?.score)}));
}
function realRoadEvaluationScore(evaluation){return ({independent:100,help:65,repeat:25})[evaluation]??null}
function realRoadEvaluationLabel(evaluation){const map={independent:lang3('Indipendente','Independent','B’mod indipendenti'),help:lang3('Con aiuto','With help','Bl-għajnuna'),repeat:lang3('Da ripetere','Repeat','Erġa’ pprova')};return map[evaluation]||'—'}
function realRoadEvaluationIcon(evaluation){return evaluation==='independent'?'✅':evaluation==='help'?'🟠':evaluation==='repeat'?'🔴':'○'}
function realRoadCreate(){
 const c=realRoadMissionCandidate();
 realRoadTwin.active={id:`RR-${c.patternId}-${Date.now().toString(36).toUpperCase()}`,createdAt:new Date().toISOString(),startedAt:'',completedAt:'',status:'planned',evaluation:'',score:null,objectiveEvaluations:c.objectives.map(()=>({evaluation:'',score:null})),...c};
 realRoadSave();cloudAddQueueEvent('real-road-mission',{action:'create',missionId:realRoadTwin.active.id,patternId:c.patternId});render();
}
function realRoadStart(){
 if(!realRoadTwin.active)return realRoadCreate();
 const m=realRoadTwin.active;m.status='active';m.startedAt=new Date().toISOString();
 if(!Array.isArray(m.objectiveEvaluations)||m.objectiveEvaluations.length!==m.objectives.length)m.objectiveEvaluations=m.objectives.map(()=>({evaluation:'',score:null}));
 realRoadSave();render();
}
function realRoadSetObjectiveEvaluation(index,evaluation){
 const m=realRoadTwin.active;if(!m||m.status!=='active')return;
 const rows=realRoadObjectiveRows(m);if(!rows[index]||realRoadEvaluationScore(evaluation)===null)return;
 m.objectiveEvaluations=rows.map((row,i)=>i===index?{evaluation,score:realRoadEvaluationScore(evaluation)}:{evaluation:row.evaluation,score:row.score});
 realRoadSave();
 const group=screen.querySelector(`[data-real-road-objective-eval="${index}"]`);
 if(group){group.querySelectorAll('[data-real-road-choice]').forEach(btn=>btn.classList.toggle('selected',btn.dataset.realRoadChoice===evaluation));const state=group.querySelector('[data-real-road-objective-state]');if(state)state.textContent=`${realRoadEvaluationIcon(evaluation)} ${realRoadEvaluationLabel(evaluation)}`;}
 const complete=realRoadObjectiveRows(m).every(row=>row.evaluation&&realRoadEvaluationScore(row.evaluation)!==null),saveButton=$('#realRoadFinalize');if(saveButton)saveButton.disabled=!complete;
}
function realRoadFinalizeEvaluation(){
 const m=realRoadTwin.active;if(!m||m.status!=='active')return;
 const rows=realRoadObjectiveRows(m);if(rows.length!==3||rows.some(row=>!row.evaluation||realRoadEvaluationScore(row.evaluation)===null)){toast(lang3('Valuta tutti e 3 i comportamenti prima di registrare.','Rate all 3 behaviours before saving.','Ivvaluta t-3 imġibiet kollha qabel issalva.'));return}
 const objectiveEvaluations=rows.map(row=>({index:row.index+1,objective:row.objective,evaluation:row.evaluation,score:realRoadEvaluationScore(row.evaluation)}));
 const score=Math.round(objectiveEvaluations.reduce((sum,row)=>sum+row.score,0)/objectiveEvaluations.length);
 const hasRepeat=objectiveEvaluations.some(row=>row.evaluation==='repeat'),allIndependent=objectiveEvaluations.every(row=>row.evaluation==='independent');
 m.objectiveEvaluations=objectiveEvaluations.map(row=>({evaluation:row.evaluation,score:row.score}));m.score=score;m.evaluation=allIndependent?'independent':hasRepeat?'repeat':'help';m.completedAt=new Date().toISOString();m.status=allIndependent?'verified':hasRepeat?'needs-work':'partial';
 const evidence={id:m.id,patternId:m.patternId,patternLabel:m.patternLabel,createdAt:m.createdAt,completedAt:m.completedAt,status:m.status,evaluation:m.evaluation,score:m.score,baselineErrorRate:m.baselineErrorRate,relatedQuestionIds:m.relatedQuestionIds||[],objectiveEvaluations};
 progress.realRoadEvidence=realRoadEvidenceRows();progress.realRoadEvidence.push(evidence);progress.realRoadEvidence=progress.realRoadEvidence.slice(-100);save(STORAGE,progress);
 realRoadTwin.history.push(evidence);realRoadTwin.history=realRoadTwin.history.slice(-50);realRoadSave();cloudAddQueueEvent('real-road-mission',{action:'evaluate-precision',...evidence});render();
}
function realRoadArchive(){if(realRoadTwin.active){realRoadTwin.active=null;realRoadSave();render()}}
function realRoadStatusLabel(status){const map={planned:lang3('PRONTA PER LA LEZIONE','READY FOR THE LESSON','LESTA GĦAL-LEZZJONI'),active:lang3('IN LEZIONE','IN LESSON','FIL-LEZZJONI'),verified:lang3('TRASFERIMENTO CONFERMATO','TRANSFER CONFIRMED','TRASFERIMENT IKKONFERMAT'),partial:lang3('PARZIALMENTE INDIPENDENTE','PARTLY INDEPENDENT','PARZJALMENT INDIPENDENTI'),'needs-work':lang3('DA RIPETERE','REPEAT','ERĠA’ PPROVA')};return map[status]||map.planned}
function realRoadResultText(m){if(!m)return '';if(m.status==='verified')return lang3('Tutti e tre i comportamenti sono stati applicati sulla strada senza aiuto. Il Twin registra tre evidenze pratiche distinte.','All three behaviours were applied on the road without help. The Twin records three distinct practical evidence points.','It-tliet imġibiet ġew applikati fit-triq mingħajr għajnuna. It-Twin jirreġistra tliet evidenzi prattiċi distinti.');if(m.status==='partial')return lang3('La missione è stata completata, ma almeno un comportamento ha richiesto aiuto. Il Twin conserva il dettaglio di ciascun comportamento.','The mission was completed, but at least one behaviour required help. The Twin keeps the detail for each behaviour.','Il-missjoni tlestiet, iżda mill-inqas imġiba waħda kellha bżonn għajnuna. It-Twin iżomm id-dettall ta’ kull imġiba.');if(m.status==='needs-work')return lang3('Almeno un comportamento deve essere ripetuto. Il Twin mantiene quel punto pratico tra le priorità.','At least one behaviour needs to be repeated. The Twin keeps that practical point among the priorities.','Mill-inqas imġiba waħda trid terġa’ ssir. It-Twin iżomm dak il-punt prattiku fost il-prijoritajiet.');return ''}
function realRoadObjectiveEvaluatorHtml(m){
 const rows=realRoadObjectiveRows(m);
 return `<section class="card real-road-instructor-check"><small>${esc(lang3('VERIFICA ISTRUTTORE','INSTRUCTOR CHECK','KONTROLL TAL-ISTRUTTUR'))}</small><h2>${esc(lang3('Valuta i 3 comportamenti separatamente','Rate the 3 behaviours separately','Ivvaluta t-3 imġibiet separatament'))}</h2><p>${esc(lang3('Per ogni comportamento registra ciò che hai realmente osservato. Il risultato complessivo sarà calcolato automaticamente.','For each behaviour record what you actually observed. The overall result will be calculated automatically.','Għal kull imġiba rreġistra dak li osservajt verament. Ir-riżultat ġenerali jiġi kkalkulat awtomatikament.'))}</p><div class="real-road-precision-list">${rows.map(row=>`<article class="real-road-precision-item" data-real-road-objective-eval="${row.index}"><div class="real-road-precision-head"><b>0${row.index+1}</b><div><strong>${esc(row.objective)}</strong><span data-real-road-objective-state>${row.evaluation?`${realRoadEvaluationIcon(row.evaluation)} ${esc(realRoadEvaluationLabel(row.evaluation))}`:esc(lang3('Da valutare','To rate','Għad irid jiġi vvalutat'))}</span></div></div><div class="real-road-precision-options"><button type="button" class="${row.evaluation==='independent'?'selected':''}" data-real-road-choice="independent" data-real-road-index="${row.index}">✅ <strong>${esc(lang3('Indipendente','Independent','B’mod indipendenti'))}</strong></button><button type="button" class="${row.evaluation==='help'?'selected':''}" data-real-road-choice="help" data-real-road-index="${row.index}">🟠 <strong>${esc(lang3('Con aiuto','With help','Bl-għajnuna'))}</strong></button><button type="button" class="${row.evaluation==='repeat'?'selected':''}" data-real-road-choice="repeat" data-real-road-index="${row.index}">🔴 <strong>${esc(lang3('Da ripetere','Repeat','Erġa’ pprova'))}</strong></button></div></article>`).join('')}</div><button class="btn real-road-finalize" id="realRoadFinalize" ${rows.every(row=>row.evaluation)?'':'disabled'}>${esc(lang3('Registra verifica completa','Save complete assessment','Irreġistra l-valutazzjoni sħiħa'))} →</button></section>`;
}
