 const item={id:`RRE-${String(s.id||'SESSION')}-${event.type}-${Math.round(at)}`,type:String(event.type),at,source:String(event.source||'technical'),criterion:String(event.criterion||''),confidence:String(event.confidence||'medium'),context:String(event.context||''),sessionId:String(s.id||''),missionId:String(s.missionId||''),patternId:String(s.patternId||''),metrics:event.metrics&&typeof event.metrics==='object'?event.metrics:{},review:'pending',reviewedAt:''};
