   if(a>=REAL_ROAD_EVENT_THRESHOLDS.hardAccelerationMps2&&v1>=REAL_ROAD_EVENT_THRESHOLDS.minEventSpeedMps)realRoadEventPush(s,{type:'hard_acceleration',at:point.t,source:'GPS speed delta',criterion:`a ≥ ${REAL_ROAD_EVENT_THRESHOLDS.hardAccelerationMps2} m/s²`,confidence,context:'technical candidate from consecutive GPS speed samples',metrics:{accelerationMps2:realRoadTelemetryRound(a,2),fromKmh:realRoadTelemetryRound(v0*3.6,1),toKmh:realRoadTelemetryRound(v1*3.6,1),dtSeconds:realRoadTelemetryRound(dt,2),gpsAccuracyM:realRoadTelemetryRound(acc,0)}});
