   if(delta>=18&&lateral>=REAL_ROAD_EVENT_THRESHOLDS.corneringMps2)realRoadEventPush(s,{type:'aggressive_cornering',at:point.t,source:'GPS heading + speed',criterion:`lateral ≥ ${REAL_ROAD_EVENT_THRESHOLDS.corneringMps2} m/s²`,confidence:realRoadEventConfidence(prev,point),context:'technical candidate from heading change and observed speed',metrics:{headingDeltaDeg:realRoadTelemetryRound(delta,1),lateralMps2:realRoadTelemetryRound(lateral,2),speedKmh:realRoadTelemetryRound(v1*3.6,1),dtSeconds:realRoadTelemetryRound(dt,2),gpsAccuracyM:realRoadTelemetryRound(acc,0)}});
