 const strong=d.strongAxes.length?d.strongAxes.map(axis=>`<span>${axis.icon} ${esc(axis.label)} <b>${Math.round(axis.score)}%</b></span>`).join(''):`<span>${esc(lang3('Ancora nessuna area con evidenza forte sufficiente','No area has strong sufficient evidence yet','Għad m’hemm l-ebda qasam b’evidenza qawwija biżżejjed'))}</span>`;
