/* ================================================================
   Build 45.8.28.4 — PRODUCTION PERMISSION SCOPE
   Verifies the server authorization boundary before Operations/Fleet/Parent
   are connected to production sync. No automatic upload is introduced.
   - school_operations: ACTIVE school_admin only.
   - fleet_context: authenticated owner-only.
   - parent_report: authenticated owner-only.
   Cross-user Fleet/Parent access remains unavailable in this sub-step.
   ================================================================ */
const MDM_PRODUCTION_PERMISSION_KEY='mdm-production-permission-v458284';
const MDM_PRODUCTION_PERMISSION_DEFAULT={
 revision:'45.8.28.4',verified:false,checkedAt:'',lastMessage:'',
 role:'',membershipStatus:'',schoolId:'',
 schoolOperationsWrite:false,schoolOperationsRead:false,
 fleetContextOwnerOnly:false,parentReportOwnerOnly:false,
 schoolStudentEvidenceRead:false,crossUserFleet:false,crossUserParent:false
};
let mdmProductionPermissionState=Object.assign(
 {},
 MDM_PRODUCTION_PERMISSION_DEFAULT,
 load(MDM_PRODUCTION_PERMISSION_KEY,{})
);
function mdmProductionPermissionSave(){
 save(MDM_PRODUCTION_PERMISSION_KEY,mdmProductionPermissionState);
}
function mdmProductionPermissionDate(value){
 if(!value)return lang3('Mai','Never','Qatt');
 try{
  return new Date(value).toLocaleString(
   settings.lang==='it'?'it-IT':settings.lang==='mt'?'mt-MT':'en-GB',
   {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}
  );
 }catch{return '—'}
}
async function mdmProductionPermissionProbe({silent=false}={}){
 const auth=mdmAuthSummary();
 if(!auth.authenticated){
  if(!silent)toast(lang3(
   'Accedi prima con Supabase Auth.',
   'Sign in with Supabase Auth first.',
   'L-ewwel idħol b’Supabase Auth.'
  ));
  return false;
 }
 if(!(await mdmEnsureFreshAuthForData()))return false;
 let result=await mdmDataRpc('mdm_production_permission_status',{});
 if(result.status===401&&mdmAuthSession.refreshToken&&await mdmAuthRefreshSession()){
  result=await mdmDataRpc('mdm_production_permission_status',{});
 }
 const data=mdmAuthParse(result.body)||{};
 const ok=result.status>=200&&result.status<300&&data.ok!==false&&String(data.permission_revision||'')==='45.8.28.4';
 mdmProductionPermissionState=Object.assign({},mdmProductionPermissionState,{
  revision:String(data.permission_revision||'45.8.28.4'),
  verified:ok,
  checkedAt:new Date().toISOString(),
  lastMessage:ok?'Production permission scope 45.8.28.4 verified':(mdmDataErrorMessage(result)||String(data.error||'permission_scope_not_ready')),
  role:String(data.membership_role||''),
  membershipStatus:String(data.membership_status||''),
  schoolId:String(data.school_id||''),
  schoolOperationsWrite:Boolean(data.school_operations_write),
  schoolOperationsRead:Boolean(data.school_operations_read),
  fleetContextOwnerOnly:Boolean(data.fleet_context_owner_only),
  parentReportOwnerOnly:Boolean(data.parent_report_owner_only),
  schoolStudentEvidenceRead:Boolean(data.school_student_evidence_read),
  crossUserFleet:Boolean(data.cross_user_fleet_context),
  crossUserParent:Boolean(data.cross_user_parent_report)
 });
 mdmProductionPermissionSave();
 render();
 if(!silent)toast(ok?lang3(
  'Permessi Production 45.8.28.4 verificati.',
  'Production permissions 45.8.28.4 verified.',
  'Il-permessi Production 45.8.28.4 ġew ivverifikati.'
 ):lang3(
  'Permessi Production non verificati: ',
  'Production permissions not verified: ',
  'Il-permessi Production ma ġewx ivverifikati: '
 )+mdmProductionPermissionState.lastMessage);
 return ok;
}
