 road.slice(-25).forEach((item,index)=>{const id=String(item?.id||`road-${index}`);rows.push({entityType:'road_evidence',localId:id,payload:mdmProductionSyncCanonicalRoad(item),clientUpdatedAt:String(item?.completedAt||item?.createdAt||new Date().toISOString())})});
