/* ================================================================
   Build 45.8.23 — PARENT / SPONSOR PORTAL FOUNDATION
   Read-only family/sponsor report built only from evidence that already
   exists in the learner profile. No external account or automatic sharing
   is simulated. Sharing happens only after an explicit user action.
   ================================================================ */
const PARENT_SPONSOR_BUILD='45.8.23';
function parentSponsorPortalData(){
 let passport=null,os=null,debrief=null,ready=null,st=null;
 try{passport=typeof evidencePassportData==='function'?evidencePassportData():null}catch{}
 try{os=typeof studentOperatingSystemData==='function'?studentOperatingSystemData():null}catch{}
 try{debrief=typeof aiLessonDebriefData==='function'?aiLessonDebriefData():null}catch{}
 try{ready=typeof readinessStats==='function'?readinessStats():null}catch{}
 try{st=typeof stats==='function'?stats():null}catch{}
 const student=[userProfile?.firstName,userProfile?.lastName].map(x=>String(x||'').trim()).filter(Boolean).join(' ')||lang3('Studente MDM','MDM learner','Student MDM');
 const axes=Array.isArray(passport?.axes)?passport.axes:[];
 const strongest=axes.filter(a=>a?.score!==null&&Number.isFinite(Number(a.score))).slice().sort((a,b)=>Number(b.score)-Number(a.score))[0]||null;
 const needs=Array.isArray(passport?.blockers)&&passport.blockers.length?passport.blockers[0]:null;
 const primary=Array.isArray(os?.steps)&&os.steps.length?os.steps[0]:null;
 const road=debrief?.current||null;
 const roadScore=debrief&&debrief.score!==null&&Number.isFinite(Number(debrief.score))?Math.round(Number(debrief.score)):null;
 const roadStatus=road?realRoadStatusLabel(String(road.status||'')):'';
 const evidenceCoverage=Number.isFinite(Number(passport?.evidenceCoverage))?Math.round(Number(passport.evidenceCoverage)):0;
 const observedPerformance=Number.isFinite(Number(passport?.performance))?Math.round(Number(passport.performance)):0;
 const readiness=Number.isFinite(Number(ready?.score))?Math.round(Number(ready.score)):0;
 const seen=drivingTwinCount(st?.seen);
 return {student,passport,os,debrief,ready,st,strongest,needs,primary,road,roadScore,roadStatus,evidenceCoverage,observedPerformance,readiness,seen};
}
function parentSponsorPortalStatusText(d){
 if(d.passport?.hardReady)return lang3('Evidenze complete secondo i gate MDM','Evidence complete under MDM gates','Evidenza kompluta skont il-gates MDM');
 if(d.evidenceCoverage>=67)return lang3('Percorso avanzato, evidenze ancora da completare','Advanced path, evidence still to complete','Mixja avvanzata, evidenza għadha trid titlesta');
 if(d.evidenceCoverage>=34)return lang3('Percorso in consolidamento','Path being consolidated','Mixja qed tissaħħaħ');
 return lang3('Evidenze ancora in costruzione','Evidence still building','Evidenza għadha qed tinbena');
}
function parentSponsorPortalNextText(d){
 if(d.primary)return {icon:d.primary.icon||'➡️',title:String(d.primary.title||''),detail:String(d.primary.detail||''),route:String(d.primary.route||'home')};
 if(d.needs)return {icon:'🧩',title:String(d.needs.label||''),detail:String(d.needs.detail||''),route:'evidencepassport'};
 return {icon:'➡️',title:lang3('Continua il percorso MDM','Continue the MDM path','Kompli l-mixja MDM'),detail:lang3('Il prossimo passo viene calcolato dai dati già registrati.','The next step is calculated from already recorded data.','Il-pass li jmiss jiġi kkalkulat mid-data diġà rreġistrata.'),route:'studentos'};
}
function parentSponsorPortalReportText(){
 const d=parentSponsorPortalData(),next=parentSponsorPortalNextText(d),p=d.passport||{};
 const lines=[
  'MDM — '+lang3('REPORT FAMIGLIA / SPONSOR','FAMILY / SPONSOR REPORT','RAPPORT TAL-FAMILJA / SPONSOR'),
  d.student,
  `${lang3('Stato','Status','Status')}: ${parentSponsorPortalStatusText(d)}`,
  `${lang3('Copertura evidenze','Evidence coverage','Kopertura tal-evidenza')}: ${d.evidenceCoverage}% (${drivingTwinCount(p.sufficient)}/${drivingTwinCount(p.totalAxes)})`,
  `${lang3('Prestazione osservata','Observed performance','Prestazzjoni osservata')}: ${d.observedPerformance}%`,
  `${lang3('Readiness didattica','Learning readiness','Tħejjija għat-tagħlim')}: ${d.readiness}%`,
  `${lang3('Domande viste','Questions seen','Mistoqsijiet dehru')}: ${d.seen}/${Q.length}`,
  ''
 ];
 if(d.strongest)lines.push(`${lang3('Punto più forte osservato','Strongest observed area','L-aktar qasam b’saħħtu osservat')}: ${d.strongest.label} · ${Math.round(Number(d.strongest.score))}%`);
 if(d.needs)lines.push(`${lang3('Evidenza da completare','Evidence to complete','Evidenza li trid titlesta')}: ${d.needs.label} · ${d.needs.detail}`);
 if(d.road)lines.push(`${lang3('Ultima verifica pratica','Latest practical check','L-aħħar kontroll prattiku')}: ${d.roadStatus}${d.roadScore!==null?` · ${d.roadScore}/100`:''}`);
 lines.push('',`${lang3('Prossimo obiettivo','Next objective','L-għan li jmiss')}: ${next.title}`,next.detail,'',lang3('Questo report mostra solo evidenze realmente registrate in MDM. Non è una certificazione ufficiale, non garantisce il superamento dell’esame e non sostituisce l’istruttore.','This report shows only evidence actually recorded in MDM. It is not an official certification, does not guarantee exam success and does not replace the instructor.','Dan ir-rapport juri biss evidenza verament irreġistrata f’MDM. Mhuwiex ċertifikazzjoni uffiċjali, ma jiggarantixxix suċċess fl-eżami u ma jissostitwixxix lill-istruttur.'));
 return lines.join('\n');
}
