function bindSchoolOperations(){
 bindSchoolOperationsProduction();
 const create=$('#schoolOpsCreateBooking');
 if(create)create.onclick=()=>{
  const date=$('#schoolOpsDate')?.value||'',time=$('#schoolOpsTime')?.value||'',startAt=schoolOperationsDateTimeValue(date,time);
  if(!startAt)return toast(lang3('Inserisci data e ora reali.','Enter a real date and time.','Daħħal data u ħin reali.'));
  const data=schoolOperationsLoad(); const booking={id:schoolOperationsId('BK'),date,time,startAt,duration:Number($('#schoolOpsDuration')?.value||60),type:$('#schoolOpsType')?.value||'practical',instructor:String($('#schoolOpsInstructor')?.value||'').trim(),note:String($('#schoolOpsBookingNote')?.value||'').trim(),status:'booked',createdAt:Date.now()};
  data.bookings.unshift(booking); schoolOperationsAudit(data,'booking-created',lang3('Prenotazione locale registrata','Local booking recorded','Ibbukkjar lokali rreġistrat'),booking.id); schoolOperationsSave(data); toast(lang3('Prenotazione locale registrata.','Local booking recorded.','Ibbukkjar lokali rreġistrat.')); render();
 };
 screen.querySelectorAll('[data-school-ops-reminder]').forEach(button=>button.onclick=()=>{const d=schoolOperationsLoad(),b=d.bookings.find(x=>x.id===button.dataset.schoolOpsReminder);if(!b)return;schoolOperationsCopy(schoolOperationsReminderText(b),lang3('Promemoria copiato. Nessun invio automatico.','Reminder copied. Nothing was sent automatically.','It-tfakkira ġiet ikkupjata. Ma ntbagħat xejn awtomatikament.'))});
 screen.querySelectorAll('[data-school-ops-complete]').forEach(button=>button.onclick=()=>{const d=schoolOperationsLoad(),b=d.bookings.find(x=>x.id===button.dataset.schoolOpsComplete);if(!b)return;b.status='completed';b.completedAt=Date.now();schoolOperationsAudit(d,'booking-completed',lang3('Lezione segnata come completata','Lesson marked completed','Lezzjoni mmarkata bħala kompluta'),b.id);schoolOperationsSave(d);toast(lang3('Lezione completata.','Lesson completed.','Lezzjoni kompluta.'));render()});
 screen.querySelectorAll('[data-school-ops-cancel]').forEach(button=>button.onclick=()=>{const d=schoolOperationsLoad(),b=d.bookings.find(x=>x.id===button.dataset.schoolOpsCancel);if(!b)return;if(!confirm(lang3('Cancellare questa prenotazione locale? Il record resterà nella traccia operativa.','Cancel this local booking? The record will remain in the operations trail.','Tikkanċella dan l-ibbukkjar lokali? Ir-rekord jibqa’ fit-traċċa operattiva.')))return;b.status='cancelled';b.cancelledAt=Date.now();schoolOperationsAudit(d,'booking-cancelled',lang3('Prenotazione cancellata','Booking cancelled','Ibbukkjar ikkanċellat'),b.id);schoolOperationsSave(d);toast(lang3('Prenotazione cancellata.','Booking cancelled.','Ibbukkjar ikkanċellat.'));render()});
 const savePayment=$('#schoolOpsSavePayment'); if(savePayment)savePayment.onclick=()=>{const bookingId=$('#schoolOpsPaymentBooking')?.value||'',amount=String($('#schoolOpsPaymentAmount')?.value||'').trim(),status=$('#schoolOpsPaymentStatus')?.value||'pending';if(!bookingId)return toast(lang3('Seleziona prima una lezione.','Select a lesson first.','L-ewwel agħżel lezzjoni.'));const d=schoolOperationsLoad();if(!d.bookings.some(b=>b.id===bookingId))return;const payment={id:schoolOperationsId('PAY'),bookingId,amount,status,at:Date.now(),source:'manual-external-confirmation'};d.payments.unshift(payment);schoolOperationsAudit(d,'payment-status','',bookingId,{status});schoolOperationsSave(d);toast(lang3('Stato pagamento salvato. Nessun denaro è stato mosso.','Payment status saved. No money was moved.','L-istat tal-ħlas ġie ssejvjat. Ma ċċaqlaq ebda flus.'));render()};
 const addCrm=$('#schoolOpsAddCrm'); if(addCrm)addCrm.onclick=()=>{const note=String($('#schoolOpsCrmNote')?.value||'').trim(),date=$('#schoolOpsCrmDate')?.value||'',followUpAt=date?new Date(`${date}T09:00:00`).getTime():null;if(!note||!followUpAt)return toast(lang3('Inserisci nota e data del follow-up.','Enter a note and follow-up date.','Daħħal nota u data tal-follow-up.'));const d=schoolOperationsLoad(),item={id:schoolOperationsId('CRM'),note,followUpAt,status:'open',createdAt:Date.now()};d.crm.unshift(item);schoolOperationsAudit(d,'crm-followup',lang3('Follow-up CRM aggiunto','CRM follow-up added','Follow-up CRM miżjud'),item.id);schoolOperationsSave(d);toast(lang3('Follow-up aggiunto.','Follow-up added.','Follow-up miżjud.'));render()};
 screen.querySelectorAll('[data-school-ops-crm-close]').forEach(button=>button.onclick=()=>{const d=schoolOperationsLoad(),n=d.crm.find(x=>x.id===button.dataset.schoolOpsCrmClose);if(!n)return;n.status='closed';n.closedAt=Date.now();schoolOperationsAudit(d,'crm-closed',lang3('Follow-up CRM chiuso','CRM follow-up closed','Follow-up CRM magħluq'),n.id);schoolOperationsSave(d);toast(lang3('Follow-up chiuso.','Follow-up closed.','Follow-up magħluq.'));render()});
}
