function securityTrustStorageTest(iterations=250){
 const key='__mdm_security_storage_probe__';
 const start=performance.now();
 try{
  for(let i=0;i<iterations;i++){
   const value=JSON.stringify({i,t:'MDM',v:[i,i+1,i+2]});
   localStorage.setItem(key,value);
   const back=JSON.parse(localStorage.getItem(key)||'{}');
   if(back.i!==i||back.t!=='MDM')throw new Error('roundtrip');
  }
  localStorage.removeItem(key);
  return {pass:true,iterations,ms:Math.max(0,Math.round((performance.now()-start)*10)/10)};
 }catch(_){
  try{localStorage.removeItem(key)}catch{}
  return {pass:false,iterations:0,ms:Math.max(0,Math.round((performance.now()-start)*10)/10)};
 }
}
async function securityTrustCryptoTest(){
 try{
  if(!crypto?.subtle)return false;
  const input=new TextEncoder().encode(`MDM:${BUILD_VERSION}:${location.origin}`);
  const digest=await crypto.subtle.digest('SHA-256',input);
  return Boolean(digest&&digest.byteLength===32);
 }catch(_){return false}
}
function securityTrustConfiguredKeySafe(){
 try{
  const k=String(mdmBackendSetup?.publishableKey||'').trim();
  if(!k)return false;
  if(/^sb_secret_/i.test(k))return false;
  if(/service[_-]?role/i.test(k))return false;
  if(/^sb_publishable_/i.test(k))return true;
  if(/^eyJ[A-Za-z0-9_-]+\./.test(k)){
   try{
    const payload=JSON.parse(atob(k.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));
    return String(payload?.role||'').toLowerCase()!=='service_role';
   }catch(_){return true}
  }
  return false;
 }catch(_){return false}
}
function securityTrustCspActive(){
 const el=document.querySelector('meta[http-equiv="Content-Security-Policy"]');
 const c=String(el?.content||'').toLowerCase();
 return c.includes("object-src 'none'")&&c.includes("script-src 'self'")&&!c.includes("script-src 'self' 'unsafe-inline'");
}
