 securityTrustState.storagePass=storage.pass;
 securityTrustState.storageIterations=storage.iterations;
 securityTrustState.storageMs=storage.ms;
 securityTrustState.cryptoPass=await securityTrustCryptoTest();
 securityTrustState.checkedAt=new Date().toISOString();
 securityTrustState.serverChecked=false;
 securityTrustState.serverOk=false;
 securityTrustState.serverMessage='';
 if(!mdmAuthSummary().authenticated){
  securityTrustState.serverMessage=lang3('Audit locale completato. Accedi per eseguire le prove server.','Local audit complete. Sign in to run server proofs.','L-audit lokali tlesta. Idħol biex tmexxi l-provi tas-server.');
  securityTrustSave();render();toast(securityTrustState.serverMessage);return;
 }
 if(!(await mdmEnsureFreshAuthForData())){
  securityTrustState.serverMessage=lang3('Sessione server non valida. Accedi di nuovo.','Server session invalid. Sign in again.','Is-sessjoni tas-server mhix valida. Erġa’ idħol.');
  securityTrustSave();render();toast(securityTrustState.serverMessage);return;
 }
 try{
  let sec=await mdmDataRpc('mdm_security_stability_status',{});
  if(sec.status===401&&mdmAuthSession.refreshToken&&await mdmAuthRefreshSession())sec=await mdmDataRpc('mdm_security_stability_status',{});
  const data=mdmAuthParse(sec.body)||{};
  securityTrustState.serverChecked=true;
  securityTrustState.serverOk=sec.status>=200&&sec.status<300&&data.ok!==false&&String(data.security_revision||'')==='45.8.29.0';
  securityTrustState.securityRevision=String(data.security_revision||'');
  securityTrustState.tablesExpected=Number(data.tables_expected||0);
  securityTrustState.tablesPresent=Number(data.tables_present||0);
  securityTrustState.rlsEnabled=Number(data.rls_enabled||0);
  securityTrustState.anonTableGrants=Number(data.anon_table_grants||0);
  securityTrustState.criticalFunctionsExpected=Number(data.critical_functions_expected||0);
  securityTrustState.criticalFunctionsFound=Number(data.critical_functions_found||0);
  securityTrustState.anonExecutableCriticalFunctions=Number(data.anon_executable_critical_functions||0);
  securityTrustState.securityDefinerUnsafeSearchPath=Number(data.security_definer_without_explicit_search_path||0);
  securityTrustState.serverMessage=securityTrustState.serverOk?lang3('Security posture server verificata.','Server security posture verified.','Il-qagħda tas-sigurtà tas-server ġiet ivverifikata.'):(mdmDataErrorMessage(sec)||String(data.error||'security_posture_not_ready'));

  let perm=await mdmDataRpc('mdm_production_permission_status',{});
  if(perm.status===401&&mdmAuthSession.refreshToken&&await mdmAuthRefreshSession())perm=await mdmDataRpc('mdm_production_permission_status',{});
  const pd=mdmAuthParse(perm.body)||{};
  securityTrustState.permissionRevision=String(pd.permission_revision||'');
  securityTrustState.permissionOk=perm.status>=200&&perm.status<300&&pd.ok!==false&&securityTrustState.permissionRevision==='45.8.28.4';

  let ops=await mdmDataRpc('mdm_school_operations_sync_status',{});
  if(ops.status===401&&mdmAuthSession.refreshToken&&await mdmAuthRefreshSession())ops=await mdmDataRpc('mdm_school_operations_sync_status',{});
  const od=mdmAuthParse(ops.body)||{};
  securityTrustState.schoolOpsSchema=String(od.schema_version||'');
  securityTrustState.schoolOpsCanRead=Boolean(od.can_read);
  securityTrustState.schoolOpsCanWrite=Boolean(od.can_write);

  if(typeof mdmProductionPermissionProbe==='function')await mdmProductionPermissionProbe({silent:true});
  if(typeof schoolOperationsProductionProbe==='function')await schoolOperationsProductionProbe({silent:true});
 }catch(e){
  securityTrustState.serverChecked=true;
  securityTrustState.serverOk=false;
  securityTrustState.serverMessage=String(e?.message||e||'audit_failed');
 }
 securityTrustState.lastReport=securityTrustReportText();
