function investorProductionCceInstalledCount(pack){
 /* Build 45.8.26.1 — C/CE proof fix.
    C/CE is loaded by its dedicated runtime before the main app. On some iPhone/Koder
    sessions the legacy CCE_Q snapshot can be empty even though the dedicated C/CE
    payload and its 386 canonical IDs are present. For Investor Proof we therefore
    verify the dedicated runtime directly, without changing the C/CE bank itself. */
 try{
  const ids=Array.isArray(window.MDM_CCE_IMPORTED_IDS)?window.MDM_CCE_IMPORTED_IDS:[];
  const uniqueIds=new Set(ids.map(id=>String(id||'')).filter(Boolean)).size;
  const runtimeQ=Array.isArray(window.MDM_CCE_Q)?new Set(window.MDM_CCE_Q.map(q=>String(q?.id||'')).filter(Boolean)).size:0;
  const all=Array.isArray(window.LPTV_QUESTIONS)?window.LPTV_QUESTIONS:[];
  const liveIds=uniqueIds?new Set(all.filter(q=>ids.includes(String(q?.id||''))).map(q=>String(q?.id||''))).size:0;
  const meta=window.MDM_CCE_IMPORT_META||{};
  const metadataCount=(meta.complete===true&&Number(meta.officialTotal)===386)?Number(meta.imported||0):0;
  const packCount=(pack?.payloadInstalled===true&&pack?.status==='verified'&&pack?.questionBank?.canonicalVerificationComplete===true)?Number(pack?.questionBank?.importedRuntimeCount||pack?.questionBank?.currentCanonicalMatches||0):0;
  return Math.max(runtimeQ,liveIds,uniqueIds,metadataCount,packCount);
 }catch(_){return 0}
}
function investorProductionPackProof(){
 const expected={'MT-LPTV':250,'MT-B':444,'MT-A':391,'MT-C-CE':386,'MT-D':208};
 const rows=[];
 for(const [id,count] of Object.entries(expected)){
  let pack=null,installed=0,active=false;
  try{
   pack=window.LicensePacks?.get(id);
   installed=id==='MT-C-CE'?investorProductionCceInstalledCount(pack):licensePackInstalledCount(pack);
   active=Boolean(window.LicensePacks?.activatable(pack));
  }catch{}
  rows.push({id,expected:count,installed:Number(installed||0),pass:Number(installed||0)===count&&active});
 }
 return rows;
}
