function investorProductionCopy(text,success){const fallback=()=>{try{const ta=document.createElement('textarea');ta.value=text;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();toast(success)}catch{toast(lang3('Copia non disponibile.','Copy unavailable.','Il-kopja mhix disponibbli.'))}};if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>toast(success)).catch(fallback);else fallback()}
function bindInvestorProduction(){
 const copy=$('#investorProdCopy');if(copy)copy.onclick=()=>investorProductionCopy(investorProductionReportText(),lang3('Readiness report copiato.','Readiness report copied.','Readiness report ġie kkupjat.'));
 const share=$('#investorProdShare');if(share)share.onclick=async()=>{const text=investorProductionReportText();if(navigator.share){try{await navigator.share({title:'MDM Investor Proof & Production Readiness',text});return}catch(e){if(e&&e.name==='AbortError')return}}investorProductionCopy(text,lang3('Condivisione non disponibile: readiness report copiato.','Sharing unavailable: readiness report copied.','Il-qsim mhux disponibbli: readiness report ġie kkupjat.'))};
}
