function buildExam(){
 const exam=countryPackExamConfig(),quotas=exam.quotas||{},target=Math.max(1,Number(exam.questionCount)||35);
 const selected=[],used=new Set();
 for(const [topic,amountRaw] of Object.entries(quotas)){
   const amount=Math.max(0,Number(amountRaw)||0),pool=shuffle(Q.filter(q=>topicIdFor(q)===topic));
   for(const q of pool){
     if(selected.filter(x=>topicIdFor(x)===topic).length>=amount)break;
     if(!used.has(q.id)){used.add(q.id);selected.push(q)}
   }
 }
 const remaining=shuffle(Q.filter(q=>!used.has(q.id)));
 while(selected.length<target&&remaining.length)selected.push(remaining.shift());
 return shuffle(selected).slice(0,target);
}
