 const words=settings.lang==='it'?GLOSSARY.filter(x=>(x.term+' '+x.it+' '+x.example+' '+x.example_it).toLowerCase().includes(term)).slice(0,8):[];
 const rs=C.regulations.filter(x=>(x.en+' '+x.it+' '+x.mt+' '+x.desc_en+' '+x.desc_it+' '+(x.desc_mt||'')).toLowerCase().includes(term));
 const topics=C.roadCode.filter(x=>(x.en+' '+x.it+' '+x.mt+' '+x.summary_en+' '+x.summary_it+' '+(x.summary_mt||'')).toLowerCase().includes(term));
 const html=[...words.map(x=>`<article class="list-card"><span class="list-icon">🔤</span><div><span class="badge">${esc(t('englishCoach'))}</span><h3>${esc(x.term)} — ${esc(x.it)}</h3><p>${esc(x.example)}</p></div></article>`),...qs.map(q=>`<button class="list-card" data-qid="${esc(q.id)}"><span class="list-icon">?</span><div><span class="badge">${esc(questionCategory(q))}</span><h3>${esc(questionText(q))}</h3>${isItalianAssisted()?`<p>${esc(q.question_it)}</p>`:''}</div><span class="chev">›</span></button>`),...topics.map(x=>`<button class="list-card" data-road="${esc(x.id)}"><span class="list-icon">${x.icon}</span><div><h3>${esc(x[settings.lang]||x.en)}</h3><p>${esc(localized(x,'summary'))}</p></div></button>`),...rs.map(x=>`<article class="list-card"><span class="list-icon">${x.icon}</span><div><h3>${esc(x[settings.lang]||x.en)}</h3><p>${esc(localized(x,'desc'))}</p><a class="source-link" href="${esc(x.url)}" target="${location.hostname==="localhost"?"_self":"_blank"}" rel="noopener">${esc(t('openSource'))} ↗</a></div></article>`)].join('');
 box.innerHTML=html||`<p class="muted">${esc(t('noResults'))}</p>`;box.querySelectorAll('[data-qid]').forEach(b=>b.onclick=()=>startQuiz([Q.find(q=>q.id===b.dataset.qid)],'guided'));box.querySelectorAll('[data-road]').forEach(b=>b.onclick=()=>showRoad(b.dataset.road))
